	"UserID" varchar(50) NULL,
	"txnCategory" varchar(50) NULL,
	"txnType" varchar(10) NULL,
	"txnID" varchar(50) NOT NULL,
	"txnDate" timestamp NULL,
	"txnAmount" numeric(21, 2) NULL,
	"txnReference" varchar(500) NULL,
	"txnSender" varchar(50) NULL,
	"txnReceiver" varchar(50) NULL,
	"txnCSAccNum" varchar(50) NULL,
	"txnCSTransType" varchar(20) NULL,
	CONSTRAINT "PKey" PRIMARY KEY ("txnID")
);
CREATE INDEX "Hist_User_Date" ON "CSHistoricalData"."CSHistData" USING btree ("UserID", "txnDate") INCLUDE ("txnCategory", "txnCSAccNum") WITH (fillfactor='70');
CREATE INDEX cshistdata_txndate_idx ON "CSHistoricalData"."CSHistData" USING btree ((("txnDate")::date));
CREATE INDEX cshistdata_userid_idx ON "CSHistoricalData"."CSHistData" USING btree ("UserID");

