-- dashboard.glsummary definition

-- Drop table

-- DROP TABLE dashboard.glsummary;

CREATE TABLE dashboard.glsummary (
	wallettypeid varchar NULL,
	currencyid varchar NULL,
	instancetype varchar NULL,
	creditamount numeric(25, 6) NULL,
	debitamount numeric(25, 6) NULL,
	totalbalance numeric(25, 6) NULL,
	creditamounttoday numeric(25, 6) NULL,
	debitamounttoday numeric(25, 6) NULL,
	summarydate timestamp NULL
);

		-- Foreign Tables
		-- Views

-- dashboard.activecustomerreport source

CREATE OR REPLACE VIEW dashboard.activecustomerreport
AS SELECT usr.id,
    wb.walletno AS bankaccountid,
    usr.createdon::timestamp(0) without time zone AS registrationdate,
    usr.firstname,
    usr.middlename AS othername,
    usr.lastname,
    usr.mobilenumber,
    max(wt.txtime::timestamp(0) without time zone) AS transactiondateandtime,
    count(wt.id) AS totaltransactions
   FROM users usr
     JOIN wallettransactions wt ON usr.id::text = wt.fromortouserid::text
     JOIN walletbalance wb ON usr.id::text = wb.ownerid::text
  WHERE wb.producttype::text = 'WALLET'::text
  GROUP BY usr.id, wb.walletno;


-- dashboard.adtrailreport source

CREATE OR REPLACE VIEW dashboard.adtrailreport
AS SELECT innerquery.username,
    'First Name'::text AS modulename,
        CASE
            WHEN innerquery.prev_value::text = ''::text THEN 'Add'::text
            WHEN innerquery.new_value::text = ''::text THEN 'Delete'::text
            ELSE 'Edit'::text
        END AS userevent,
        CASE
            WHEN innerquery.prev_value::text = ''::text THEN innerquery.new_value::text
            WHEN innerquery.new_value::text = ''::text THEN innerquery.prev_value::text
            ELSE concat(innerquery.prev_value, '->', innerquery.new_value)
        END AS actionperformed,
    innerquery.lastmodifiedbyipaddress AS ipaddress,
    innerquery.modifiedon AS "timestamp"
   FROM ( SELECT usersaudit.username,
            lead(usersaudit.firstname) OVER (PARTITION BY usersaudit.username ORDER BY usersaudit.modifiedon) AS new_value,
            usersaudit.firstname AS prev_value,
            usersaudit.lastmodifiedbyipaddress,
            usersaudit.modifiedon::timestamp(0) without time zone AS modifiedon
           FROM usersaudit) innerquery
  WHERE innerquery.prev_value::text <> innerquery.new_value::text
UNION ALL
 SELECT innerquery.username,
    'Middle Name'::text AS modulename,
        CASE
            WHEN innerquery.prev_value::text = ''::text THEN 'Add'::text
            WHEN innerquery.new_value::text = ''::text THEN 'Delete'::text
            ELSE 'Edit'::text
        END AS userevent,
        CASE
            WHEN innerquery.prev_value::text = ''::text THEN innerquery.new_value::text
            WHEN innerquery.new_value::text = ''::text THEN innerquery.prev_value::text
            ELSE concat(innerquery.prev_value, '->', innerquery.new_value)
        END AS actionperformed,
    innerquery.lastmodifiedbyipaddress AS ipaddress,
    innerquery.modifiedon AS "timestamp"
   FROM ( SELECT usersaudit.username,
            lead(usersaudit.middlename) OVER (PARTITION BY usersaudit.username ORDER BY usersaudit.modifiedon) AS new_value,
            usersaudit.middlename AS prev_value,
            usersaudit.lastmodifiedbyipaddress,
            usersaudit.modifiedon::timestamp(0) without time zone AS modifiedon
           FROM usersaudit) innerquery
  WHERE innerquery.prev_value::text <> innerquery.new_value::text
UNION ALL
 SELECT innerquery.username,
    'Last Name'::text AS modulename,
        CASE
            WHEN innerquery.prev_value::text = ''::text THEN 'Add'::text
            WHEN innerquery.new_value::text = ''::text THEN 'Delete'::text
            ELSE 'Edit'::text
        END AS userevent,
        CASE
