    'First Name'::text AS modulename,
        CASE
            WHEN innerquery.prev_value::text = ''::text THEN 'Add'::text
            WHEN innerquery.new_value::text = ''::text THEN 'Delete'::text
            ELSE 'Edit'::text
        END AS userevent,
        CASE
            WHEN innerquery.prev_value::text = ''::text THEN innerquery.new_value::text
