            lead(usersaudit.userstatus) OVER (PARTITION BY usersaudit.username ORDER BY usersaudit.modifiedon) AS new_value,
            usersaudit.userstatus AS prev_value,
            usersaudit.lastmodifiedbyipaddress,
            usersaudit.modifiedon::timestamp(0) without time zone AS modifiedon
           FROM usersaudit) innerquery
  WHERE innerquery.prev_value::text <> innerquery.new_value::text
UNION ALL
 SELECT innerquery.username,
    'KYC Status'::text AS modulename,
        CASE
            WHEN innerquery.prev_value::text = ''::text THEN 'Add'::text
            WHEN innerquery.new_value::text = ''::text THEN 'Delete'::text
            ELSE 'Edit'::text
        END AS userevent,
        CASE
            WHEN innerquery.prev_value::text = ''::text THEN innerquery.new_value::text
            WHEN innerquery.new_value::text = ''::text THEN innerquery.prev_value::text
            ELSE concat(innerquery.prev_value, '->', innerquery.new_value)
        END AS actionperformed,
    innerquery.lastmodifiedbyipaddress AS ipaddress,
    innerquery.modifiedon AS "timestamp"
   FROM ( SELECT usersaudit.username,
            lead(usersaudit.kycstatus) OVER (PARTITION BY usersaudit.username ORDER BY usersaudit.modifiedon) AS new_value,
            usersaudit.kycstatus AS prev_value,
            usersaudit.lastmodifiedbyipaddress,
            usersaudit.modifiedon::timestamp(0) without time zone AS modifiedon
           FROM usersaudit) innerquery
  WHERE innerquery.prev_value::text <> innerquery.new_value::text;


