-- dashboard.backofficeuserreport source

CREATE OR REPLACE VIEW dashboard.backofficeuserreport
AS SELECT u.createdon::timestamp(0) without time zone AS createdondate,
    u.firstname,
    u.lastname,
    u.email,
    u.username,
    u.lastlogin::timestamp(0) without time zone AS lastlogindate,
    u.roletype,
    u.userstatus,
    u.remarks,
    u.ldapuser,
    r.name AS "role name"
   FROM users u
     JOIN role r ON u.roleid::text = r.id::text
  WHERE u.roletype::text = 'OPERATION'::text;


-- dashboard.c2breconreport source

CREATE OR REPLACE VIEW dashboard.c2breconreport
AS SELECT date(w.createdon) AS date,
    w.txtime::timestamp(0) without time zone::time without time zone AS "time",
    c2b.mpesareceiptnumber AS mpesaref,
    concat(w.businesstrxid, ' / ', w.executionid) AS trxbatchid,
    round(w.creditamount + w.debitamount, 2) AS trxamount,
        CASE
            WHEN w.creditamount > 0::numeric THEN 'Credit'::text
            ELSE 'Debit'::text
        END AS transactiontype,
        CASE
            WHEN w.description IS NULL OR w.description::text = ''::text THEN bp.name
            ELSE w.description
        END AS transactionnarration,
    wt.glaccountnumber AS glid,
    array_to_json(ARRAY[to_json(c2b.paymentrequest::json -> 'phoneNumber'::text)]) ->> 0 AS mobile
   FROM mpesac2bpayment c2b
     JOIN wallettransactions w ON c2b.externalrefid::text = w.externalrefid::text
     LEFT JOIN wallettype wt ON w.wallettypeid::text = wt.id::text
     LEFT JOIN businessproduct bp ON w.businessproductid::text = bp.id::text
  WHERE c2b.callbackresultcode::text = '0.0'::text
  ORDER BY w.createdon DESC;


-- dashboard.cdscoringreport source

CREATE OR REPLACE VIEW dashboard.cdscoringreport
AS SELECT concat('254', usr.username) AS mobilenumber,
    usr.idnumber,
    usr.createdon::timestamp(0) without time zone AS createdon,
        CASE
            WHEN cl.creditlimit > 0::numeric THEN concat('Limit Asigned (', round(cl.creditlimit, 2), ')')
            ELSE 'Limit NOT Assigned'::text
        END AS status,
        CASE
            WHEN cl.creditlimit > 1000::numeric THEN concat('Hello ', usr.firstname, ' You are qualified to get a loan upto ', round(cl.creditlimit, 2))
            ELSE concat('Hello ', usr.firstname, ' you do not qualify for a Timiza loan at the moment.')
        END AS result,
        CASE
            WHEN count(l.userid) > 1 THEN 'Repeat'::text
            ELSE 'New'::text
        END AS newrepeatcustomer
   FROM users usr
     JOIN role rl ON usr.roleid::text = rl.id::text
     LEFT JOIN creditlimit cl ON usr.id::text = cl.userid::text
     LEFT JOIN loan l ON usr.id::text = l.userid::text
  WHERE rl.roletype::text <> 'OPERATION'::text
  GROUP BY (concat('254', usr.username)), usr.idnumber, (usr.createdon::timestamp(0) without time zone), (
        CASE
            WHEN cl.creditlimit > 0::numeric THEN concat('Limit Asigned (', round(cl.creditlimit, 2), ')')
            ELSE 'Limit NOT Assigned'::text
        END), (
        CASE
            WHEN cl.creditlimit > 1000::numeric THEN concat('Hello ', usr.firstname, ' You are qualified to get a loan upto ', round(cl.creditlimit, 2))
            ELSE concat('Hello ', usr.firstname, ' you do not qualify for a Timiza loan at the moment.')
        END);


-- dashboard.claimstatusreport source

CREATE OR REPLACE VIEW dashboard.claimstatusreport
AS SELECT bulkinsuranceclaim.customerfullname,
    bulkinsuranceclaim.claimreporteddate::timestamp(0) without time zone AS claimreporteddate,
    bulkinsuranceclaim.claimreceiveddatebyinsurancecompany::timestamp(0) without time zone AS claimreceiveddatebyinsurancecompany,
    bulkinsuranceclaim.claimpaiddate::timestamp(0) without time zone AS claimpaiddate,
    bulkinsuranceclaim.claimstatus,
    bulkinsuranceclaim.claimreason,
    bulkinsuranceclaim.mobilenumber
   FROM bulkinsuranceclaim;


-- dashboard.crbhitsreport source

CREATE OR REPLACE VIEW dashboard.crbhitsreport
AS SELECT
        CASE
            WHEN webserviceintegrationrecord.status::text ~~ 'SUCCESS'::text THEN 'Successful Response'::character varying
            ELSE webserviceintegrationrecord.applicationerrormessage
        END AS description,
    date(webserviceintegrationrecord.reuestedon) AS requestdate,
    count(webserviceintegrationrecord.id) AS count
   FROM webserviceintegrationrecord
  WHERE webserviceintegrationrecord.integrationname::text = 'CRB_INFO_HANDLER'::text
  GROUP BY (
        CASE
            WHEN webserviceintegrationrecord.status::text ~~ 'SUCCESS'::text THEN 'Successful Response'::character varying
            ELSE webserviceintegrationrecord.applicationerrormessage
        END), (date(webserviceintegrationrecord.reuestedon));


-- dashboard.crbreport source

CREATE OR REPLACE VIEW dashboard.crbreport
AS SELECT usr.lastname AS surname,
    usr.firstname AS forename1,
    usr.middlename AS forename2,
    ''::text AS forename3,
    ''::text AS tradingas,
    to_char(usr.dob::date::timestamp with time zone, 'yyyymmdd'::text) AS date_of_birth,
    usr.username AS client_number,
    l.accountnumber,
        CASE
            WHEN usr.gender::text = 'MALE'::text THEN 'M'::character varying
            WHEN usr.gender::text = 'FEMALE'::text THEN 'F'::character varying
            ELSE usr.gender
        END AS gender,
    'KE'::text AS nationality,
        CASE
            WHEN usr.idtype::text = 'NATIONAL_ID'::text THEN '001'::character varying
            WHEN usr.idtype::text = 'PASSPORT'::text THEN '002'::character varying
            WHEN usr.idtype::text = 'ALIEN_REGISTRATION'::text THEN '003'::character varying
            WHEN usr.idtype::text = 'SERVICE_ID'::text THEN '004'::character varying
            ELSE usr.idtype
        END AS primaryid_type,
    usr.idnumber AS primaryid_num,
    concat('254', usr.username) AS mobilenumber,
    'I'::text AS accountproducttype,
    to_char(l.expectedfirstrepaymentdate::date::timestamp with time zone, 'yyyymmdd'::text) AS installment_due_date,
    round(l.principaldisbursed, 2) * 100::numeric AS originalamount,
    'KES'::text AS currencyoffacility,
    round(l.totalamountoutstanding, 2) * 100::numeric AS current_balance_inkes,
    round(l.totalamountoutstanding, 2) * 100::numeric AS current_balance,
    ( SELECT round(loan.totalamountoutstanding, 2) * 100::numeric AS round
           FROM loan
          WHERE loan.accountnumber::text = l.accountnumber::text AND loan.expectedfirstrepaymentdate < now()) AS overdue_balance,
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN ' '::text
            WHEN l.calucatedclosedate < date(now()) THEN to_char((l.calucatedclosedate::date + 1)::timestamp with time zone, 'yyyymmdd'::text)
            ELSE ' '::text
        END AS overdue_date,
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::double precision
            WHEN date_part('days'::text, age(l.expectedfirstrepaymentdate::timestamp with time zone, now())) > 0::double precision THEN 0::double precision
            ELSE date_part('days'::text, age(l.expectedfirstrepaymentdate::timestamp with time zone, now())) * '-1'::integer::double precision
        END AS days_in_arrears,
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::double precision
            WHEN date_part('days'::text, age(l.expectedfirstrepaymentdate::timestamp with time zone, now())) > 0::double precision THEN 0::double precision
            ELSE 1::double precision
        END AS noofinstallmentinarrears,
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 'A'::text
            WHEN round(lb.currentbucketnumber, 0) = '1'::numeric THEN 'B'::text
            WHEN round(lb.currentbucketnumber, 0) = '2'::numeric THEN 'C'::text
            WHEN round(lb.currentbucketnumber, 0) = '3'::numeric THEN 'D'::text
            ELSE 'E'::text
        END AS "Prudential Risk Classification",
        CASE
            WHEN l.loanstatus::text = 'ACTIVE'::text THEN 'F'::text
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 'A'::text
            ELSE 'C'::text
        END AS accountstatus,
        CASE
            WHEN l.loanstatus::text = 'ACTIVE'::text THEN to_char(l.createdon::date::timestamp with time zone, 'yyyymmdd'::text)
            ELSE to_char(l.modifiedon::date::timestamp with time zone, 'yyyymmdd'::text)
        END AS accountstatusdate,
    1 AS repaymentperiod,
    to_char(l.actualdisbursementdate::date::timestamp with time zone, 'yyyymmdd'::text) AS disbursement_date,
    round(l.totalexpectedcostofloan + l.chargescharged, 2) * 100::numeric AS installment_amount,
        CASE
            WHEN l.lastpaidon IS NULL THEN ' '::text
            ELSE to_char(l.lastpaidon::date::timestamp with time zone, 'yyyymmdd'::text)
        END AS latest_pymt_date,
    round(l.lastinstallmentamount, 2) * 100::numeric AS latest_pymt_amt
   FROM users usr
     JOIN loan l ON usr.id::text = l.userid::text
     LEFT JOIN userkycdetails ukyc ON usr.id::text = ukyc.userid::text
     LEFT JOIN loanbucket lb ON l.id::text = lb.loanid::text
     LEFT JOIN loanproduct lp ON l.loanproductid::text = lp.id::text
     JOIN creditlimit cl ON l.userid::text = cl.userid::text
     JOIN walletbalance wt ON usr.id::text = wt.ownerid::text
  WHERE wt.producttype::text = 'WALLET'::text;


-- dashboard.creditlimitpendingcount source

CREATE OR REPLACE VIEW dashboard.creditlimitpendingcount
AS SELECT cl.id,
    cl.userid,
    cl.creditlimit,
    cl.creditlimittype,
    cl.loanterm,
    cl.termtype,
    cl.limitsource,
    cl.limitlastupdatedon,
    cl.limitlastupdatedby,
    cl.termsource,
    cl.termlastupdatedon,
    cl.termlastupdatedby,
    cl.currentbalance,
    cl.limitexpirydate,
    cl.riskcategory,
    cl.createdon,
    cl.modifiedon,
    cl.loantermactual,
    cl.riskvalue,
    cl.model,
    cl.ntbriskmetriccalc,
    cl.mpesaestincome,
    cl.airtimeestincome,
    cl.mpesaweight,
    cl.airtimeweight,
    cl.consolidatedestincome,
    cl.dsrvalue,
    cl.adjustedriskscore,
    cl.validationerrorjson,
    cl.templimitapplicablefrom,
    cl.lastlimitincreasedate,
    cl.updatependingattempts
   FROM creditlimit cl
     JOIN users u ON cl.userid::text = u.id::text AND u.userstatus::text <> 'RECYCLED'::text
  WHERE cl.limitexpirydate >= '2021-05-01 00:00:00'::timestamp without time zone AND date(cl.limitexpirydate) <= (now()::date + 3) AND cl.updatependingattempts < 4 AND (cl.templimitapplicablefrom IS NULL OR cl.templimitapplicablefrom < cl.limitexpirydate) AND cl.creditlimit >= 1000::numeric;


-- dashboard.customerdailyscoringreport source

CREATE OR REPLACE VIEW dashboard.customerdailyscoringreport
AS SELECT concat('254', usr.username) AS mobilenumber,
    usr.idnumber,
    usr.createdon::timestamp(0) without time zone AS createdon,
        CASE
            WHEN cl.creditlimit IS NULL THEN 'Limit NOT Assigned'::text
            WHEN cl.creditlimit = 0.0 THEN 'Limit NOT Assigned'::text
            ELSE concat('Limit Assigned(', round(cl.creditlimit, 2), ')')
        END AS status,
        CASE
            WHEN cl.creditlimit IS NULL THEN 'Limit NOT Assigned'::text
            ELSE 'Limit Assigned'::text
        END AS statusfilter,
        CASE
            WHEN cl.creditlimit IS NULL THEN concat('Hello ', usr.firstname, ' you do no qualify for a Timiza loan at the moment.')
            WHEN cl.creditlimit < 1000::numeric THEN concat('Hello ', usr.firstname, ' you do no qualify for a Timiza loan at the moment.')
            ELSE concat('Hello ', usr.firstname, ' You are qualified to get a loan upto ', round(cl.creditlimit, 2))
        END AS result,
        CASE
            WHEN count(l.userid) > 1 THEN 'Repeat'::text
            ELSE 'New'::text
        END AS newrepeatcust
   FROM users usr
     JOIN role rl ON usr.roleid::text = rl.id::text AND rl.roletype::text <> 'OPERATION'::text
     LEFT JOIN creditlimit cl ON usr.id::text ~~ cl.userid::text
     LEFT JOIN loan l ON usr.id::text ~~ l.userid::text
  GROUP BY (concat('254', usr.username)), usr.idnumber, (usr.createdon::timestamp(0) without time zone), (
        CASE
            WHEN cl.creditlimit IS NULL THEN 'Limit NOT Assigned'::text
            WHEN cl.creditlimit = 0.0 THEN 'Limit NOT Assigned'::text
            ELSE concat('Limit Assigned(', round(cl.creditlimit, 2), ')')
        END), (
        CASE
            WHEN cl.creditlimit IS NULL THEN 'Limit NOT Assigned'::text
            ELSE 'Limit Assigned'::text
        END), (
        CASE
            WHEN cl.creditlimit IS NULL THEN concat('Hello ', usr.firstname, ' you do no qualify for a Timiza loan at the moment.')
            WHEN cl.creditlimit < 1000::numeric THEN concat('Hello ', usr.firstname, ' you do no qualify for a Timiza loan at the moment.')
            ELSE concat('Hello ', usr.firstname, ' You are qualified to get a loan upto ', round(cl.creditlimit, 2))
        END);


-- dashboard.customerdetailsreport source

CREATE OR REPLACE VIEW dashboard.customerdetailsreport
AS SELECT usr.id AS customernumber,
    usr.createdon::timestamp(0) without time zone AS dateopened,
        CASE
            WHEN kyc.title IS NULL THEN ' '::character varying
            ELSE kyc.title
        END AS salutation,
    usr.lastname AS surname,
    usr.firstname,
    usr.middlename AS othername,
    concat(usr.firstname, ' ', usr.middlename, ' ', usr.lastname) AS fullname,
    usr.idnumber AS nationalidorpassportno,
    date(usr.dob) AS dateofbirth,
    usr.gender,
    'KE'::text AS nationality,
    concat('254', usr.username) AS mobilenumber,
    usr.email AS emailaddress,
    usr.address AS address1,
    ' '::text AS address2,
    ' '::text AS address3,
    usr.pincode AS postalcode,
    usr.city AS citytown,
        CASE
            WHEN kyc.createdon IS NULL THEN ' '::text
            ELSE kyc.createdon::timestamp(0) without time zone::text
        END AS createdon,
    ' '::text AS maritalstatus,
        CASE
            WHEN kyc.employmenttype::text ~~ 'Unemployed'::text THEN 'Uneployed'::character varying
            WHEN kyc.employername IS NULL THEN ' '::character varying
            ELSE kyc.employername
        END AS employer,
    usr.idtype AS documenttype,
        CASE
            WHEN cl.creditlimit IS NULL THEN ' '::text
            ELSE round(cl.creditlimit, 2)::text
        END AS creditlimit,
        CASE
            WHEN cl.riskcategory IS NULL THEN ' '::character varying
            ELSE cl.riskcategory
        END AS riskcategory,
    usr.kycstatus
   FROM users usr
     LEFT JOIN userkycdetails kyc ON usr.id::text = kyc.userid::text
     LEFT JOIN creditlimit cl ON usr.id::text = cl.userid::text
     JOIN role rl ON usr.roleid::text = rl.id::text AND rl.roletype::text ~~ 'CUSTOMER'::text;


-- dashboard.customerregistrationreport source

CREATE OR REPLACE VIEW dashboard.customerregistrationreport
AS SELECT usr.createdon::timestamp(0) without time zone AS registrationdateandtime,
    concat('254', usr.username) AS mobilenumber,
    usr.id AS customerid,
    ch.name AS mobileplatform,
    usr.firstname,
    usr.middlename AS othername,
    usr.lastname,
    usr.idnumber,
    date(usr.dob) AS date,
    usr.gender,
    usr.userstatus AS custstatus,
        CASE
            WHEN usr.passwordexpirydate >= now() THEN 'Active'::text
            ELSE 'Expired'::text
        END AS pinstatus
   FROM users usr
     JOIN role rl ON usr.roleid::text = rl.id::text
     LEFT JOIN channel ch ON usr.registrationchannelid::text = ch.id::text
  WHERE rl.roletype::text ~~ 'CUSTOMER'::text;


-- dashboard.fintrxreport source

CREATE OR REPLACE VIEW dashboard.fintrxreport
AS SELECT wtrans.txtime::timestamp(0) without time zone AS date,
    bp.name AS transactiontype,
    usr.username AS bankid,
        CASE
            WHEN wtrans.description IS NULL OR wtrans.description::text = ''::text THEN bp.name
            ELSE wtrans.description
        END AS paymentdetails,
    wtrans.businesstrxid AS trxreference,
    round(wtrans.creditamount, 2) AS amount,
    ( SELECT
                CASE
                    WHEN round(sum(wallettransactions.debitamount), 2) IS NULL THEN 0::numeric
                    ELSE round(sum(wallettransactions.debitamount), 2)
                END AS round
           FROM wallettransactions
          WHERE wallettransactions.executionid::text = wtrans.executionid::text AND wallettransactions.walletinstanceid::text = wtrans.walletinstanceid::text AND wallettransactions.parentid IS NOT NULL) AS transactionfee,
        CASE
            WHEN wtrans.transactionstatus::text = 'PROCESSED'::text THEN 'Success'::text
            ELSE 'Failure'::text
        END AS status,
    'CREDIT'::text AS trxtype,
    usr.username AS customerid,
    ''::character varying AS merchantid,
        CASE
            WHEN wtrans.channelid::text = 'SYSTEM'::text THEN 'SYSTEM'::character varying
            ELSE ch.name
        END AS trxsource,
    usr.firstname,
    usr.lastname,
    concat('254', usr.username) AS mobilenumber,
    wtrans.businesstrxid AS uniqueid,
    ( SELECT wallettype.glaccountnumber
           FROM wallettype
          WHERE wallettype.id::text = ((( SELECT walletbalance.wallettypeid
                   FROM walletbalance
                  WHERE walletbalance.id::text = wtrans.otherwalletinstanceid::text))::text)) AS sourceaccount,
    wb.walletno AS destinationaccount
   FROM wallettransactions wtrans
     LEFT JOIN businessproduct bp ON wtrans.businessproductid::text = bp.id::text
     LEFT JOIN users usr ON wtrans.fromortouserid::text = usr.id::text
     LEFT JOIN walletbalance wb ON usr.id::text = wb.ownerid::text
     LEFT JOIN channel ch ON wtrans.channelid::text = ch.id::text
  WHERE wtrans.parentid IS NULL AND bp.bpcode::text = 'DMPESA'::text AND wtrans.creditamount > 0::numeric AND wb.producttype::text = 'WALLET'::text
UNION ALL
 SELECT wtrans.txtime::timestamp(0) without time zone AS date,
        CASE
            WHEN fsi.receiverpartypublicname IS NULL THEN bp.name::text
            WHEN fsi.requesttype::text = 'B2C'::text THEN bp.name::text
            ELSE concat(bp.name)
        END AS transactiontype,
    usr.username AS bankid,
        CASE
            WHEN fsi.receiverpartypublicname IS NULL THEN bp.name::text
            WHEN fsi.requesttype::text = 'B2C'::text THEN bp.name::text
            ELSE concat(bp.name, '-', fsi.receiverpartypublicname)
        END AS paymentdetails,
    wtrans.businesstrxid AS trxreference,
    round(wtrans.debitamount, 2) AS amount,
    ( SELECT
                CASE
                    WHEN round(sum(wallettransactions.debitamount), 2) IS NULL THEN 0::numeric
                    ELSE round(sum(wallettransactions.debitamount), 2)
                END AS round
           FROM wallettransactions
          WHERE wallettransactions.executionid::text = wtrans.executionid::text AND wallettransactions.walletinstanceid::text = wtrans.walletinstanceid::text AND wallettransactions.parentid IS NOT NULL) AS transactionfee,
        CASE
            WHEN wtrans.transactionstatus::text = 'PROCESSED'::text THEN 'Success'::text
            ELSE 'Failure'::text
        END AS status,
    'DEBIT'::text AS trxtype,
    usr.username AS customerid,
        CASE
            WHEN fsi.requesttype::text = 'B2C'::text THEN ''::character varying
            WHEN fsi.receiverpartypublicname IS NULL THEN ''::character varying
            ELSE fsi.receiverpartypublicname
        END AS merchantid,
        CASE
            WHEN wtrans.channelid::text = 'SYSTEM'::text THEN 'SYSTEM'::character varying
            ELSE ch.name
        END AS trxsource,
    usr.firstname,
    usr.lastname,
    concat('254', usr.username) AS mobilenumber,
    wtrans.businesstrxid AS uniqueid,
    wb.walletno AS sourceaccount,
    ( SELECT wallettype.glaccountnumber
           FROM wallettype
          WHERE wallettype.id::text = ((( SELECT walletbalance.wallettypeid
                   FROM walletbalance
                  WHERE walletbalance.id::text = wtrans.otherwalletinstanceid::text))::text)) AS destinationaccount
   FROM wallettransactions wtrans
     LEFT JOIN businessproduct bp ON wtrans.businessproductid::text = bp.id::text
     LEFT JOIN users usr ON wtrans.fromortouserid::text = usr.id::text
     LEFT JOIN mpesafsi fsi ON wtrans.externalrefid::text = fsi.originatorconversationid::text
     JOIN walletbalance wb ON usr.id::text = wb.ownerid::text
     LEFT JOIN channel ch ON wtrans.channelid::text = ch.id::text
  WHERE wtrans.parentid IS NULL AND (bp.bpcode::text <> ALL (ARRAY['DMPESA'::character varying::text, 'SNDMNY'::character varying::text])) AND wtrans.debitamount > 0::numeric AND wb.producttype::text = 'WALLET'::text
UNION ALL
 SELECT wtrans.txtime::timestamp(0) without time zone AS date,
        CASE
            WHEN fsi.receiverpartypublicname IS NULL THEN bp.name::text
            WHEN fsi.requesttype::text = 'B2C'::text THEN bp.name::text
            ELSE concat(bp.name, '-', fsi.receiverpartypublicname)
        END AS transactiontype,
    usr.username AS bankid,
        CASE
            WHEN fsi.receiverpartypublicname IS NULL THEN bp.name::text
            WHEN fsi.requesttype::text = 'B2C'::text THEN bp.name::text
            ELSE concat(bp.name, '-', fsi.receiverpartypublicname)
        END AS paymentdetails,
    wtrans.businesstrxid AS trxreference,
