  WHERE wtrans.parentid IS NULL AND bp.bpcode::text = 'SNDMNY'::text AND wb.producttype::text = 'WALLET'::text AND (wtrans.creditamount > 0::numeric OR wtrans.debitamount > 0::numeric)
UNION ALL
 SELECT wtrans.txtime::timestamp(0) without time zone AS date,
