     LEFT JOIN walletbalance wb ON usr.id::text = wb.ownerid::text
     LEFT JOIN channel ch ON wtrans.channelid::text = ch.id::text
  WHERE wtrans.parentid IS NULL AND wtrans.debitamount > 0::numeric AND wtrans.sourceid IS NULL AND wtrans.businessproductid IS NULL AND wtrans.chargebackofid IS NULL AND wb.producttype::text = 'WALLET'::text AND (wtrans.instancetype::text = 'CUSTOMER'::text OR wtrans.instancetype::text = 'BUSINESS'::text AND wtrans.externalrefid IS NOT NULL)
UNION ALL
 SELECT wtrans.txtime::timestamp(0) without time zone AS date,
    wtrans.description AS transactiontype,
    usr.username AS bankid,
    wtrans.description AS paymentdetails,
    wtrans.businesstrxid AS trxreference,
    round(wtrans.creditamount, 2) AS amount,
    ( SELECT
                CASE
                    WHEN round(sum(wallettransactions.debitamount), 2) IS NULL THEN 0::numeric
                    ELSE round(sum(wallettransactions.debitamount), 2)
                END AS round
           FROM wallettransactions
          WHERE wallettransactions.executionid::text = wtrans.executionid::text AND wallettransactions.walletinstanceid::text = wtrans.walletinstanceid::text AND wallettransactions.parentid IS NOT NULL) AS transactionfee,
        CASE
            WHEN wtrans.transactionstatus::text = 'PROCESSED'::text THEN 'Success'::text
            ELSE 'Failure'::text
        END AS status,
    'CREDIT'::text AS trxtype,
    usr.username AS customerid,
    ''::character varying AS merchantid,
        CASE
            WHEN wtrans.channelid::text = 'SYSTEM'::text THEN 'SYSTEM'::character varying
            ELSE ch.name
        END AS trxsource,
    usr.firstname,
    usr.lastname,
    concat('254', usr.username) AS mobilenumber,
    wtrans.businesstrxid AS uniqueid,
        CASE
            WHEN wtrans.externalrefid IS NULL THEN wb.walletno
            ELSE ( SELECT walletbalance.walletno
               FROM walletbalance
              WHERE walletbalance.id::text = wtrans.walletinstanceid::text)
        END AS sourceaccount,
    ( SELECT wallettype.glaccountnumber
           FROM wallettype
          WHERE wallettype.id::text = ((( SELECT walletbalance.wallettypeid
                   FROM walletbalance
                  WHERE walletbalance.id::text = wtrans.otherwalletinstanceid::text))::text)) AS destinationaccount
   FROM wallettransactions wtrans
     JOIN users usr ON wtrans.fromortouserid::text = usr.id::text
     LEFT JOIN walletbalance wb ON usr.id::text = wb.ownerid::text
     LEFT JOIN channel ch ON wtrans.channelid::text = ch.id::text
  WHERE wtrans.parentid IS NULL AND wtrans.debitamount = 0::numeric AND wtrans.creditamount > 0::numeric AND wtrans.sourceid IS NULL AND wtrans.businessproductid IS NULL AND wtrans.chargebackofid IS NULL AND wb.producttype::text = 'WALLET'::text AND (wtrans.instancetype::text = 'CUSTOMER'::text OR wtrans.instancetype::text = 'BUSINESS'::text AND wtrans.externalrefid IS NOT NULL);


-- dashboard.gldetailsreport source

CREATE OR REPLACE VIEW dashboard.gldetailsreport
AS SELECT w2.glaccountnumber AS accountid,
    w2.name AS description,
    ( SELECT
                CASE
                    WHEN w.otherwalletinstanceid IS NULL THEN 'Business'::character varying
                    ELSE ( SELECT walletbalance.walletno
                       FROM walletbalance
                      WHERE walletbalance.id::text = w.otherwalletinstanceid::text)
                END AS walletno) AS customerid,
    ( SELECT
                CASE
                    WHEN w.initiatorid IS NULL OR w.initiatorid::text = 'NEW_THREAD'::text THEN 'Business'::character varying
                    ELSE ( SELECT users.username
                       FROM users
                      WHERE users.id::text = w.initiatorid::text)
                END AS username) AS mobilenumber,
        CASE
            WHEN w.creditamount > 0::numeric THEN 'Credit'::text
            ELSE 'Debit'::text
        END AS trxtype,
        CASE
            WHEN w.description IS NULL OR w.description::text = ''::text THEN ( SELECT b.name
               FROM businessproduct b
              WHERE b.id::text = w.businessproductid::text)
            ELSE w.description
        END AS trxdescription,
    w.businesstrxid AS serialid,
    w.createdon::timestamp(0) without time zone AS trxdate,
        CASE
            WHEN w.creditamount > 0::numeric THEN round(w.totalbalance - w.creditamount, 2)
            ELSE round(w.totalbalance + w.debitamount, 2)
        END AS openingbalance,
    round(w.creditamount, 2) AS creditamount,
    round(w.debitamount, 2) AS debitamount,
    round(w.totalbalance, 2) AS closingbalance
   FROM wallettransactions w
     JOIN wallettype w2 ON w.wallettypeid::text = w2.id::text AND (w.transactionstatus::text = 'PROCESSED'::text OR w.transactionstatus::text = 'FAILED'::text)
  ORDER BY w.createdon DESC;


-- dashboard.glsummaryreport source

CREATE OR REPLACE VIEW dashboard.glsummaryreport
AS SELECT date(g.summarydate) AS "Date",
    w3.glaccountnumber AS "AccountID",
    w3.name AS "Description",
    'KES'::text AS "Currency ID",
    round(g.totalbalance - g.creditamounttoday + g.debitamounttoday, 2) AS "Opening Balance",
    round(g.debitamounttoday, 2) AS "Debit Amount",
    round(g.creditamounttoday, 2) AS "Credit Amount",
    round(g.totalbalance, 2) AS "Closing Balance"
   FROM glsummary g
     JOIN wallettype w3 ON g.wallettypeid::text = w3.id::text;


-- dashboard.insurance_cancellation_policy_report source

CREATE OR REPLACE VIEW dashboard.insurance_cancellation_policy_report
AS SELECT ins.cancelledon::timestamp(0) without time zone AS dateofcancellation,
    ins.insurancepolicyno AS insurancepolicynumber,
    concat(ins.firstname, ' ', ins.lastname) AS customername,
    wb.walletno AS timizaaccountnumber,
    concat('254', ins.mobilenumber) AS mobilenumber,
    ins.idnumber,
    round(ins.premiumamount, 2) AS premiumamount,
    ins.termfrequency AS coverperiod
   FROM insurancesubscription ins
     JOIN walletbalance wb ON ins.userid::text = wb.ownerid::text
  WHERE ins.status::text ~~ 'CANCELLED'::text AND wb.producttype::text = 'WALLET'::text;


-- dashboard.insurancepremiumcollectionschedulereport source

CREATE OR REPLACE VIEW dashboard.insurancepremiumcollectionschedulereport
AS SELECT ins.createdon::timestamp(0) without time zone AS dateofregistration,
    ins.insurancepolicyno AS insurancepolicynumber,
    concat(ins.firstname, ' ', ins.lastname) AS customername,
    date(usr.dob) AS dob,
    wb.walletno AS timizaacountnumber,
    concat('254', usr.username) AS mobilenumber,
    ins.idnumber,
    round(ins.premiumamount, 2) AS premiumamount,
    ins.termfrequency AS coverperiod,
    ins.benificiaryfullname AS benificiaryname,
    ins.benificiarymobilenumber,
    ins.benificiaryidnumber AS "Beneficiary ID Number",
    ins.lastpaymentdate,
    ins.nextautodebitdate::timestamp(0) without time zone::text::date AS "Next Auto Debit Date",
    ins.sourceoffunds AS "Source of Funds",
    ins.lastpaymentamount AS "Last Payment Amount"
   FROM insurancesubscription ins
     JOIN users usr ON ins.userid::text = usr.id::text
     JOIN walletbalance wb ON ins.userid::text = wb.ownerid::text
  WHERE wb.producttype::text = 'WALLET'::text AND ins.status::text <> 'CANCELLED'::text;


-- dashboard.interestaccrual source

CREATE OR REPLACE VIEW dashboard.interestaccrual
AS SELECT rd.rdaccountno AS accountid,
    concat('254', usr.username) AS mobilenumber,
    rd.accountstatus,
    concat(usr.firstname, ' ', usr.lastname) AS name,
    date(da.acuraldonetill) AS accrualdate,
    round(da.dailyaccuralamount, 2) AS value,
    round(da.totalinterestaccured, 2) AS totalaccrued,
    round(rd.totalamountdeposited, 2) AS balance,
    round(da.dailyaccuralamount, 2) AS baseaccrued,
    round(rd.bonusamountdisbursed, 2) AS bonusaccrued
   FROM depositaccural da
     JOIN users usr ON da.userid::text ~~ usr.id::text
     LEFT JOIN rdproductassociation rd ON da.depositproductassociationid::text ~~ rd.id::text;


-- dashboard.iprsfailedreport source

CREATE OR REPLACE VIEW dashboard.iprsfailedreport
AS SELECT concat('254', usr.username) AS mobilenumber,
    usr.idnumber,
    rq.createdon::timestamp(0) without time zone AS createdon,
    'FAILED'::text AS status
   FROM registrationqueue rq
     JOIN users usr ON rq.userid::text = usr.id::text
  WHERE rq.queuename::text = 'IPRS'::text AND rq.status::text = 'FAILED'::text;


-- dashboard.iprsmnomismatch source

CREATE OR REPLACE VIEW dashboard.iprsmnomismatch
AS SELECT concat('254', usr.mobilenumber) AS mobilenumber,
    usr.idnumber,
    usr.createdon::timestamp(0) without time zone AS createdon,
    usr.mnoiprsmatchpercentage,
    iprs.firstname AS iprsfirstname,
    iprs.othername AS iprsothername,
    iprs.surname AS iprslastname,
    sfcom.firstname AS mnofirstname,
    sfcom.surname AS mnolastname,
        CASE
            WHEN (100::numeric - usr.mnoiprsmatchpercentage) > 30::numeric THEN 'FAIL'::text
            ELSE 'PASS'::text
        END AS result
   FROM users usr
     JOIN iprsuserdetails iprs ON usr.id::text ~~ iprs.userid::text
     LEFT JOIN safaricomcustomercreditscoredetails sfcom ON usr.id::text ~~ sfcom.userid::text;


-- dashboard.iprspendingreport source

CREATE OR REPLACE VIEW dashboard.iprspendingreport
AS SELECT concat('254', usr.username) AS mobilenumber,
    usr.idnumber,
    rq.createdon::timestamp(0) without time zone AS createdon,
    'PENDING'::text AS status
   FROM registrationqueue rq
     JOIN users usr ON rq.userid::text = usr.id::text
  WHERE rq.queuename::text = 'IPRS'::text AND rq.status::text = 'PENDING'::text;


-- dashboard.lapsed_insurance_policy_report source

CREATE OR REPLACE VIEW dashboard.lapsed_insurance_policy_report
AS SELECT ins.idnumber,
    round(ins.lastpaymentamount, 2) AS lastpremiumpaid,
    ins.insurancepolicyno AS insurancepolicynumber,
    concat(ins.firstname, ' ', ins.lastname) AS customername,
    wb.walletno AS timizaaccountnumber,
    concat('254', ins.mobilenumber) AS mobilenumber,
    round(ins.premiumamount, 2) AS premiumdue,
    ins.termfrequency AS coverperiod,
    date(ins.modifiedon) AS "Lapsed Date",
    ins.nextautodebitdate::timestamp(0) without time zone::text::date AS "Next Auto Debit Date"
   FROM insurancesubscriptionaudit ins
     JOIN walletbalance wb ON ins.userid::text = wb.ownerid::text
  WHERE ins.status::text ~~ 'LAPSED'::text AND wb.producttype::text = 'WALLET'::text AND wb.producttype::text = 'WALLET'::text AND
        CASE
            WHEN ins.termfrequency::text = 'MONTHLY'::text THEN date_part('day'::text, ins.modifiedon) = 5::double precision
            ELSE NULL::boolean
        END
UNION ALL
 SELECT i.idnumber,
    round(i.lastpaymentamount, 2) AS lastpremiumpaid,
    i.insurancepolicyno AS insurancepolicynumber,
    concat(i.firstname, ' ', i.lastname) AS customername,
    wb.walletno AS timizaaccountnumber,
    concat('254', i.mobilenumber) AS mobilenumber,
    round(i.premiumamount, 2) AS premiumdue,
    i.termfrequency AS coverperiod,
    date(i.modifiedon) AS "Lapsed Date",
    i.nextautodebitdate::timestamp(0) without time zone::text::date AS "Next Auto Debit Date"
   FROM insurancesubscriptionaudit i
     JOIN walletbalance wb ON i.userid::text = wb.ownerid::text AND wb.producttype::text = 'WALLET'::text
     JOIN ( SELECT insurancesubscriptionaudit.id,
            max(insurancesubscriptionaudit.modifiedon) AS modifiedon
           FROM insurancesubscriptionaudit
          WHERE insurancesubscriptionaudit.paymentfrequency::text = 'YEARLY'::text AND insurancesubscriptionaudit.status::text = 'LAPSED'::text
          GROUP BY insurancesubscriptionaudit.id, (date_trunc('year'::text, insurancesubscriptionaudit.modifiedon))) r ON i.id::text = r.id::text AND i.modifiedon = r.modifiedon;


-- dashboard.liencountforprocessing source

CREATE OR REPLACE VIEW dashboard.liencountforprocessing
AS SELECT l.id,
    l.createdby,
    l.modifiedby,
    l.createdon,
    l.modifiedon,
    l.disbursementwalletid,
    l.userid,
    l.roleid,
    l.mfgroupid,
    l.loanproductid,
    l.loanofficerid,
    l.loanpurpose,
    l.loanstatus,
    l.principalrequested,
    l.principalgranted,
    l.annualisedinterestrate,
    l.intrestmethod,
    l.calcuatedintrest,
    l.loanperiodrequested,
    l.loanperiod,
    l.loanperiodfrequency,
    l.replayfrequency,
    l.numberofrepayments,
    l.loanapplicationid,
    l.autopayloan,
    l.gracenointerest,
    l.gracenoprinciplepayment,
    l.gracenopayment,
    l.approvedon,
    l.approvedby,
    l.expecteddisbursementdate,
    l.expectedfirstrepaymentdate,
    l.interesttobecalculatedfrom,
    l.actualdisbursementdate,
    l.lastpaidon,
    l.disbursedbyuser,
    l.calucatedclosedate,
    l.closedbyuser,
    l.processingfeescharged,
    l.principaldisbursed,
    l.principalrepaid,
    l.principalwroteoff,
    l.principaloutstanding,
    l.interestchargedsofar,
    l.interestrepaidsofar,
    l.interestwavedoff,
    l.interestwrittenoff,
    l.interestoutstanding,
    l.feescharged,
    l.feesrepaid,
    l.feeschargeswaved,
    l.feechargeswroteoff,
    l.feechargesoutstanding,
    l.chargescharged,
    l.chargesrepaid,
    l.chargeschargeswaved,
    l.totalactualrepayment,
    l.totalexpectedcostofloan,
    l.totalactualcostofloan,
    l.totalamountwaived,
    l.totalamountwrittenoff,
    l.totalamountoutstanding,
    l.finalexcessamount,
    l.rejectiondate,
    l.rejectedby,
    l.rescheduledon,
    l.creditlifefeescharged,
    l.unpaidfees,
    l.prepaymentinterestoption,
    l.loantype,
    l.lastrepaymenttxnid,
    l.transactionfeecharged,
    l.autopaytried,
    l.creditrepayratio,
    l.accountnumber,
    l.lastinstallmentamount,
    l.actualclosedate,
    l.writtenoffdate,
    l.excisedutycharged,
    l.riskassessment,
    l.creditlimit,
    l.isoverdue,
    l.overdueamount,
    l.totalamountchargedoff,
    l.chargeoffdate,
    l.installmentamount
   FROM loan l
     JOIN walletlienrecord wlr ON l.id::text = wlr.moduleid::text
  WHERE wlr.status::text = 'ACTIVE'::text AND wlr.lienamount > 0::numeric AND (l.userid::text IN ( SELECT wb.ownerid AS id
           FROM walletbalance wb
             JOIN walletlienrecord wlr_1 ON wlr_1.walletbalanceid::text = wb.id::text
          WHERE (wb.totalbalance - wb.lowertotalbalancelimit) > 0::numeric AND wlr_1.status::text = 'ACTIVE'::text AND wlr_1.lienamount > 0::numeric));


-- dashboard.loanbucketshiftcount source

CREATE OR REPLACE VIEW dashboard.loanbucketshiftcount
AS SELECT lb.loanid,
    lb.nextbucketshiftdate,
    lb.currentbucketnumber,
    lb.validatedtill,
    lb.loanproductid,
    lb.userid,
    lb.createdon,
    lb.modifiedon,
    lb.lastpaymentdate,
    lb.lastbucketchange,
    lb.addtoreporting,
    lb.id
   FROM loanbucket lb,
    loan l
  WHERE date(lb.nextbucketshiftdate) <= date(now()) AND l.id::text = lb.loanid::text AND l.loanstatus::text = 'ACTIVE'::text;


-- dashboard.loanclosedreport source

CREATE OR REPLACE VIEW dashboard.loanclosedreport
AS SELECT usr.lastname AS "Surname",
    usr.firstname AS "Forename1",
    usr.middlename AS "Forename2",
        CASE
            WHEN ukyc.title IS NULL THEN ''::character varying
            ELSE ukyc.title
        END AS "Salutation",
    CURRENT_DATE AS "current_date",
    l.calucatedclosedate,
    to_char(CURRENT_DATE::timestamp with time zone, 'dd/mm/yyyy'::text) AS "BusinessDate",
    to_char(usr.dob::date::timestamp with time zone, 'dd/mm/yyyy'::text) AS "Date_of_Birth",
    usr.id AS "Client_Number",
    l.accountnumber AS "Mobile_Loan_Account_Number",
    usr.gender,
    'KE'::text AS "Nationality",
    usr.idtype AS "PrimaryID_type",
    usr.idnumber AS "PrimaryID_Num",
    concat('254', usr.username) AS "Mobile_Number",
    'KE'::text AS "Postal_Country",
    0 AS salary_band,
    'Virtual Banking'::text AS "Lender_Branch_Name",
    160 AS "Lender_Branch_Code",
    'IN001'::text AS "Account_prod_type",
    to_char(l.expecteddisbursementdate::date::timestamp with time zone, 'dd/mm/yyyy'::text) AS "Date_Acct_Opened",
    to_char(l.expectedfirstrepaymentdate::date::timestamp with time zone, 'dd/mm/yyyy'::text) AS "Instalment_due_date",
    round(l.principaldisbursed, 2) AS "Original_Amount",
    round(l.principaldisbursed, 2) AS local_orig_amount,
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN round(l.totalamountoutstanding, 2)
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN round(l.totalamountwrittenoff, 2)
            ELSE round(l.totalamountoutstanding, 2)
        END AS "Current_balance",
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN round(l.totalamountoutstanding, 2)
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN round(l.totalamountwrittenoff, 2)
            WHEN date(l.calucatedclosedate) >= CURRENT_DATE THEN 0::numeric
            WHEN l.totalamountoutstanding IS NULL THEN 0::numeric
            ELSE round(l.totalamountoutstanding, 2)
        END AS "Overdue_balance",
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN ' '::text
            WHEN l.calucatedclosedate < CURRENT_DATE THEN to_char((l.calucatedclosedate::date + 1)::timestamp with time zone, 'dd/mm/yyyy'::text)
            ELSE ' '::text
        END AS "Overdue_date",
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::double precision
            WHEN date_part('days'::text, l.calucatedclosedate::timestamp with time zone - CURRENT_DATE::timestamp with time zone) >= 0::double precision THEN 0::double precision
            ELSE date_part('days'::text, l.calucatedclosedate::timestamp with time zone - CURRENT_DATE::timestamp with time zone) * '-1'::integer::double precision
        END AS "Days_in_arrears",
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 'Bucket 0'::text
            ELSE concat('Bucket ', round(lb.currentbucketnumber, 0))
        END AS "Bucket",
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::numeric
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN round(l.totalamountwrittenoff, 2)
            WHEN date(l.calucatedclosedate) > CURRENT_DATE THEN 0::numeric
            WHEN l.totalamountoutstanding IS NULL THEN 0::numeric
            ELSE round(l.totalamountoutstanding, 2)
        END AS "Instalment_arrears",
    l.loanstatus AS "Account_Status",
        CASE
            WHEN l.loanstatus::text = 'ACTIVE'::text THEN to_char(l.createdon::date::timestamp with time zone, 'dd/mm/yyyy'::text)
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN to_char(l.writtenoffdate::date::timestamp with time zone, 'dd/mm/yyyy'::text)
            ELSE to_char(l.actualclosedate::date::timestamp with time zone, 'dd/mm/yyyy'::text)
        END AS "Account_status_Date",
    ' '::text AS "Reason_For_Closure",
    l.loanperiod AS "Repayment_period",
    ''::text AS "Deferred_pymt_Date",
    ''::text AS "Deferred_pymt_amt",
    l.replayfrequency AS "Payment_freq",
    to_char(l.actualdisbursementdate::date::timestamp with time zone, 'dd/mm/yyyy'::text) AS "Disbursement_Date",
    round(l.totalexpectedcostofloan, 2) AS "Instalment_amount",
        CASE
            WHEN l.lastpaidon IS NULL THEN ' '::text
            ELSE to_char(l.lastpaidon::date::timestamp with time zone, 'dd/mm/yyyy'::text)
        END AS "Latest_pymt_date",
    COALESCE(round(l.lastinstallmentamount, 2), 0::numeric) AS "Latest_pymt_Amt",
        CASE
            WHEN l.loanstatus::text = ANY (ARRAY['ACTIVE'::character varying::text, 'WRITTEN_OFF'::character varying::text]) THEN 'ACTIVE'::text
            ELSE 'CLOSED'::text
        END AS "Account_status_desc",
    lp.name AS product_name,
    to_char(l.createdon, 'dd/mm/yyyy HH24:MI:SS'::text) AS createdon,
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::numeric
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN 0::numeric
            ELSE round(l.principaloutstanding, 2)
        END AS "PrincipalOutstanding",
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::numeric
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN 0::numeric
            ELSE round(l.calcuatedintrest - l.interestrepaidsofar, 2)
        END AS "Interestoutstanding",
    round(l.creditlimit, 2) AS "Creditlimit",
    l.riskassessment AS "RiskCategory",
    ( SELECT sum(round(l2.penaltypending, 2)) AS sum
           FROM loanschedule l2
          WHERE l2.loanid::text = l.id::text) AS "Penaltyfeeoutstanding",
    ( SELECT sum(round(l2.penaltycomponent, 2)) AS sum
           FROM loanschedule l2
          WHERE l2.loanid::text = l.id::text) AS "RolloverFees",
    0::numeric AS "ChargeOffInterestPending"
   FROM users usr
     JOIN loan l ON usr.id::text = l.userid::text AND l.loanstatus::text = 'CLOSED'::text
     LEFT JOIN userkycdetails ukyc ON usr.id::text = ukyc.userid::text
     LEFT JOIN loanbucket lb ON l.id::text = lb.loanid::text
     LEFT JOIN loanproduct lp ON l.loanproductid::text = lp.id::text
  WHERE l.actualclosedate >= CURRENT_DATE;


-- dashboard.loandistributionbybucket source

CREATE OR REPLACE VIEW dashboard.loandistributionbybucket
AS SELECT a.totalamountoutstanding,
    concat('BUCKET ', round(a.currentbucketnumber, 0)) AS currentbucketnumber
   FROM ( SELECT sum(l.totalamountoutstanding) AS totalamountoutstanding,
            lb.currentbucketnumber
           FROM loan l,
            loanbucket lb
          WHERE l.id::text = lb.loanid::text
          GROUP BY lb.currentbucketnumber) a;


-- dashboard.loanlimitsreport source

CREATE OR REPLACE VIEW dashboard.loanlimitsreport
AS SELECT concat(usr.firstname, ' ', usr.middlename, ' ', usr.lastname) AS customername,
    concat('254', usr.username) AS mobilenumber,
    round(cl.creditlimit, 2) AS creditlimit,
        CASE
            WHEN cl.limitlastupdatedon IS NULL THEN cl.createdon::timestamp(0) without time zone
            ELSE cl.limitlastupdatedon::timestamp(0) without time zone
        END AS limitlastupdatedon,
    cl.limitexpirydate::timestamp(0) without time zone AS limitexpirydate,
        CASE
            WHEN date(cl.limitexpirydate) > date(now()) THEN 'Valid'::text
            ELSE 'Expired'::text
        END AS limitstatus
   FROM users usr
     JOIN creditlimit cl ON usr.id::text = cl.userid::text
     JOIN role rl ON usr.roleid::text = rl.id::text
  WHERE rl.roletype::text <> 'OPERATIONAL'::text AND cl.creditlimit > 0::numeric
  ORDER BY (
        CASE
            WHEN cl.limitlastupdatedon IS NULL THEN cl.createdon::timestamp(0) without time zone
            ELSE cl.limitlastupdatedon::timestamp(0) without time zone
        END) DESC;


-- dashboard.loanpurpose source

CREATE OR REPLACE VIEW dashboard.loanpurpose
AS SELECT loanpurposelist.loanpurpose,
    count(
        CASE
            WHEN loanpurposelist.gender::text ~~ 'MALE'::text THEN 1
            ELSE NULL::integer
        END) AS malecount,
    count(
        CASE
            WHEN loanpurposelist.gender::text ~~ 'FEMALE'::text THEN 1
            ELSE NULL::integer
        END) AS femalecount,
    count(
        CASE
            WHEN loanpurposelist.gender::text ~~ 'MALE'::text OR loanpurposelist.gender::text ~~ 'FEMALE'::text THEN 1
            ELSE NULL::integer
        END) AS totalcount,
    sum(
        CASE
            WHEN loanpurposelist.gender::text ~~ 'MALE'::text THEN round(loanpurposelist.principalgranted, 2)
            ELSE 0::numeric
        END) AS malesum,
    sum(
        CASE
            WHEN loanpurposelist.gender::text ~~ 'FEMALE'::text THEN round(loanpurposelist.principalgranted, 2)
            ELSE 0::numeric
        END) AS femalesum,
    sum(
        CASE
            WHEN loanpurposelist.gender::text ~~ 'MALE'::text OR loanpurposelist.gender::text ~~ 'FEMALE'::text THEN round(loanpurposelist.principalgranted, 2)
            ELSE 0::numeric
        END) AS totalsum
   FROM ( SELECT
                CASE
                    WHEN loan.loanpurpose::text ~~ 'EDUCATIONAL'::text THEN 'Educational'::text
                    WHEN loan.loanpurpose::text ~~ 'BUSINESS'::text THEN 'BUSINESS'::text
                    WHEN loan.loanpurpose::text <> ALL (ARRAY['BUSINESS'::character varying::text, 'EDUCATIONAL'::character varying::text]) THEN 'Others'::text
                    ELSE NULL::text
                END AS loanpurpose,
            users.gender,
            loan.principalgranted
           FROM loan
             JOIN users ON loan.userid::text ~~ users.id::text
          WHERE loan.principalgranted > 0::numeric) loanpurposelist
  GROUP BY loanpurposelist.loanpurpose;


-- dashboard.loanriskcategory source

CREATE OR REPLACE VIEW dashboard.loanriskcategory
AS SELECT c.riskcategory,
    sum(l.principaldisbursed) AS "Principal Disbursed"
   FROM loan l
     JOIN creditlimit c ON c.userid::text = l.userid::text AND c.riskcategory IS NOT NULL
  GROUP BY c.riskcategory;


-- dashboard.mnokycfail source

CREATE OR REPLACE VIEW dashboard.mnokycfail
AS SELECT concat('254', safaricomintegrationrecord.mobilenumber) AS mobilenumber,
    safaricomintegrationrecord.idnumber,
    safaricomintegrationrecord.createdon::timestamp(0) without time zone AS createdon,
    safaricomintegrationrecord.status,
    safaricomintegrationrecord.responsemessage AS result
   FROM safaricomintegrationrecord
  WHERE safaricomintegrationrecord.status::text = 'FAILURE'::text;


-- dashboard.mobiledepositaccount source

CREATE OR REPLACE VIEW dashboard.mobiledepositaccount
AS SELECT agelist.age AS ageofaccountholder,
    date_part('year'::text, agelist.createdon) AS year,
        CASE
            WHEN date_part('month'::text, agelist.createdon) = 1::double precision THEN 'January'::text
            WHEN date_part('month'::text, agelist.createdon) = 2::double precision THEN 'February'::text
            WHEN date_part('month'::text, agelist.createdon) = 3::double precision THEN 'March'::text
            WHEN date_part('month'::text, agelist.createdon) = 4::double precision THEN 'April'::text
            WHEN date_part('month'::text, agelist.createdon) = 5::double precision THEN 'May'::text
            WHEN date_part('month'::text, agelist.createdon) = 6::double precision THEN 'June'::text
            WHEN date_part('month'::text, agelist.createdon) = 7::double precision THEN 'July'::text
            WHEN date_part('month'::text, agelist.createdon) = 8::double precision THEN 'August'::text
            WHEN date_part('month'::text, agelist.createdon) = 9::double precision THEN 'September'::text
            WHEN date_part('month'::text, agelist.createdon) = 10::double precision THEN 'October'::text
            WHEN date_part('month'::text, agelist.createdon) = 11::double precision THEN 'November'::text
            WHEN date_part('month'::text, agelist.createdon) = 12::double precision THEN 'December'::text
            ELSE NULL::text
        END AS month,
    count(
        CASE
            WHEN agelist.gender::text = 'MALE'::text THEN 1
            ELSE NULL::integer
        END) AS malecount,
    count(
        CASE
            WHEN agelist.gender::text = 'FEMALE'::text THEN 1
            ELSE NULL::integer
        END) AS femalecount,
    count(
        CASE
            WHEN agelist.gender::text = ''::text OR agelist.gender IS NULL THEN 1
            ELSE NULL::integer
        END) AS nogendercount,
    count(
        CASE
            WHEN agelist.gender::text = 'MALE'::text OR agelist.gender::text = 'FEMALE'::text OR agelist.gender::text = ''::text OR agelist.gender IS NULL THEN 1
            ELSE NULL::integer
        END) AS totalcount,
    sum(
        CASE
            WHEN agelist.gender::text = 'MALE'::text THEN round(agelist.totalamountdeposited, 2)
            ELSE 0::numeric
        END) AS malesum,
    sum(
        CASE
            WHEN agelist.gender::text = 'FEMALE'::text THEN round(agelist.totalamountdeposited, 2)
            ELSE 0::numeric
        END) AS femalesum,
    sum(
        CASE
            WHEN agelist.gender::text = ''::text OR agelist.gender IS NULL THEN round(agelist.totalamountdeposited, 2)
            ELSE 0::numeric
        END) AS nogendersum,
    sum(
        CASE
            WHEN agelist.gender::text = 'MALE'::text OR agelist.gender::text = 'FEMALE'::text OR agelist.gender::text = ''::text OR agelist.gender IS NULL THEN round(agelist.totalamountdeposited, 2)
            ELSE 0::numeric
        END) AS totalsum
   FROM ( SELECT
                CASE
                    WHEN date_part('year'::text, age(users.dob)) >= 18::double precision AND date_part('year'::text, age(users.dob)) <= 25::double precision THEN '18-25'::text
                    WHEN date_part('year'::text, age(users.dob)) >= 26::double precision AND date_part('year'::text, age(users.dob)) <= 35::double precision THEN '26-35'::text
                    WHEN date_part('year'::text, age(users.dob)) >= 36::double precision AND date_part('year'::text, age(users.dob)) <= 45::double precision THEN '36-45'::text
                    WHEN date_part('year'::text, age(users.dob)) >= 46::double precision AND date_part('year'::text, age(users.dob)) <= 55::double precision THEN '46-55'::text
                    WHEN date_part('year'::text, age(users.dob)) >= 56::double precision AND date_part('year'::text, age(users.dob)) <= 125::double precision THEN '56 and above'::text
                    ELSE NULL::text
                END AS age,
            users.gender,
            w.totalbalance AS totalamountdeposited,
            w.createdon::timestamp(0) without time zone AS createdon
           FROM walletbalance w
             JOIN users ON w.ownerid::text = users.id::text AND w.isactive = true AND w.producttype::text = 'WALLET'::text AND date_part('year'::text, now()) = date_part('year'::text, w.createdon) AND w.totalbalance > 0::numeric) agelist
  WHERE agelist.age IS NOT NULL
  GROUP BY agelist.age, (date_part('year'::text, agelist.createdon)), (
        CASE
            WHEN date_part('month'::text, agelist.createdon) = 1::double precision THEN 'January'::text
            WHEN date_part('month'::text, agelist.createdon) = 2::double precision THEN 'February'::text
            WHEN date_part('month'::text, agelist.createdon) = 3::double precision THEN 'March'::text
            WHEN date_part('month'::text, agelist.createdon) = 4::double precision THEN 'April'::text
            WHEN date_part('month'::text, agelist.createdon) = 5::double precision THEN 'May'::text
            WHEN date_part('month'::text, agelist.createdon) = 6::double precision THEN 'June'::text
            WHEN date_part('month'::text, agelist.createdon) = 7::double precision THEN 'July'::text
            WHEN date_part('month'::text, agelist.createdon) = 8::double precision THEN 'August'::text
            WHEN date_part('month'::text, agelist.createdon) = 9::double precision THEN 'September'::text
            WHEN date_part('month'::text, agelist.createdon) = 10::double precision THEN 'October'::text
            WHEN date_part('month'::text, agelist.createdon) = 11::double precision THEN 'November'::text
            WHEN date_part('month'::text, agelist.createdon) = 12::double precision THEN 'December'::text
            ELSE NULL::text
        END);


