-- dashboard.mobileloanbygenderandrepayment source

CREATE OR REPLACE VIEW dashboard.mobileloanbygenderandrepayment
AS SELECT loanrepaymenttimelist.loanrepaymenttime AS timeofloanrepayment,
    date_part('year'::text, loanrepaymenttimelist.lastpaidon) AS year,
        CASE
            WHEN date_part('month'::text, loanrepaymenttimelist.lastpaidon) = 1::double precision THEN 'January'::text
            WHEN date_part('month'::text, loanrepaymenttimelist.lastpaidon) = 2::double precision THEN 'February'::text
            WHEN date_part('month'::text, loanrepaymenttimelist.lastpaidon) = 3::double precision THEN 'March'::text
            WHEN date_part('month'::text, loanrepaymenttimelist.lastpaidon) = 4::double precision THEN 'April'::text
            WHEN date_part('month'::text, loanrepaymenttimelist.lastpaidon) = 5::double precision THEN 'May'::text
            WHEN date_part('month'::text, loanrepaymenttimelist.lastpaidon) = 6::double precision THEN 'June'::text
            WHEN date_part('month'::text, loanrepaymenttimelist.lastpaidon) = 7::double precision THEN 'July'::text
            WHEN date_part('month'::text, loanrepaymenttimelist.lastpaidon) = 8::double precision THEN 'August'::text
            WHEN date_part('month'::text, loanrepaymenttimelist.lastpaidon) = 9::double precision THEN 'September'::text
            WHEN date_part('month'::text, loanrepaymenttimelist.lastpaidon) = 10::double precision THEN 'October'::text
            WHEN date_part('month'::text, loanrepaymenttimelist.lastpaidon) = 11::double precision THEN 'November'::text
            WHEN date_part('month'::text, loanrepaymenttimelist.lastpaidon) = 12::double precision THEN 'December'::text
            ELSE NULL::text
        END AS month,
    count(
        CASE
            WHEN loanrepaymenttimelist.gender::text = 'MALE'::text THEN 1
            ELSE NULL::integer
        END) AS malecount,
    count(
        CASE
            WHEN loanrepaymenttimelist.gender::text = 'FEMALE'::text THEN 1
            ELSE NULL::integer
        END) AS femalecount,
    count(
        CASE
            WHEN loanrepaymenttimelist.gender::text = ''::text OR loanrepaymenttimelist.gender IS NULL THEN 1
            ELSE NULL::integer
        END) AS nogendercount,
    count(
        CASE
            WHEN loanrepaymenttimelist.gender::text = 'MALE'::text OR loanrepaymenttimelist.gender::text = 'FEMALE'::text OR loanrepaymenttimelist.gender::text = ''::text OR loanrepaymenttimelist.gender IS NULL THEN 1
            ELSE NULL::integer
        END) AS totalcount,
    sum(
        CASE
            WHEN loanrepaymenttimelist.gender::text = 'MALE'::text THEN round(loanrepaymenttimelist.principalrepaid, 2)
            ELSE 0::numeric
        END) AS malesum,
    sum(
        CASE
            WHEN loanrepaymenttimelist.gender::text = 'FEMALE'::text THEN round(loanrepaymenttimelist.principalrepaid, 2)
            ELSE 0::numeric
        END) AS femalesum,
    sum(
        CASE
            WHEN loanrepaymenttimelist.gender::text = ''::text OR loanrepaymenttimelist.gender IS NULL THEN round(loanrepaymenttimelist.principalrepaid, 2)
            ELSE 0::numeric
        END) AS nogendersum,
    sum(
        CASE
            WHEN loanrepaymenttimelist.gender::text = 'MALE'::text OR loanrepaymenttimelist.gender::text = 'FEMALE'::text OR loanrepaymenttimelist.gender::text = ''::text OR loanrepaymenttimelist.gender IS NULL THEN round(loanrepaymenttimelist.principalrepaid, 2)
            ELSE 0::numeric
        END) AS totalsum
   FROM ( SELECT
                CASE
                    WHEN l.lastpaidon::time without time zone >= '00:00:00'::time without time zone AND l.lastpaidon::time without time zone <= '03:00:00'::time without time zone THEN '12:00 am - 3:00 am'::text
                    WHEN l.lastpaidon::time without time zone >= '03:00:01'::time without time zone AND l.lastpaidon::time without time zone <= '06:00:00'::time without time zone THEN '3:00 am - 6:00 am'::text
                    WHEN l.lastpaidon::time without time zone >= '06:00:01'::time without time zone AND l.lastpaidon::time without time zone <= '11:00:00'::time without time zone THEN '6:00 am - 11:00 am'::text
                    WHEN l.lastpaidon::time without time zone >= '11:00:01'::time without time zone AND l.lastpaidon::time without time zone <= '17:00:00'::time without time zone THEN '11:00 am - 05:00 pm'::text
                    WHEN l.lastpaidon::time without time zone >= '17:00:01'::time without time zone AND l.lastpaidon::time without time zone <= '23:59:59'::time without time zone THEN '5:00 pm - 11:59 pm'::text
                    ELSE NULL::text
                END AS loanrepaymenttime,
            users.gender,
            l.principalrepaid,
            l.lastpaidon::timestamp(0) without time zone AS lastpaidon,
            l.createdon,
            l.actualclosedate,
            l.loanproductid
           FROM loan l
             JOIN users ON l.userid::text = users.id::text AND date_part('year'::text, now()) = date_part('year'::text, l.lastpaidon)) loanrepaymenttimelist
  WHERE loanrepaymenttimelist.principalrepaid IS NOT NULL AND loanrepaymenttimelist.loanrepaymenttime IS NOT NULL AND loanrepaymenttimelist.createdon >= '2021-01-01 00:00:00'::timestamp without time zone AND loanrepaymenttimelist.actualclosedate >= '2021-01-01 00:00:00'::timestamp without time zone AND loanrepaymenttimelist.loanproductid::text = 'e0cff44e-bf30-43cf-91ab-82b3f2446980'::text
  GROUP BY loanrepaymenttimelist.loanrepaymenttime, (date_part('year'::text, loanrepaymenttimelist.lastpaidon)), (
        CASE
            WHEN date_part('month'::text, loanrepaymenttimelist.lastpaidon) = 1::double precision THEN 'January'::text
            WHEN date_part('month'::text, loanrepaymenttimelist.lastpaidon) = 2::double precision THEN 'February'::text
            WHEN date_part('month'::text, loanrepaymenttimelist.lastpaidon) = 3::double precision THEN 'March'::text
            WHEN date_part('month'::text, loanrepaymenttimelist.lastpaidon) = 4::double precision THEN 'April'::text
            WHEN date_part('month'::text, loanrepaymenttimelist.lastpaidon) = 5::double precision THEN 'May'::text
            WHEN date_part('month'::text, loanrepaymenttimelist.lastpaidon) = 6::double precision THEN 'June'::text
            WHEN date_part('month'::text, loanrepaymenttimelist.lastpaidon) = 7::double precision THEN 'July'::text
            WHEN date_part('month'::text, loanrepaymenttimelist.lastpaidon) = 8::double precision THEN 'August'::text
            WHEN date_part('month'::text, loanrepaymenttimelist.lastpaidon) = 9::double precision THEN 'September'::text
            WHEN date_part('month'::text, loanrepaymenttimelist.lastpaidon) = 10::double precision THEN 'October'::text
            WHEN date_part('month'::text, loanrepaymenttimelist.lastpaidon) = 11::double precision THEN 'November'::text
            WHEN date_part('month'::text, loanrepaymenttimelist.lastpaidon) = 12::double precision THEN 'December'::text
            ELSE NULL::text
        END);


-- dashboard.mobileloanrepayment source

CREATE OR REPLACE VIEW dashboard.mobileloanrepayment
AS SELECT loanrepaymentlist.loanrepayment AS repaymentperiodindays,
    date_part('year'::text, loanrepaymentlist.actualdisbursementdate) AS year,
        CASE
            WHEN date_part('month'::text, loanrepaymentlist.actualdisbursementdate) = 1::double precision THEN 'January'::text
            WHEN date_part('month'::text, loanrepaymentlist.actualdisbursementdate) = 2::double precision THEN 'February'::text
            WHEN date_part('month'::text, loanrepaymentlist.actualdisbursementdate) = 3::double precision THEN 'March'::text
            WHEN date_part('month'::text, loanrepaymentlist.actualdisbursementdate) = 4::double precision THEN 'April'::text
            WHEN date_part('month'::text, loanrepaymentlist.actualdisbursementdate) = 5::double precision THEN 'May'::text
            WHEN date_part('month'::text, loanrepaymentlist.actualdisbursementdate) = 6::double precision THEN 'June'::text
            WHEN date_part('month'::text, loanrepaymentlist.actualdisbursementdate) = 7::double precision THEN 'July'::text
            WHEN date_part('month'::text, loanrepaymentlist.actualdisbursementdate) = 8::double precision THEN 'August'::text
            WHEN date_part('month'::text, loanrepaymentlist.actualdisbursementdate) = 9::double precision THEN 'September'::text
            WHEN date_part('month'::text, loanrepaymentlist.actualdisbursementdate) = 10::double precision THEN 'October'::text
            WHEN date_part('month'::text, loanrepaymentlist.actualdisbursementdate) = 11::double precision THEN 'November'::text
            WHEN date_part('month'::text, loanrepaymentlist.actualdisbursementdate) = 12::double precision THEN 'December'::text
            ELSE NULL::text
        END AS month,
    count(
        CASE
            WHEN loanrepaymentlist.gender::text = 'MALE'::text THEN 1
            ELSE NULL::integer
        END) AS malecount,
    count(
        CASE
            WHEN loanrepaymentlist.gender::text = 'FEMALE'::text THEN 1
            ELSE NULL::integer
        END) AS femalecount,
    count(
        CASE
            WHEN loanrepaymentlist.gender::text = ''::text OR loanrepaymentlist.gender IS NULL THEN 1
            ELSE NULL::integer
        END) AS nogendercount,
    count(
        CASE
            WHEN loanrepaymentlist.gender::text = 'MALE'::text OR loanrepaymentlist.gender::text = 'FEMALE'::text OR loanrepaymentlist.gender::text = ''::text OR loanrepaymentlist.gender IS NULL THEN 1
            ELSE NULL::integer
        END) AS totalcount,
    sum(
        CASE
            WHEN loanrepaymentlist.gender::text = 'MALE'::text THEN round(loanrepaymentlist.principalrepaid, 2)
            ELSE 0::numeric
        END) + sum(
        CASE
            WHEN loanrepaymentlist.gender::text = 'MALE'::text AND loanrepaymentlist.principalrepaid = 0::numeric THEN round(loanrepaymentlist.totalamountoutstanding, 2)
            ELSE 0::numeric
        END) + sum(
        CASE
            WHEN loanrepaymentlist.gender::text = 'MALE'::text AND loanrepaymentlist.loanstatus::text = 'WRITTEN_OFF'::text THEN round(loanrepaymentlist.totalamountwrittenoff, 2)
            ELSE 0::numeric
        END) AS malesum,
    sum(
        CASE
            WHEN loanrepaymentlist.gender::text = 'FEMALE'::text THEN round(loanrepaymentlist.principalrepaid, 2)
            ELSE 0::numeric
        END) + sum(
        CASE
            WHEN loanrepaymentlist.gender::text = 'FEMALE'::text AND loanrepaymentlist.principalrepaid = 0::numeric THEN round(loanrepaymentlist.totalamountoutstanding, 2)
            ELSE 0::numeric
        END) + sum(
        CASE
            WHEN loanrepaymentlist.gender::text = 'FEMALE'::text AND loanrepaymentlist.loanstatus::text = 'WRITTEN_OFF'::text THEN round(loanrepaymentlist.totalamountwrittenoff, 2)
            ELSE 0::numeric
        END) AS femalesum,
    sum(
        CASE
            WHEN loanrepaymentlist.gender::text = ''::text OR loanrepaymentlist.gender IS NULL THEN round(loanrepaymentlist.principalrepaid, 2)
            ELSE 0::numeric
        END) + sum(
        CASE
            WHEN (loanrepaymentlist.gender::text = ''::text OR loanrepaymentlist.gender IS NULL) AND loanrepaymentlist.principalrepaid = 0::numeric THEN round(loanrepaymentlist.totalamountoutstanding, 2)
            ELSE 0::numeric
        END) + sum(
        CASE
            WHEN (loanrepaymentlist.gender::text = ''::text OR loanrepaymentlist.gender IS NULL) AND loanrepaymentlist.loanstatus::text = 'WRITTEN_OFF'::text THEN round(loanrepaymentlist.totalamountwrittenoff, 2)
            ELSE 0::numeric
        END) AS nogendersum,
    sum(
        CASE
            WHEN loanrepaymentlist.gender::text = 'MALE'::text OR loanrepaymentlist.gender::text = 'FEMALE'::text OR loanrepaymentlist.gender::text = ''::text OR loanrepaymentlist.gender IS NULL THEN round(loanrepaymentlist.principalrepaid, 2)
            ELSE 0::numeric
        END) + sum(
        CASE
            WHEN (loanrepaymentlist.gender::text = 'MALE'::text OR loanrepaymentlist.gender::text = 'FEMALE'::text OR loanrepaymentlist.gender::text = ''::text OR loanrepaymentlist.gender IS NULL) AND loanrepaymentlist.principalrepaid = 0::numeric THEN round(loanrepaymentlist.totalamountoutstanding, 2)
            ELSE 0::numeric
        END) + sum(
        CASE
            WHEN (loanrepaymentlist.gender::text = 'MALE'::text OR loanrepaymentlist.gender::text = 'FEMALE'::text OR loanrepaymentlist.gender::text = ''::text OR loanrepaymentlist.gender IS NULL) AND loanrepaymentlist.loanstatus::text = 'WRITTEN_OFF'::text THEN round(loanrepaymentlist.totalamountwrittenoff, 2)
            ELSE 0::numeric
        END) AS totalsum
   FROM ( SELECT
                CASE
                    WHEN date_part('day'::text, l.lastpaidon - l.actualdisbursementdate) IS NULL THEN 'Balance'::text
                    WHEN date_part('day'::text, l.lastpaidon - l.actualdisbursementdate) <= 1::double precision THEN '1'::text
                    WHEN date_part('day'::text, l.lastpaidon - l.actualdisbursementdate) >= 2::double precision AND date_part('day'::text, l.lastpaidon - l.actualdisbursementdate) <= 15::double precision THEN '2 to 15'::text
                    WHEN date_part('day'::text, l.lastpaidon - l.actualdisbursementdate) >= 16::double precision AND date_part('day'::text, l.lastpaidon - l.actualdisbursementdate) <= 30::double precision THEN '16 to 30'::text
                    WHEN date_part('day'::text, l.lastpaidon - l.actualdisbursementdate) >= 31::double precision AND date_part('day'::text, l.lastpaidon - l.actualdisbursementdate) <= 90::double precision THEN '31 to 90'::text
                    ELSE 'Above 90'::text
                END AS loanrepayment,
            users.gender,
            l.principalrepaid,
            l.actualdisbursementdate::timestamp(0) without time zone AS actualdisbursementdate,
            l.totalamountoutstanding,
            l.totalamountwrittenoff,
            l.loanstatus,
            l.createdon::timestamp(0) without time zone AS createdon,
            l.loanproductid
           FROM loan l
             JOIN users ON l.userid::text = users.id::text AND date_part('year'::text, now()) = date_part('year'::text, l.actualdisbursementdate)) loanrepaymentlist
  WHERE loanrepaymentlist.loanproductid::text = 'e0cff44e-bf30-43cf-91ab-82b3f2446980'::text
  GROUP BY loanrepaymentlist.loanrepayment, (date_part('year'::text, loanrepaymentlist.actualdisbursementdate)), (
        CASE
            WHEN date_part('month'::text, loanrepaymentlist.actualdisbursementdate) = 1::double precision THEN 'January'::text
            WHEN date_part('month'::text, loanrepaymentlist.actualdisbursementdate) = 2::double precision THEN 'February'::text
            WHEN date_part('month'::text, loanrepaymentlist.actualdisbursementdate) = 3::double precision THEN 'March'::text
            WHEN date_part('month'::text, loanrepaymentlist.actualdisbursementdate) = 4::double precision THEN 'April'::text
            WHEN date_part('month'::text, loanrepaymentlist.actualdisbursementdate) = 5::double precision THEN 'May'::text
            WHEN date_part('month'::text, loanrepaymentlist.actualdisbursementdate) = 6::double precision THEN 'June'::text
            WHEN date_part('month'::text, loanrepaymentlist.actualdisbursementdate) = 7::double precision THEN 'July'::text
            WHEN date_part('month'::text, loanrepaymentlist.actualdisbursementdate) = 8::double precision THEN 'August'::text
            WHEN date_part('month'::text, loanrepaymentlist.actualdisbursementdate) = 9::double precision THEN 'September'::text
            WHEN date_part('month'::text, loanrepaymentlist.actualdisbursementdate) = 10::double precision THEN 'October'::text
            WHEN date_part('month'::text, loanrepaymentlist.actualdisbursementdate) = 11::double precision THEN 'November'::text
            WHEN date_part('month'::text, loanrepaymentlist.actualdisbursementdate) = 12::double precision THEN 'December'::text
            ELSE NULL::text
        END);


-- dashboard.mobilephoneloandisbursal source

CREATE OR REPLACE VIEW dashboard.mobilephoneloandisbursal
AS SELECT loandisbursaltimelist.loandisbursaltime AS timeofloandisbursal,
    date_part('year'::text, loandisbursaltimelist.createdon) AS year,
        CASE
            WHEN date_part('month'::text, loandisbursaltimelist.createdon) = 1::double precision THEN 'January'::text
            WHEN date_part('month'::text, loandisbursaltimelist.createdon) = 2::double precision THEN 'February'::text
            WHEN date_part('month'::text, loandisbursaltimelist.createdon) = 3::double precision THEN 'March'::text
            WHEN date_part('month'::text, loandisbursaltimelist.createdon) = 4::double precision THEN 'April'::text
            WHEN date_part('month'::text, loandisbursaltimelist.createdon) = 5::double precision THEN 'May'::text
            WHEN date_part('month'::text, loandisbursaltimelist.createdon) = 6::double precision THEN 'June'::text
            WHEN date_part('month'::text, loandisbursaltimelist.createdon) = 7::double precision THEN 'July'::text
            WHEN date_part('month'::text, loandisbursaltimelist.createdon) = 8::double precision THEN 'August'::text
            WHEN date_part('month'::text, loandisbursaltimelist.createdon) = 9::double precision THEN 'September'::text
            WHEN date_part('month'::text, loandisbursaltimelist.createdon) = 10::double precision THEN 'October'::text
            WHEN date_part('month'::text, loandisbursaltimelist.createdon) = 11::double precision THEN 'November'::text
            WHEN date_part('month'::text, loandisbursaltimelist.createdon) = 12::double precision THEN 'December'::text
            ELSE NULL::text
        END AS month,
    count(
        CASE
            WHEN loandisbursaltimelist.gender::text = 'MALE'::text THEN 1
            ELSE NULL::integer
        END) AS malecount,
    count(
        CASE
            WHEN loandisbursaltimelist.gender::text = 'FEMALE'::text THEN 1
            ELSE NULL::integer
        END) AS femalecount,
    count(
        CASE
            WHEN loandisbursaltimelist.gender::text = ''::text OR loandisbursaltimelist.gender IS NULL THEN 1
            ELSE NULL::integer
        END) AS nogendercount,
    count(
        CASE
            WHEN loandisbursaltimelist.gender::text = 'MALE'::text OR loandisbursaltimelist.gender::text = 'FEMALE'::text OR loandisbursaltimelist.gender::text = ''::text OR loandisbursaltimelist.gender IS NULL THEN 1
            ELSE NULL::integer
        END) AS totalcount,
    sum(
        CASE
            WHEN loandisbursaltimelist.gender::text = 'MALE'::text THEN round(loandisbursaltimelist.principaldisbursed, 2)
            ELSE 0::numeric
        END) AS malesum,
    sum(
        CASE
            WHEN loandisbursaltimelist.gender::text = 'FEMALE'::text THEN round(loandisbursaltimelist.principaldisbursed, 2)
            ELSE 0::numeric
        END) AS femalesum,
    sum(
        CASE
            WHEN loandisbursaltimelist.gender::text = ''::text OR loandisbursaltimelist.gender IS NULL THEN round(loandisbursaltimelist.principaldisbursed, 2)
            ELSE 0::numeric
        END) AS nogendersum,
    sum(
        CASE
            WHEN loandisbursaltimelist.gender::text = 'MALE'::text OR loandisbursaltimelist.gender::text = 'FEMALE'::text OR loandisbursaltimelist.gender::text = ''::text OR loandisbursaltimelist.gender IS NULL THEN round(loandisbursaltimelist.principaldisbursed, 2)
            ELSE 0::numeric
        END) AS totalsum
   FROM ( SELECT
                CASE
                    WHEN l.createdon::time without time zone >= '00:00:00'::time without time zone AND l.createdon::time without time zone <= '03:00:00'::time without time zone THEN '12:00 am - 3:00 am'::text
                    WHEN l.createdon::time without time zone >= '03:00:01'::time without time zone AND l.createdon::time without time zone <= '06:00:00'::time without time zone THEN '3:00 am - 6:00 am'::text
                    WHEN l.createdon::time without time zone >= '06:00:01'::time without time zone AND l.createdon::time without time zone <= '11:00:00'::time without time zone THEN '6:00 am - 11:00 am'::text
                    WHEN l.createdon::time without time zone >= '11:00:01'::time without time zone AND l.createdon::time without time zone <= '17:00:00'::time without time zone THEN '11:00 am - 05:00 pm'::text
                    WHEN l.createdon::time without time zone >= '17:00:01'::time without time zone AND l.createdon::time without time zone <= '23:59:59'::time without time zone THEN '5:00 pm - 11:59 pm'::text
                    ELSE NULL::text
                END AS loandisbursaltime,
            users.gender,
            l.principaldisbursed,
            l.createdon::timestamp(0) without time zone AS createdon,
            l.loanproductid
           FROM loan l
             JOIN users ON l.userid::text = users.id::text AND date_part('year'::text, now()) = date_part('year'::text, l.createdon)) loandisbursaltimelist
  WHERE loandisbursaltimelist.principaldisbursed IS NOT NULL AND loandisbursaltimelist.loanproductid::text = 'e0cff44e-bf30-43cf-91ab-82b3f2446980'::text
  GROUP BY loandisbursaltimelist.loandisbursaltime, (date_part('year'::text, loandisbursaltimelist.createdon)), (
        CASE
            WHEN date_part('month'::text, loandisbursaltimelist.createdon) = 1::double precision THEN 'January'::text
            WHEN date_part('month'::text, loandisbursaltimelist.createdon) = 2::double precision THEN 'February'::text
            WHEN date_part('month'::text, loandisbursaltimelist.createdon) = 3::double precision THEN 'March'::text
            WHEN date_part('month'::text, loandisbursaltimelist.createdon) = 4::double precision THEN 'April'::text
            WHEN date_part('month'::text, loandisbursaltimelist.createdon) = 5::double precision THEN 'May'::text
            WHEN date_part('month'::text, loandisbursaltimelist.createdon) = 6::double precision THEN 'June'::text
            WHEN date_part('month'::text, loandisbursaltimelist.createdon) = 7::double precision THEN 'July'::text
            WHEN date_part('month'::text, loandisbursaltimelist.createdon) = 8::double precision THEN 'August'::text
            WHEN date_part('month'::text, loandisbursaltimelist.createdon) = 9::double precision THEN 'September'::text
            WHEN date_part('month'::text, loandisbursaltimelist.createdon) = 10::double precision THEN 'October'::text
            WHEN date_part('month'::text, loandisbursaltimelist.createdon) = 11::double precision THEN 'November'::text
            WHEN date_part('month'::text, loandisbursaltimelist.createdon) = 12::double precision THEN 'December'::text
            ELSE NULL::text
        END);


-- dashboard.mobilephoneloansize source

CREATE OR REPLACE VIEW dashboard.mobilephoneloansize
AS SELECT loanrangelist.loanrange AS loansize,
    date_part('year'::text, loanrangelist.createdon) AS year,
        CASE
            WHEN date_part('month'::text, loanrangelist.createdon) = 1::double precision THEN 'January'::text
            WHEN date_part('month'::text, loanrangelist.createdon) = 2::double precision THEN 'February'::text
            WHEN date_part('month'::text, loanrangelist.createdon) = 3::double precision THEN 'March'::text
            WHEN date_part('month'::text, loanrangelist.createdon) = 4::double precision THEN 'April'::text
            WHEN date_part('month'::text, loanrangelist.createdon) = 5::double precision THEN 'May'::text
            WHEN date_part('month'::text, loanrangelist.createdon) = 6::double precision THEN 'June'::text
            WHEN date_part('month'::text, loanrangelist.createdon) = 7::double precision THEN 'July'::text
            WHEN date_part('month'::text, loanrangelist.createdon) = 8::double precision THEN 'August'::text
            WHEN date_part('month'::text, loanrangelist.createdon) = 9::double precision THEN 'September'::text
            WHEN date_part('month'::text, loanrangelist.createdon) = 10::double precision THEN 'October'::text
            WHEN date_part('month'::text, loanrangelist.createdon) = 11::double precision THEN 'November'::text
            WHEN date_part('month'::text, loanrangelist.createdon) = 12::double precision THEN 'December'::text
            ELSE NULL::text
        END AS month,
    count(
        CASE
            WHEN loanrangelist.gender::text = 'MALE'::text THEN 1
            ELSE NULL::integer
        END) AS malecount,
    count(
        CASE
            WHEN loanrangelist.gender::text = 'FEMALE'::text THEN 1
            ELSE NULL::integer
        END) AS femalecount,
    count(
        CASE
            WHEN loanrangelist.gender::text = ''::text OR loanrangelist.gender IS NULL THEN 1
            ELSE NULL::integer
        END) AS nogendercount,
    count(
        CASE
            WHEN loanrangelist.gender::text = 'MALE'::text OR loanrangelist.gender::text = 'FEMALE'::text OR loanrangelist.gender::text = ''::text OR loanrangelist.gender IS NULL THEN 1
            ELSE NULL::integer
        END) AS totalcount,
    sum(
        CASE
            WHEN loanrangelist.gender::text = 'MALE'::text THEN round(loanrangelist.principalgranted, 2)
            ELSE 0::numeric
        END) AS malesum,
    sum(
        CASE
            WHEN loanrangelist.gender::text = 'FEMALE'::text THEN round(loanrangelist.principalgranted, 2)
            ELSE 0::numeric
        END) AS femalesum,
    sum(
        CASE
            WHEN loanrangelist.gender::text = ''::text OR loanrangelist.gender IS NULL THEN round(loanrangelist.principalgranted, 2)
            ELSE 0::numeric
        END) AS nogendersum,
    sum(
        CASE
            WHEN loanrangelist.gender::text = 'MALE'::text OR loanrangelist.gender::text = 'FEMALE'::text OR loanrangelist.gender::text = ''::text OR loanrangelist.gender IS NULL THEN round(loanrangelist.principalgranted, 2)
            ELSE NULL::numeric
        END) AS totalsum
   FROM ( SELECT
                CASE
                    WHEN l.principalgranted >= 100::numeric AND l.principalgranted <= 5000::numeric THEN '100-5000'::text
                    WHEN l.principalgranted >= 5001::numeric AND l.principalgranted <= 10000::numeric THEN '5001-10000'::text
                    WHEN l.principalgranted >= 10001::numeric AND l.principalgranted <= 20000::numeric THEN '10001-20000'::text
                    WHEN l.principalgranted >= 20001::numeric AND l.principalgranted <= 50000::numeric THEN '20001-50000'::text
                    WHEN l.principalgranted >= 50001::numeric AND l.principalgranted <= 100000::numeric THEN '50001-100000'::text
                    WHEN l.principalgranted > 100001::numeric THEN '> 100001'::text
                    ELSE NULL::text
                END AS loanrange,
            users.gender,
            l.principalgranted,
            l.createdon::timestamp(0) without time zone AS createdon
           FROM loan l
             JOIN users ON l.userid::text = users.id::text AND date_part('year'::text, now()) = date_part('year'::text, l.createdon) AND l.loanproductid::text = 'e0cff44e-bf30-43cf-91ab-82b3f2446980'::text) loanrangelist
  GROUP BY loanrangelist.loanrange, (date_part('year'::text, loanrangelist.createdon)), (
        CASE
            WHEN date_part('month'::text, loanrangelist.createdon) = 1::double precision THEN 'January'::text
            WHEN date_part('month'::text, loanrangelist.createdon) = 2::double precision THEN 'February'::text
            WHEN date_part('month'::text, loanrangelist.createdon) = 3::double precision THEN 'March'::text
            WHEN date_part('month'::text, loanrangelist.createdon) = 4::double precision THEN 'April'::text
            WHEN date_part('month'::text, loanrangelist.createdon) = 5::double precision THEN 'May'::text
            WHEN date_part('month'::text, loanrangelist.createdon) = 6::double precision THEN 'June'::text
            WHEN date_part('month'::text, loanrangelist.createdon) = 7::double precision THEN 'July'::text
            WHEN date_part('month'::text, loanrangelist.createdon) = 8::double precision THEN 'August'::text
            WHEN date_part('month'::text, loanrangelist.createdon) = 9::double precision THEN 'September'::text
            WHEN date_part('month'::text, loanrangelist.createdon) = 10::double precision THEN 'October'::text
            WHEN date_part('month'::text, loanrangelist.createdon) = 11::double precision THEN 'November'::text
            WHEN date_part('month'::text, loanrangelist.createdon) = 12::double precision THEN 'December'::text
            ELSE NULL::text
        END);


