CREATE OR REPLACE VIEW dashboard.mobilephoneloantenor
AS SELECT loantenorlist.loantenor,
    date_part('year'::text, loantenorlist.createdon) AS year,
        CASE
            WHEN date_part('month'::text, loantenorlist.createdon) = 1::double precision THEN 'January'::text
            WHEN date_part('month'::text, loantenorlist.createdon) = 2::double precision THEN 'February'::text
            WHEN date_part('month'::text, loantenorlist.createdon) = 3::double precision THEN 'March'::text
            WHEN date_part('month'::text, loantenorlist.createdon) = 4::double precision THEN 'April'::text
            WHEN date_part('month'::text, loantenorlist.createdon) = 5::double precision THEN 'May'::text
            WHEN date_part('month'::text, loantenorlist.createdon) = 6::double precision THEN 'June'::text
            WHEN date_part('month'::text, loantenorlist.createdon) = 7::double precision THEN 'July'::text
            WHEN date_part('month'::text, loantenorlist.createdon) = 8::double precision THEN 'August'::text
            WHEN date_part('month'::text, loantenorlist.createdon) = 9::double precision THEN 'September'::text
            WHEN date_part('month'::text, loantenorlist.createdon) = 10::double precision THEN 'October'::text
            WHEN date_part('month'::text, loantenorlist.createdon) = 11::double precision THEN 'November'::text
            WHEN date_part('month'::text, loantenorlist.createdon) = 12::double precision THEN 'December'::text
            ELSE NULL::text
        END AS month,
    count(
        CASE
            WHEN loantenorlist.gender::text = 'MALE'::text THEN 1
            ELSE NULL::integer
        END) AS malecount,
    count(
        CASE
            WHEN loantenorlist.gender::text = 'FEMALE'::text THEN 1
            ELSE NULL::integer
        END) AS femalecount,
    count(
        CASE
            WHEN loantenorlist.gender::text = ''::text OR loantenorlist.gender IS NULL THEN 1
            ELSE NULL::integer
        END) AS nogendercount,
    count(
        CASE
            WHEN loantenorlist.gender::text = 'MALE'::text OR loantenorlist.gender::text = 'FEMALE'::text OR loantenorlist.gender::text = ''::text OR loantenorlist.gender IS NULL THEN 1
            ELSE NULL::integer
        END) AS totalcount,
    sum(
        CASE
            WHEN loantenorlist.gender::text = 'MALE'::text THEN round(loantenorlist.principalgranted, 2)
            ELSE 0::numeric
        END) AS malesum,
    sum(
        CASE
            WHEN loantenorlist.gender::text = 'FEMALE'::text THEN round(loantenorlist.principalgranted, 2)
            ELSE 0::numeric
        END) AS femalesum,
    sum(
        CASE
            WHEN loantenorlist.gender::text = ''::text OR loantenorlist.gender IS NULL THEN round(loantenorlist.principalgranted, 2)
            ELSE 0::numeric
        END) AS nogendersum,
    sum(
        CASE
            WHEN loantenorlist.gender::text = 'MALE'::text OR loantenorlist.gender::text = 'FEMALE'::text OR loantenorlist.gender::text = ''::text OR loantenorlist.gender IS NULL THEN round(loantenorlist.principalgranted, 2)
            ELSE 0::numeric
        END) AS totalsum,
        CASE
            WHEN loantenorlist.loanpurpose IS NULL THEN 'Personal'::text
            ELSE 'Personal'::text
        END AS "Purpose"
   FROM ( SELECT
                CASE
                    WHEN l.loanperiod < 1 THEN '<1'::text
                    WHEN l.loanperiod = 1 THEN '1'::text
                    WHEN l.loanperiod >= 2 AND l.loanperiod <= 3 THEN '2-3'::text
                    WHEN l.loanperiod > 3 THEN '>3'::text
                    ELSE NULL::text
                END AS loantenor,
            users.gender,
            l.loanpurpose,
            l.principalgranted,
            l.createdon::timestamp(0) without time zone AS createdon,
            l.loanproductid
           FROM loan l
             JOIN users ON l.userid::text = users.id::text AND date_part('year'::text, now()) = date_part('year'::text, l.createdon)) loantenorlist
  WHERE loantenorlist.loanproductid::text = 'e0cff44e-bf30-43cf-91ab-82b3f2446980'::text
  GROUP BY loantenorlist.loantenor, (date_part('year'::text, loantenorlist.createdon)), (
        CASE
            WHEN date_part('month'::text, loantenorlist.createdon) = 1::double precision THEN 'January'::text
            WHEN date_part('month'::text, loantenorlist.createdon) = 2::double precision THEN 'February'::text
            WHEN date_part('month'::text, loantenorlist.createdon) = 3::double precision THEN 'March'::text
            WHEN date_part('month'::text, loantenorlist.createdon) = 4::double precision THEN 'April'::text
            WHEN date_part('month'::text, loantenorlist.createdon) = 5::double precision THEN 'May'::text
            WHEN date_part('month'::text, loantenorlist.createdon) = 6::double precision THEN 'June'::text
            WHEN date_part('month'::text, loantenorlist.createdon) = 7::double precision THEN 'July'::text
            WHEN date_part('month'::text, loantenorlist.createdon) = 8::double precision THEN 'August'::text
            WHEN date_part('month'::text, loantenorlist.createdon) = 9::double precision THEN 'September'::text
            WHEN date_part('month'::text, loantenorlist.createdon) = 10::double precision THEN 'October'::text
            WHEN date_part('month'::text, loantenorlist.createdon) = 11::double precision THEN 'November'::text
            WHEN date_part('month'::text, loantenorlist.createdon) = 12::double precision THEN 'December'::text
            ELSE NULL::text
        END), (
        CASE
            WHEN loantenorlist.loanpurpose IS NULL THEN 'Personal'::text
            ELSE 'Personal'::text
        END);


-- dashboard.mpesab2bexceptionreport source

CREATE OR REPLACE VIEW dashboard.mpesab2bexceptionreport
AS SELECT date(w.txtime) AS "Date",
    w.txtime::timestamp(0) without time zone::time without time zone AS "Time",
    fsi.transactionid AS "MpesaRef",
    concat(w.businesstrxid, ' / ', w.executionid) AS "TrxBatchID",
        CASE
            WHEN w.debitamount > 0::numeric THEN round(w.creditamount + w.debitamount, 2) * '-1'::integer::numeric
            ELSE round(w.creditamount + w.debitamount, 2)
        END AS "TrxAmount",
        CASE
            WHEN w.debitamount > 0::numeric THEN 'Debit'::text
            WHEN w.creditamount > 0::numeric THEN 'Credit'::text
            ELSE NULL::text
        END AS "TrxType",
        CASE
            WHEN w.description IS NULL OR w.description::text = ''::text THEN bp.name
            ELSE w.description
        END AS "TrxNarration",
    wt.glaccountnumber AS "GLID",
    fsi.mobilenumber AS "Mobile",
    concat('Failed - ', fsi.resultdesc) AS "Status"
   FROM mpesafsi fsi
     JOIN wallettransactions w ON fsi.originatorconversationid::text = w.externalrefid::text
     LEFT JOIN wallettype wt ON w.wallettypeid::text = wt.id::text
     LEFT JOIN businessproduct bp ON w.businessproductid::text = bp.id::text
  WHERE fsi.requesttype::text <> 'B2C'::text AND w.transactionstatus::text <> 'PROCESSED'::text
  ORDER BY w.txtime DESC, w.businesstrxid;


-- dashboard.mpesab2breport source

CREATE OR REPLACE VIEW dashboard.mpesab2breport
AS SELECT date(w.txtime) AS date,
    w.txtime::timestamp(0) without time zone::time without time zone AS "time",
    fsi.transactionid AS mpesaref,
    concat(w.businesstrxid, ' / ', w.executionid) AS trxbatchid,
        CASE
            WHEN w.debitamount > 0::numeric THEN round(w.creditamount + w.debitamount, 2) * '-1'::integer::numeric
            ELSE round(w.creditamount + w.debitamount, 2)
        END AS trxamount,
        CASE
            WHEN w.debitamount > 0::numeric THEN 'Debit'::text
            WHEN w.creditamount > 0::numeric THEN 'Credit'::text
            ELSE NULL::text
        END AS trxtype,
        CASE
            WHEN w.description IS NULL OR w.description::text = ''::text THEN bp.name
            ELSE w.description
        END AS trxnarration,
    wt.glaccountnumber AS glid,
    fsi.mobilenumber AS mobile,
        CASE
            WHEN w.chargebackbyid IS NOT NULL AND w.transactionstatus::text = 'PROCESSED'::text THEN 'Chargeback'::text
            WHEN w.transactionstatus::text = 'PROCESSED'::text THEN 'Success'::text
            ELSE concat('Failed - ', fsi.resultdesc)
        END AS status
   FROM mpesafsi fsi
     JOIN wallettransactions w ON fsi.originatorconversationid::text = w.externalrefid::text
     LEFT JOIN wallettype wt ON w.wallettypeid::text = wt.id::text
     LEFT JOIN businessproduct bp ON w.businessproductid::text = bp.id::text
  WHERE fsi.requesttype::text <> 'B2C'::text
  ORDER BY w.txtime DESC, w.businesstrxid;


-- dashboard.mpesab2cexceptionreport source

CREATE OR REPLACE VIEW dashboard.mpesab2cexceptionreport
AS SELECT date(w.txtime) AS "Date",
    w.txtime::timestamp(0) without time zone::time without time zone AS "Time",
    fsi.transactionid AS "MpesaRef",
    concat(w.businesstrxid, ' / ', w.executionid) AS "TrxBatchID",
        CASE
            WHEN w.debitamount > 0::numeric THEN round(w.debitamount + w.creditamount, 2) * '-1'::integer::numeric
            ELSE round(w.debitamount + w.creditamount, 2)
        END AS "TrxAmount",
        CASE
            WHEN w.creditamount > 0::numeric THEN 'Credit'::text
            WHEN w.debitamount > 0::numeric THEN 'Debit'::text
            ELSE NULL::text
        END AS "TrxType",
        CASE
            WHEN w.description IS NULL OR w.description::text = ''::text THEN bp.name
            ELSE w.description
        END AS "TrxNarration",
    wt.glaccountnumber AS "GLID",
    fsi.mobilenumber AS "Mobile",
    concat('Failed - ', fsi.resultdesc) AS "Status"
   FROM mpesafsi fsi
     JOIN wallettransactions w ON fsi.originatorconversationid::text = w.externalrefid::text
     LEFT JOIN wallettype wt ON w.wallettypeid::text = wt.id::text
     LEFT JOIN businessproduct bp ON w.businessproductid::text = bp.id::text
  WHERE fsi.requesttype::text = 'B2C'::text AND w.transactionstatus::text <> 'PROCESSED'::text
  ORDER BY w.txtime DESC, w.businesstrxid;


-- dashboard.mpesab2creport source

CREATE OR REPLACE VIEW dashboard.mpesab2creport
AS SELECT date(w.txtime) AS date,
    w.txtime::timestamp(0) without time zone::time without time zone AS "time",
    fsi.transactionid AS mpesaref,
    concat(w.businesstrxid, ' / ', w.executionid) AS trxbatchid,
        CASE
            WHEN w.debitamount > 0::numeric THEN round(w.debitamount + w.creditamount, 2) * '-1'::integer::numeric
            ELSE round(w.debitamount + w.creditamount, 2)
        END AS trxamount,
        CASE
            WHEN w.creditamount > 0::numeric THEN 'Credit'::text
            WHEN w.debitamount > 0::numeric THEN 'Debit'::text
            ELSE NULL::text
        END AS trxtype,
        CASE
            WHEN w.description IS NULL OR w.description::text = ''::text THEN bp.name
            ELSE w.description
        END AS trxnarration,
    wt.glaccountnumber AS glid,
    fsi.mobilenumber AS mobile,
        CASE
            WHEN w.chargebackbyid IS NOT NULL AND w.transactionstatus::text = 'PROCESSED'::text THEN 'Chargeback'::text
            WHEN w.transactionstatus::text = 'PROCESSED'::text THEN 'Success'::text
            ELSE concat('Failed - ', fsi.resultdesc)
        END AS status
   FROM mpesafsi fsi
     JOIN wallettransactions w ON fsi.originatorconversationid::text = w.externalrefid::text
     LEFT JOIN wallettype wt ON w.wallettypeid::text = wt.id::text
     LEFT JOIN businessproduct bp ON w.businessproductid::text = bp.id::text
  WHERE fsi.requesttype::text = 'B2C'::text
  ORDER BY w.txtime DESC, w.businesstrxid;


-- dashboard.mpesac2bexceptionreport source

CREATE OR REPLACE VIEW dashboard.mpesac2bexceptionreport
AS SELECT date(mb.requesttime) AS "Date",
    mb.requesttime::timestamp(0) without time zone::time without time zone AS "Time",
    mb.merchantrequestid AS "MpesaRef",
    'N/A'::text AS "Transaction ID/Batch ID",
        CASE
            WHEN (array_to_json(ARRAY[to_json(mb.paymentrequest::json -> 'amount'::text)]) ->> 0) IS NULL THEN '0'::text
            ELSE array_to_json(ARRAY[to_json(mb.paymentrequest::json -> 'amount'::text)]) ->> 0
        END AS "Transaction Amount",
    'N/A'::text AS "Transaction Type",
    'N/A'::text AS "Transaction Narration",
    'N/A'::text AS "GLID",
    array_to_json(ARRAY[to_json(mb.paymentrequest::json -> 'phoneNumber'::text)]) ->> 0 AS "Mobile",
        CASE
            WHEN mb.callbackresponse IS NULL THEN mb.paymentresponse::json -> 'errorMessage'::text
            ELSE ((mb.callbackresponse::json -> 'body'::text) -> 'stkCallback'::text) -> 'resultDesc'::text
        END AS "Description"
   FROM mpesac2bpayment mb
  WHERE mb.sourcetype::text <> 'LOAN'::text AND (mb.callbackresultcode::text <> '0.0'::text OR mb.callbackresultcode IS NULL)
  ORDER BY mb.requesttime DESC, mb.id;


-- dashboard.mpesac2btracker source

CREATE OR REPLACE VIEW dashboard.mpesac2btracker
AS SELECT mcb.callbackresultcode,
    date(mcb.requesttime) AS date,
    mcb.requesttime::timestamp(0) without time zone::time without time zone AS "time",
    mcb.requesttime,
    array_to_json(ARRAY[to_json(mcb.paymentrequest::json -> 'phoneNumber'::text)]) ->> 0 AS mobile,
    array_to_json(ARRAY[to_json(mcb.paymentresponse::json -> 'errorCode'::text)]) ->> 0 AS errorcode,
    array_to_json(ARRAY[to_json(mcb.paymentresponse::json -> 'responseCode'::text)]) ->> 0 AS responsecode
   FROM mpesac2bpayment mcb
  WHERE date(mcb.requesttime) >= '2021-09-01'::date;


-- dashboard.nonperformingloans source

CREATE OR REPLACE VIEW dashboard.nonperformingloans
AS SELECT daysatrisklist.daysatrisk,
    date_part('year'::text, daysatrisklist.actualdisbursementdate) AS year,
        CASE
            WHEN date_part('month'::text, daysatrisklist.actualdisbursementdate) = 1::double precision THEN 'January'::text
            WHEN date_part('month'::text, daysatrisklist.actualdisbursementdate) = 2::double precision THEN 'February'::text
            WHEN date_part('month'::text, daysatrisklist.actualdisbursementdate) = 3::double precision THEN 'March'::text
            WHEN date_part('month'::text, daysatrisklist.actualdisbursementdate) = 4::double precision THEN 'April'::text
            WHEN date_part('month'::text, daysatrisklist.actualdisbursementdate) = 5::double precision THEN 'May'::text
            WHEN date_part('month'::text, daysatrisklist.actualdisbursementdate) = 6::double precision THEN 'June'::text
            WHEN date_part('month'::text, daysatrisklist.actualdisbursementdate) = 7::double precision THEN 'July'::text
            WHEN date_part('month'::text, daysatrisklist.actualdisbursementdate) = 8::double precision THEN 'August'::text
            WHEN date_part('month'::text, daysatrisklist.actualdisbursementdate) = 9::double precision THEN 'September'::text
            WHEN date_part('month'::text, daysatrisklist.actualdisbursementdate) = 10::double precision THEN 'October'::text
            WHEN date_part('month'::text, daysatrisklist.actualdisbursementdate) = 11::double precision THEN 'November'::text
            WHEN date_part('month'::text, daysatrisklist.actualdisbursementdate) = 12::double precision THEN 'December'::text
            ELSE NULL::text
        END AS month,
    count(
        CASE
            WHEN daysatrisklist.gender::text = 'MALE'::text THEN 1
            ELSE NULL::integer
        END) AS malecount,
    count(
        CASE
            WHEN daysatrisklist.gender::text = 'FEMALE'::text THEN 1
            ELSE NULL::integer
        END) AS femalecount,
    count(
        CASE
            WHEN daysatrisklist.gender::text = ''::text OR daysatrisklist.gender IS NULL THEN 1
            ELSE NULL::integer
        END) AS nogendercount,
    count(
        CASE
            WHEN daysatrisklist.gender::text = 'MALE'::text OR daysatrisklist.gender::text = 'FEMALE'::text OR daysatrisklist.gender::text = ''::text OR daysatrisklist.gender IS NULL THEN 1
            ELSE NULL::integer
        END) AS totalcount,
    sum(
        CASE
            WHEN daysatrisklist.gender::text = 'MALE'::text AND daysatrisklist.loanstatus::text = 'ACTIVE'::text THEN round(daysatrisklist.totalamountoutstanding, 2)
            ELSE 0::numeric
        END) + sum(
        CASE
            WHEN daysatrisklist.gender::text = 'MALE'::text AND daysatrisklist.loanstatus::text = 'WRITTEN_OFF'::text THEN round(daysatrisklist.totalamountwrittenoff, 2)
            ELSE 0::numeric
        END) AS malesum,
    sum(
        CASE
            WHEN daysatrisklist.gender::text = 'FEMALE'::text AND daysatrisklist.loanstatus::text = 'ACTIVE'::text THEN round(daysatrisklist.totalamountoutstanding, 2)
            ELSE 0::numeric
        END) + sum(
        CASE
            WHEN daysatrisklist.gender::text = 'FEMALE'::text AND daysatrisklist.loanstatus::text = 'WRITTEN_OFF'::text THEN round(daysatrisklist.totalamountwrittenoff, 2)
            ELSE 0::numeric
        END) AS femalesum,
    sum(
        CASE
            WHEN (daysatrisklist.gender::text = ''::text OR daysatrisklist.gender IS NULL) AND daysatrisklist.loanstatus::text = 'ACTIVE'::text THEN round(daysatrisklist.totalamountoutstanding, 2)
            ELSE 0::numeric
        END) + sum(
        CASE
            WHEN (daysatrisklist.gender::text = ''::text OR daysatrisklist.gender IS NULL) AND daysatrisklist.loanstatus::text = 'WRITTEN_OFF'::text THEN round(daysatrisklist.totalamountwrittenoff, 2)
            ELSE 0::numeric
        END) AS nogendersum,
    sum(
        CASE
            WHEN (daysatrisklist.gender::text = 'MALE'::text OR daysatrisklist.gender::text = 'FEMALE'::text OR daysatrisklist.gender::text = ''::text OR daysatrisklist.gender IS NULL) AND daysatrisklist.loanstatus::text = 'ACTIVE'::text THEN round(daysatrisklist.totalamountoutstanding, 2)
            ELSE 0::numeric
        END) + sum(
        CASE
            WHEN (daysatrisklist.gender::text = 'MALE'::text OR daysatrisklist.gender::text = 'FEMALE'::text OR daysatrisklist.gender::text = ''::text OR daysatrisklist.gender IS NULL) AND daysatrisklist.loanstatus::text = 'WRITTEN_OFF'::text THEN round(daysatrisklist.totalamountwrittenoff, 2)
            ELSE 0::numeric
        END) AS totalsum
   FROM ( SELECT
                CASE
                    WHEN date_part('day'::text, now() - l2.duedate::timestamp with time zone) <= 0::double precision THEN '0'::text
                    WHEN date_part('day'::text, now() - l2.duedate::timestamp with time zone) >= 1::double precision AND date_part('day'::text, now() - l2.duedate::timestamp with time zone) <= 30::double precision THEN '1 to 30'::text
                    WHEN date_part('day'::text, now() - l2.duedate::timestamp with time zone) >= 31::double precision AND date_part('day'::text, now() - l2.duedate::timestamp with time zone) <= 60::double precision THEN '31 to 60'::text
                    WHEN date_part('day'::text, now() - l2.duedate::timestamp with time zone) >= 61::double precision AND date_part('day'::text, now() - l2.duedate::timestamp with time zone) <= 90::double precision THEN '61 to 90'::text
                    ELSE '> 90'::text
                END AS daysatrisk,
            users.gender,
            l.principalrepaid,
            l.actualdisbursementdate,
            l.totalamountoutstanding,
            l.totalamountwrittenoff,
            l2.amountdue,
            l.loanstatus
           FROM loan l
             JOIN loanschedule l2 ON l.id::text = l2.loanid::text
             JOIN users ON l.userid::text = users.id::text
          WHERE date_part('year'::text, now()) = date_part('year'::text, l.actualdisbursementdate) AND l.loanstatus::text <> 'CLOSED'::text) daysatrisklist
  GROUP BY daysatrisklist.daysatrisk, (date_part('year'::text, daysatrisklist.actualdisbursementdate)), (
        CASE
            WHEN date_part('month'::text, daysatrisklist.actualdisbursementdate) = 1::double precision THEN 'January'::text
            WHEN date_part('month'::text, daysatrisklist.actualdisbursementdate) = 2::double precision THEN 'February'::text
            WHEN date_part('month'::text, daysatrisklist.actualdisbursementdate) = 3::double precision THEN 'March'::text
            WHEN date_part('month'::text, daysatrisklist.actualdisbursementdate) = 4::double precision THEN 'April'::text
            WHEN date_part('month'::text, daysatrisklist.actualdisbursementdate) = 5::double precision THEN 'May'::text
            WHEN date_part('month'::text, daysatrisklist.actualdisbursementdate) = 6::double precision THEN 'June'::text
            WHEN date_part('month'::text, daysatrisklist.actualdisbursementdate) = 7::double precision THEN 'July'::text
            WHEN date_part('month'::text, daysatrisklist.actualdisbursementdate) = 8::double precision THEN 'August'::text
            WHEN date_part('month'::text, daysatrisklist.actualdisbursementdate) = 9::double precision THEN 'September'::text
            WHEN date_part('month'::text, daysatrisklist.actualdisbursementdate) = 10::double precision THEN 'October'::text
            WHEN date_part('month'::text, daysatrisklist.actualdisbursementdate) = 11::double precision THEN 'November'::text
            WHEN date_part('month'::text, daysatrisklist.actualdisbursementdate) = 12::double precision THEN 'December'::text
            ELSE NULL::text
        END);


-- dashboard.p2ptransactions source

CREATE OR REPLACE VIEW dashboard.p2ptransactions
AS SELECT wt.executionid
   FROM wallettransactions wt,
    businessproduct bp
  WHERE wt.businessproductid::text ~~ bp.id::text AND wt.parentid IS NULL AND wt.chargebackofid IS NULL AND bp.bpcode::text ~~ 'SNDMNY'::text AND wt.transactionstatus::text ~~ 'PROCESSED'::text;


-- dashboard.pinstatusreport source

CREATE OR REPLACE VIEW dashboard.pinstatusreport
AS SELECT usr.username AS mobilenumber,
    usr.passwordexpirydate,
        CASE
            WHEN usr.passwordexpirydate >= now() THEN 'Active'::text
            ELSE 'Expired'::text
        END AS pinstatus,
    usr.userstatus AS customerstatus
   FROM users usr
     JOIN role rl ON usr.roleid::text = rl.id::text AND rl.roletype::text <> 'OPERATION'::text;


-- dashboard.productionreport source

CREATE OR REPLACE VIEW dashboard.productionreport
AS SELECT concat(ins.firstname, ' ', ins.lastname) AS clientname,
    date(usr.dob) AS dateofbirth,
    ins.idnumber,
    usr.gender,
    ins.premiumamount,
    ins.mobilenumber,
    ins.status,
    ins.createdon::timestamp(0) without time zone AS createdon
   FROM insurancesubscription ins,
    users usr
  WHERE ins.userid::text = usr.id::text;


-- dashboard.rdaccrualcountforprocessing source

CREATE OR REPLACE VIEW dashboard.rdaccrualcountforprocessing
AS SELECT d.id,
    d.depositproductassociationid,
    d.depositproductid,
    d.acuraldonetill,
    d.totalinterestaccured,
    d.interestpendingdisbursal,
    d.totalinterestdisbursed,
    d.interestdisbursedlastcycle,
    d.dailyaccuralamount,
    d.depositamount,
    d.producttype,
    d.accountstatus,
    d.interestdisbursaldate,
    d.maturitydate,
    d.lastinterestdisburseddate,
    d.userid,
    d.createdon,
    d.modifiedon,
    d.totalinterestaccuredonamountbonus,
    d.interestpendingdisbursalonamountbonus,
    d.totalinterestdisbursedonamountbonus,
    d.interestdisbursedlastcycleonamountbonus,
    d.totalinterestaccuredonmaturity,
    d.interestpendingdisbursalonmaturity,
    d.totalinterestdisbursedonmaturity,
    d.interestdisbursedlastcycleonmaturity,
    d.totalinterestaccuredonpoolamount,
    d.interestpendingdisbursalonpoolamount,
    d.dailyaccuraltermbonusamount,
    d.dailyaccuralamountbonusamount
   FROM depositaccural d
     JOIN rdproductassociation r ON d.depositproductassociationid::text = r.id::text AND d.depositproductid::text = 'cbc82b05-34c8-4e2a-9b65-ce31fd2632b8'::text AND d.producttype::text = 'RECURRING'::text AND date(d.acuraldonetill) < date(now()) AND d.accountstatus::text = 'ACTIVE'::text;


-- dashboard.registrations source

CREATE OR REPLACE VIEW dashboard.registrations
AS SELECT users.createdon,
    users.username,
    users.firstname,
    users.middlename,
    users.lastname
   FROM users
  WHERE users.userstatus::text = 'ACTIVE'::text AND users.kycstatus::text = 'KYC_DONE'::text AND date(users.createdon) = date(now());


-- dashboard.savingsaccountreport source

CREATE OR REPLACE VIEW dashboard.savingsaccountreport
AS SELECT usr.username AS clientid,
    rdpa.rdaccountno AS accountid,
    concat('254', usr.username) AS mobilenumber,
    concat(usr.firstname, ' ', usr.lastname) AS accountname,
    rdp.productnumber AS productid,
    round(rdpa.totalamountdeposited, 2) AS accountbalance,
    rdpa.createdon::timestamp(0) without time zone AS createdon,
    usr.userstatus AS accountstatus,
    '1'::text AS noofgoals,
    rdpa.accountstatus AS isactive,
    rdpa.targetamount AS "Target Amount",
    rdpa.savingperiod AS "Savings Term (In Months)"
   FROM rdproductassociation rdpa
     LEFT JOIN users usr ON rdpa.userid::text = usr.id::text
     LEFT JOIN rdproduct rdp ON rdpa.productid::text = rdp.id::text;


-- dashboard.staticlimituploadreport source

CREATE OR REPLACE VIEW dashboard.staticlimituploadreport
AS SELECT concat(u.firstname, ' ', u.lastname) AS customername,
    concat('254', blr.mobilenumber) AS mobilenumber,
    round(blr.newlimit, 2) AS newlimit,
    date(blr.limitexpirydate) AS limitexpirydate,
    c.riskcategory AS assessment,
        CASE
            WHEN blr.executionstatus::text = 'EXECUTED_SUCCESS'::text THEN 'Success'::text
            ELSE 'Failure'::text
        END AS updatestatus,
    blb.id AS uploadbatchid,
    blr.createdon::timestamp(0) without time zone AS createdon,
    ( SELECT u_1.username
           FROM users u_1
          WHERE u_1.id::text = blr.createdby::text) AS createdby,
    blr.modifiedon::timestamp(0) without time zone AS supervisedon,
    ( SELECT u_1.username
           FROM users u_1
          WHERE u_1.id::text = blr.modifiedby::text) AS supervisedby
   FROM users u,
    creditlimit c,
    bulklendinglimitrecord blr,
    bulklendinglimitjob blb
  WHERE u.id::text = c.userid::text AND u.username::text = blr.mobilenumber::text AND blr.bulklendinglimitjobid::text = blb.id::text AND (blr.executionstatus::text = 'EXECUTED_SUCCESS'::text OR blr.executionstatus::text = 'EXECUTED_ERROR'::text);


-- dashboard.temporarylimittable source

CREATE OR REPLACE VIEW dashboard.temporarylimittable
AS SELECT concat(usr.firstname, ' ', usr.lastname) AS "Customer Name",
    concat('254', usr.username) AS "Mobile Number",
    round(clp.creditlimit, 2) AS "Limit Amount (New)",
    clp.createdon::timestamp(0) without time zone AS limitdate,
    clp.riskcategory AS "Assessment",
    round(cl.creditlimit, 2) AS "Old Limit Amount",
    cl.riskcategory AS "Old Assessment",
    clp.status AS "Status"
   FROM users usr
     JOIN creditlimit cl ON usr.id::text = cl.userid::text
     JOIN creditlimitpending clp ON usr.id::text = clp.userid::text;


-- dashboard.termloandisbursedduringday source

CREATE OR REPLACE VIEW dashboard.termloandisbursedduringday
AS SELECT loandisbursaltimelist.loandisbursaltime AS timeofloandisbursal,
    sum(loandisbursaltimelist.principaldisbursed) AS disbursalamount
   FROM ( SELECT
                CASE
                    WHEN date_part('hour'::text, loan.createdon) >= 0::double precision AND date_part('hour'::text, loan.createdon) <= 6::double precision THEN '12:00 am - 6:00 am'::text
                    WHEN date_part('hour'::text, loan.createdon) >= 6::double precision AND date_part('hour'::text, loan.createdon) <= 12::double precision THEN '6:00 am - 12:00 pm'::text
                    WHEN date_part('hour'::text, loan.createdon) >= 12::double precision AND date_part('hour'::text, loan.createdon) <= 18::double precision THEN '12:00 pm - 6:00 pm'::text
                    WHEN date_part('hour'::text, loan.createdon) >= 18::double precision AND date_part('hour'::text, loan.createdon) <= 23.59::double precision THEN '6:00 pm - 12:00 am'::text
                    ELSE NULL::text
                END AS loandisbursaltime,
            loan.principaldisbursed,
            loan.loanproductid,
            loan.createdon
           FROM loan) loandisbursaltimelist
  WHERE loandisbursaltimelist.principaldisbursed IS NOT NULL AND loandisbursaltimelist.loanproductid::text ~~ '68e8db46-c420-4e90-8ef0-2a48c50f9e65'::text AND date(loandisbursaltimelist.createdon) = date(now())
  GROUP BY loandisbursaltimelist.loandisbursaltime;


-- dashboard.thirtydayloandisbursedduringday source

CREATE OR REPLACE VIEW dashboard.thirtydayloandisbursedduringday
AS SELECT loandisbursaltimelist.loandisbursaltime AS timeofloandisbursal,
    sum(loandisbursaltimelist.principaldisbursed) AS disbursalamount
   FROM ( SELECT
                CASE
                    WHEN date_part('hour'::text, loan.createdon) >= 0::double precision AND date_part('hour'::text, loan.createdon) <= 6::double precision THEN '12:00 am - 6:00 am'::text
                    WHEN date_part('hour'::text, loan.createdon) >= 6::double precision AND date_part('hour'::text, loan.createdon) <= 12::double precision THEN '6:00 am - 12:00 pm'::text
                    WHEN date_part('hour'::text, loan.createdon) >= 12::double precision AND date_part('hour'::text, loan.createdon) <= 18::double precision THEN '12:00 pm - 6:00 pm'::text
                    WHEN date_part('hour'::text, loan.createdon) >= 18::double precision AND date_part('hour'::text, loan.createdon) <= 23.59::double precision THEN '6:00 pm - 12:00 am'::text
                    ELSE NULL::text
                END AS loandisbursaltime,
            loan.principaldisbursed,
            loan.loanproductid,
            loan.createdon
           FROM loan) loandisbursaltimelist
  WHERE loandisbursaltimelist.principaldisbursed IS NOT NULL AND loandisbursaltimelist.loanproductid::text ~~ 'e0cff44e-bf30-43cf-91ab-82b3f2446980'::text AND date(loandisbursaltimelist.createdon) = date(now())
  GROUP BY loandisbursaltimelist.loandisbursaltime;


-- dashboard.totaltimizaregistration source

CREATE OR REPLACE VIEW dashboard.totaltimizaregistration
AS SELECT usr.id
   FROM users usr
     JOIN role rl ON usr.roleid::text = rl.id::text AND rl.roletype::text <> 'OPERATION'::text;


-- dashboard.trxountdb source

CREATE OR REPLACE VIEW dashboard.trxountdb
AS SELECT w.executionid,
        CASE
            WHEN w.transactionstatus::text = 'PROCESSED'::text THEN 'Successful'::text
            ELSE 'Failed'::text
        END AS status
   FROM wallettransactions w
  WHERE w.parentid IS NULL AND w.chargebackofid IS NULL AND w.transactionstatus IS NOT NULL;


-- dashboard.trxsummarydb source

CREATE OR REPLACE VIEW dashboard.trxsummarydb
AS SELECT 'Airtime Purchase'::text AS name,
    round(sum(wt.debitamount), 2) AS amount
   FROM businessproduct bp
     LEFT JOIN wallettransactions wt ON bp.id::text = wt.businessproductid::text
  WHERE wt.parentid IS NULL AND wt.chargebackofid IS NULL AND wt.debitamount > 0::numeric AND wt.transactionstatus::text = 'PROCESSED'::text AND date(wt.createdon) = date(now()) AND bp.bpcode::text <> 'BPTIM'::text AND bp.name::text = 'Airtime Purchase'::text
UNION ALL
 SELECT 'Bill Payment'::text AS name,
    round(sum(wt.debitamount), 2) AS amount
   FROM businessproduct bp
     LEFT JOIN wallettransactions wt ON bp.id::text = wt.businessproductid::text
  WHERE wt.parentid IS NULL AND wt.chargebackofid IS NULL AND wt.debitamount > 0::numeric AND wt.transactionstatus::text = 'PROCESSED'::text AND date(wt.createdon) = date(now()) AND bp.bpcode::text <> 'BPTIM'::text AND bp.name::text = 'Bill Payment'::text
UNION ALL
 SELECT 'Withdraw to ATM Cashout'::text AS name,
    round(sum(wt.debitamount), 2) AS amount
   FROM businessproduct bp
     LEFT JOIN wallettransactions wt ON bp.id::text = wt.businessproductid::text
  WHERE wt.parentid IS NULL AND wt.chargebackofid IS NULL AND wt.debitamount > 0::numeric AND wt.transactionstatus::text = 'PROCESSED'::text AND date(wt.createdon) = date(now()) AND bp.bpcode::text <> 'BPTIM'::text AND bp.name::text = 'Withdraw to ATM Cashout'::text
UNION ALL
 SELECT 'MerchantPayment using tillno'::text AS name,
    round(sum(wt.debitamount), 2) AS amount
   FROM businessproduct bp
     LEFT JOIN wallettransactions wt ON bp.id::text = wt.businessproductid::text
  WHERE wt.parentid IS NULL AND wt.chargebackofid IS NULL AND wt.debitamount > 0::numeric AND wt.transactionstatus::text = 'PROCESSED'::text AND date(wt.createdon) = date(now()) AND bp.bpcode::text <> 'BPTIM'::text AND bp.name::text = 'MerchantPayment using tillno'::text
UNION ALL
 SELECT 'Send Money P2P'::text AS name,
    round(sum(wt.debitamount), 2) AS amount
   FROM businessproduct bp
     LEFT JOIN wallettransactions wt ON bp.id::text = wt.businessproductid::text
  WHERE wt.parentid IS NULL AND wt.chargebackofid IS NULL AND wt.debitamount > 0::numeric AND wt.transactionstatus::text = 'PROCESSED'::text AND date(wt.createdon) = date(now()) AND bp.bpcode::text <> 'BPTIM'::text AND bp.name::text = 'Send Money P2P'::text
UNION ALL
 SELECT 'Deposit using M-PESA'::text AS name,
    round(sum(wt.debitamount), 2) AS amount
   FROM businessproduct bp
     LEFT JOIN wallettransactions wt ON bp.id::text = wt.businessproductid::text
  WHERE wt.parentid IS NULL AND wt.chargebackofid IS NULL AND wt.debitamount > 0::numeric AND wt.transactionstatus::text = 'PROCESSED'::text AND date(wt.createdon) = date(now()) AND bp.bpcode::text <> 'BPTIM'::text AND bp.name::text = 'Deposit using M-PESA'::text
UNION ALL
 SELECT 'Merchant payment using paybillnumber'::text AS name,
    round(sum(wt.debitamount), 2) AS amount
   FROM businessproduct bp
     LEFT JOIN wallettransactions wt ON bp.id::text = wt.businessproductid::text
  WHERE wt.parentid IS NULL AND wt.chargebackofid IS NULL AND wt.debitamount > 0::numeric AND wt.transactionstatus::text = 'PROCESSED'::text AND date(wt.createdon) = date(now()) AND bp.bpcode::text <> 'BPTIM'::text AND bp.name::text = 'Merchant payment using paybillnumber'::text
UNION ALL
 SELECT 'Withdraw to M-PESA'::text AS name,
    round(sum(wt.debitamount), 2) AS amount
   FROM businessproduct bp
     LEFT JOIN wallettransactions wt ON bp.id::text = wt.businessproductid::text
  WHERE wt.parentid IS NULL AND wt.chargebackofid IS NULL AND wt.debitamount > 0::numeric AND wt.transactionstatus::text = 'PROCESSED'::text AND date(wt.createdon) = date(now()) AND bp.bpcode::text <> 'BPTIM'::text AND bp.name::text = 'Withdraw to M-PESA'::text
UNION ALL
 SELECT 'Loan Repayment Using Timiza'::text AS name,
    round(sum(wtrans.debitamount), 2) AS amount
   FROM wallettransactions wtrans
     JOIN loan l ON l.id::text = wtrans.sourceid::text
     JOIN walletbalance wb ON wb.id::text = wtrans.walletinstanceid::text
  WHERE wtrans.parentid IS NULL AND wtrans.debitamount > 0::numeric AND wtrans.chargebackofid IS NULL AND wb.producttype::text = 'WALLET'::text AND wtrans.instancetype::text = 'CUSTOMER'::text AND wtrans.externalrefid IS NULL AND date(wtrans.createdon) = date(now()) AND wtrans.transactionstatus::text = 'PROCESSED'::text
UNION ALL
 SELECT 'Loan Repayment Using M-PESA'::text AS name,
    round(sum(wtrans.debitamount), 2) AS amount
   FROM wallettransactions wtrans
     JOIN loan l ON l.id::text = wtrans.sourceid::text
  WHERE wtrans.parentid IS NULL AND wtrans.debitamount > 0::numeric AND wtrans.chargebackofid IS NULL AND wtrans.instancetype::text = 'BUSINESS'::text AND wtrans.externalrefid IS NOT NULL AND date(wtrans.createdon) = date(now()) AND wtrans.transactionstatus::text = 'PROCESSED'::text
UNION ALL
 SELECT 'Insurance Subscription Using Timiza'::text AS name,
    round(sum(wtrans.debitamount), 2) AS amount
   FROM wallettransactions wtrans
     JOIN insurancesubscription i ON i.id::text = wtrans.sourceid::text
     JOIN walletbalance wb ON wb.id::text = wtrans.walletinstanceid::text
  WHERE wtrans.parentid IS NULL AND wtrans.debitamount > 0::numeric AND wtrans.chargebackofid IS NULL AND wb.producttype::text = 'WALLET'::text AND wtrans.instancetype::text = 'CUSTOMER'::text AND wtrans.externalrefid IS NULL AND date(wtrans.createdon) = date(now()) AND wtrans.transactionstatus::text = 'PROCESSED'::text AND wtrans.description::text ~~ 'Insurance Payment%'::text
UNION ALL
 SELECT 'Goal Deposit Using Timiza'::text AS name,
    round(sum(wtrans.debitamount), 2) AS amount
   FROM wallettransactions wtrans
     JOIN rdproductassociation r ON r.id::text = wtrans.sourceid::text
     JOIN walletbalance wb ON wb.id::text = wtrans.walletinstanceid::text
  WHERE wtrans.parentid IS NULL AND wtrans.debitamount > 0::numeric AND wtrans.chargebackofid IS NULL AND wb.producttype::text = 'WALLET'::text AND wtrans.instancetype::text = 'CUSTOMER'::text AND wtrans.externalrefid IS NULL AND date(wtrans.createdon) = date(now()) AND wtrans.transactionstatus::text = 'PROCESSED'::text AND (wtrans.description::text ~~ 'RD_INITIAL_DEPOSIT%'::text OR wtrans.description::text ~~ 'RD_TOPUP%'::text);


-- dashboard.trxsummaryreport source

CREATE OR REPLACE VIEW dashboard.trxsummaryreport
AS SELECT bp.name AS service_name,
        CASE
            WHEN trns.transactionstatus::text = 'PROCESSED'::text THEN 'SUCCESS'::text
            ELSE 'FAIL'::text
        END AS trns_status,
    'Credit'::text AS trns_type,
    count(trns.transactionid) AS no_of_transactions,
    round(sum(trns.creditamount), 2) AS total_transacted_amount
   FROM wallettransactions trns
     LEFT JOIN businessproduct bp ON bp.id::text = trns.businessproductid::text
     LEFT JOIN users u ON u.id::text = trns.fromortouserid::text
     LEFT JOIN mpesafsi fsi ON trns.externalrefid::text = fsi.originatorconversationid::text
  WHERE trns.businessproductid IS NOT NULL AND trns.creditamount > 0::numeric AND bp.bpcode::text = 'DMPESA'::text
  GROUP BY bp.name, (
        CASE
            WHEN trns.transactionstatus::text = 'PROCESSED'::text THEN 'SUCCESS'::text
            ELSE 'FAIL'::text
        END), 'Credit'::text
UNION ALL
 SELECT
        CASE
            WHEN fsi.receiverpartypublicname IS NULL THEN bp.name::text
            WHEN fsi.requesttype::text = 'B2C'::text THEN bp.name::text
            ELSE concat(bp.name, '-', fsi.receiverpartypublicname)
        END AS service_name,
        CASE
            WHEN trns.transactionstatus::text = 'PROCESSED'::text THEN 'SUCCESS'::text
            ELSE 'FAIL'::text
        END AS trns_status,
    'Debit'::text AS trns_type,
    count(trns.transactionid) AS no_of_transactions,
    round(sum(trns.debitamount), 2) AS total_transacted_amount
   FROM wallettransactions trns
     LEFT JOIN businessproduct bp ON bp.id::text = trns.businessproductid::text
     LEFT JOIN users u ON u.id::text = trns.fromortouserid::text
     LEFT JOIN mpesafsi fsi ON trns.externalrefid::text = fsi.originatorconversationid::text
  WHERE trns.businessproductid IS NOT NULL AND trns.chargebackofid IS NULL AND trns.debitamount > 0::numeric AND bp.bpcode::text <> 'DMPESA'::text
  GROUP BY (
        CASE
            WHEN fsi.receiverpartypublicname IS NULL THEN bp.name::text
            WHEN fsi.requesttype::text = 'B2C'::text THEN bp.name::text
            ELSE concat(bp.name, '-', fsi.receiverpartypublicname)
        END), (
        CASE
            WHEN trns.transactionstatus::text = 'PROCESSED'::text THEN 'SUCCESS'::text
            ELSE 'FAIL'::text
        END), 'Debit'::text
UNION ALL
 SELECT 'Customer Registration'::character varying AS service_name,
    'SUCESS'::text AS trns_status,
    'NF'::text AS trns_type,
    count(usr.id) AS no_of_transactions,
    0.00 AS total_transacted_amount
   FROM users usr
     JOIN role rl ON usr.roleid::text = rl.id::text AND rl.roletype::text <> 'OPERATION'::text
UNION ALL
 SELECT 'Loan Taken'::character varying AS service_name,
    'SUCCESS'::text AS trns_status,
    'NF'::text AS trns_type,
    count(loan.id) AS no_of_transactions,
    0.00 AS total_transacted_amount
   FROM loan
UNION ALL
 SELECT lp.name AS service_name,
        CASE
            WHEN wt.transactionstatus::text = 'PROCESSED'::text THEN 'SUCCESS'::text
            ELSE 'FAIL'::text
        END AS trns_status,
    'Debit'::text AS trns_type,
    count(wt.id) AS no_of_transactions,
    round(sum(wt.debitamount), 2) AS total_transacted_amount
   FROM wallettransactions wt
     JOIN loan l ON wt.sourceid::text = l.id::text
     LEFT JOIN loanproduct lp ON l.loanproductid::text = lp.id::text AND wt.chargebackofid IS NULL
  WHERE wt.chargebackofid IS NULL AND wt.creditamount = 0::numeric
  GROUP BY lp.name, (
        CASE
            WHEN wt.transactionstatus::text = 'PROCESSED'::text THEN 'SUCCESS'::text
            ELSE 'FAIL'::text
        END), 'Debit'::text
UNION ALL
 SELECT 'Goal Account Open'::character varying AS service_name,
    'SUCCESS'::text AS trns_status,
    'NF'::text AS trns_type,
    count(rdproductassociation.id) AS no_of_transactions,
    0.00 AS total_transacted_amount
   FROM rdproductassociation
UNION ALL
 SELECT wt.description AS service_name,
        CASE
            WHEN wt.transactionstatus::text = 'PROCESSED'::text THEN 'SUCCESS'::text
            ELSE 'FAIL'::text
        END AS trns_status,
    'Debit'::text AS trns_type,
    count(wt.id) AS no_of_transactions,
    round(sum(wt.debitamount), 2) AS total_transacted_amount
   FROM wallettransactions wt
     JOIN rdproductassociation rdp ON wt.sourceid::text = rdp.id::text
  WHERE wt.chargebackofid IS NULL AND wt.creditamount = 0::numeric
  GROUP BY wt.description, (
        CASE
            WHEN wt.transactionstatus::text = 'PROCESSED'::text THEN 'SUCCESS'::text
            ELSE 'FAIL'::text
        END), 'Debit'::text
UNION ALL
 SELECT 'Insurance Registration'::character varying AS service_name,
    'SUCCESS'::text AS trns_status,
    'NF'::text AS trns_type,
    count(insurancesubscription.id) AS no_of_transactions,
    0.00 AS total_transacted_amount
   FROM insurancesubscription
UNION ALL
 SELECT wt.description AS service_name,
        CASE
            WHEN wt.transactionstatus::text = 'PROCESSED'::text THEN 'SUCCESS'::text
            ELSE 'FAIL'::text
        END AS trns_status,
    'Debit'::text AS trns_type,
    count(wt.id) AS no_of_transactions,
    round(sum(wt.debitamount), 2) AS total_transacted_amount
   FROM wallettransactions wt
     JOIN insurancesubscription ins ON wt.businesstrxid::text = ins.transactionid::text
  WHERE wt.chargebackofid IS NULL AND wt.creditamount = 0::numeric
  GROUP BY wt.description, (
        CASE
            WHEN wt.transactionstatus::text = 'PROCESSED'::text THEN 'SUCCESS'::text
            ELSE 'FAIL'::text
        END), 'Debit'::text;


-- dashboard.u756loanreport source

CREATE OR REPLACE VIEW dashboard.u756loanreport
AS SELECT usr.lastname AS "Surname",
    usr.firstname AS "Forename1",
    usr.middlename AS "Forename2",
        CASE
            WHEN ukyc.title IS NULL THEN ''::character varying
            ELSE ukyc.title
        END AS "Salutation",
    date(now()) AS "BusinessDate",
    date(usr.dob) AS "Date_of_Birth",
    usr.id AS "Client_Number",
    l.accountnumber AS "Mobile_Loan_Account_Number",
    usr.gender,
    'KE'::text AS "Nationality",
    usr.idtype AS "PrimaryID_type",
    usr.idnumber AS "PrimaryID_Num",
    concat('254', usr.username) AS "Mobile_Number",
    'KE'::text AS "Postal_Country",
    0 AS salary_band,
    'Virtual Banking'::text AS "Lender_Branch_Name",
    160 AS "Lender_Branch_Code",
    'IN001'::text AS "Account_prod_type",
    date(l.expecteddisbursementdate) AS "Date_Acct_Opened",
    date(l.expectedfirstrepaymentdate)::text AS "Instalment_due_date",
    round(l.principaldisbursed, 2) AS "Original_Amount",
    round(l.principaldisbursed, 2) AS local_orig_amount,
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::numeric
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN round(l.totalamountwrittenoff, 2)
            ELSE round(l.totalamountoutstanding, 2)
        END AS "Current_balance",
    ( SELECT
                CASE
                    WHEN loan.loanstatus::text = 'CLOSED'::text THEN 0::numeric
                    WHEN loan.loanstatus::text = 'WRITTEN_OFF'::text THEN round(l.totalamountwrittenoff, 2)
                    WHEN date(loan.calucatedclosedate) > date(now()) THEN 0::numeric
                    WHEN loan.totalamountoutstanding IS NULL THEN 0::numeric
                    ELSE round(loan.totalamountoutstanding, 2)
                END AS round
           FROM loan
          WHERE loan.accountnumber::text = l.accountnumber::text) AS "Overdue_balance",
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN ' '::text
            WHEN l.calucatedclosedate < date(now()) THEN date(date(l.calucatedclosedate) + '1 day'::interval)::text
            ELSE ' '::text
        END AS "Overdue_date",
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::double precision
            WHEN date_part('days'::text, l.calucatedclosedate::timestamp with time zone - now()) > 0::double precision THEN 0::double precision
            ELSE date_part('days'::text, l.calucatedclosedate::timestamp with time zone - now()) * '-1'::integer::double precision
        END AS "Days_in_arrears",
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 'Bucket 0'::text
            ELSE concat('Bucket ', round(lb.currentbucketnumber, 0))
        END AS "Bucket",
    ( SELECT
                CASE
                    WHEN loan.loanstatus::text = 'CLOSED'::text THEN 0::numeric
                    WHEN loan.loanstatus::text = 'WRITTEN_OFF'::text THEN round(l.totalamountwrittenoff, 2)
                    WHEN date(loan.calucatedclosedate) > date(now()) THEN 0::numeric
                    WHEN loan.totalamountoutstanding IS NULL THEN 0::numeric
                    ELSE round(loan.totalamountoutstanding, 2)
                END AS round
           FROM loan
          WHERE loan.accountnumber::text = l.accountnumber::text) AS "Instalment_arrears",
    l.loanstatus AS "Account_Status",
        CASE
            WHEN l.loanstatus::text = 'ACTIVE'::text THEN date(l.createdon)
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN date(l.writtenoffdate)
            ELSE date(l.actualclosedate)
        END AS "Account_status_Date",
    ' '::text AS "Reason_For_Closure",
    1 AS "Repayment_period",
    ''::text AS "Deferred_pymt_Date",
    ''::text AS "Deferred_pymt_amt",
    l.replayfrequency AS "Payment_freq",
    date(l.actualdisbursementdate) AS "Disbursement_Date",
    round(l.totalexpectedcostofloan, 2) AS "Instalment_amount",
        CASE
            WHEN l.lastpaidon IS NULL THEN ' '::text
            ELSE date(l.lastpaidon)::text
        END AS "Latest_pymt_date",
    COALESCE(round(l.lastinstallmentamount, 2), 0::numeric) AS "Latest_pymt_Amt",
        CASE
            WHEN l.loanstatus::text = ANY (ARRAY['ACTIVE'::character varying::text, 'WRITTEN_OFF'::character varying::text]) THEN 'ACTIVE'::text
            ELSE 'CLOSED'::text
        END AS "Account_status_desc",
    lp.name AS product_name,
    l.createdon::timestamp(0) without time zone AS createdon,
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::numeric
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN 0::numeric
            ELSE round(l.principaloutstanding, 2)
        END AS "PrincipalOutstanding",
    ( SELECT
                CASE
                    WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::numeric
                    WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN 0::numeric
                    ELSE round(l.calcuatedintrest - l.interestrepaidsofar, 2)
                END AS round
           FROM loanschedule ls
          WHERE ls.loanid::text = l.id::text
         LIMIT 1) AS "Interestoutstanding",
    round(cl.creditlimit, 2) AS "Creditlimit",
    cl.riskcategory AS "RiskCategory",
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::numeric
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN 0::numeric
            ELSE ( SELECT sum(round(l2.penaltypending, 2)) AS sum
               FROM loanschedule l2
              WHERE l2.loanid::text = l.id::text)
        END AS "Penaltyfeeoutstanding",
    ( SELECT sum(round(l2.penaltycomponent, 2)) AS sum
           FROM loanschedule l2
          WHERE l2.loanid::text = l.id::text) AS "RolloverFees"
   FROM users usr
     JOIN loan l ON usr.id::text = l.userid::text
     LEFT JOIN userkycdetails ukyc ON usr.id::text = ukyc.userid::text
     LEFT JOIN loanbucket lb ON l.id::text = lb.loanid::text
     LEFT JOIN loanproduct lp ON l.loanproductid::text = lp.id::text
     JOIN creditlimit cl ON l.userid::text = cl.userid::text;


-- dashboard.u756report source

CREATE OR REPLACE VIEW dashboard.u756report
AS SELECT usr.lastname AS surname,
    usr.firstname AS forename1,
    usr.middlename AS forename2,
        CASE
            WHEN ukyc.title IS NULL THEN ''::character varying
            ELSE ukyc.title
        END AS salutation,
    l.createdon::timestamp(0) without time zone AS businessdate,
    date(usr.dob) AS date_of_birth,
    usr.username AS client_number,
    l.accountnumber AS mobile_loan_account_number,
    usr.gender,
    'KE'::text AS nationality,
    usr.idtype AS primaryid_type,
    usr.idnumber AS primaryid_num,
    concat('254', usr.username) AS mobilenumber,
    'KE'::text AS postal_country,
    0 AS salary_band,
    'Virtual Banking'::text AS lender_branch_name,
    160 AS lender_branch_code,
    'IN001'::text AS account_prod_type,
    usr.createdon::timestamp(0) without time zone AS date_account_opened,
    ls.duedate AS installment_due_date,
    l.principaldisbursed AS originalamount,
    l.principaldisbursed AS local_orig_amount,
    l.totalamountoutstanding AS current_balance,
    l.totalamountoutstanding AS overdue_balance,
    date(ls.duedate) + '30 days'::interval AS overdue_date,
    date_part('days'::text, age(ls.duedate::timestamp with time zone, now())) AS days_in_arrears,
    concat('Bucket ', lb.currentbucketnumber) AS bucket,
    ls.amountdue AS installment_arrears,
    l.loanstatus AS account_status,
    l.createdon AS account_status_date,
    ' '::text AS reason_for_closure,
    1 AS repaymentperiod,
    ''::text AS deferred_pymt_date,
    ''::text AS deferred_pymt_amt,
    'M'::text AS payment_freq,
    l.actualdisbursementdate AS disbursement_date,
    ls.amountdue AS installment_amount,
    l.lastpaidon AS latest_pymt_date,
    l.lastinstallmentamount AS latest_pymt_amt,
    usr.userstatus AS account_status_desc,
    lp.name AS product_name,
    l.createdon::timestamp(0) without time zone AS createdon,
    l.principaloutstanding,
    l.interestoutstanding,
    cl.creditlimit,
    cl.riskcategory,
    l.chargescharged AS penaltyfeeoutstanding,
    ( SELECT sum(l2.penaltycomponent) AS sum
           FROM loanschedule l2
          WHERE l2.loanid::text = l.id::text) AS rolloverfees
   FROM users usr
     JOIN loan l ON usr.id::text = l.userid::text
     LEFT JOIN userkycdetails ukyc ON usr.id::text = ukyc.userid::text
     JOIN loanschedule ls ON l.id::text = ls.loanid::text
     JOIN loanbucket lb ON l.id::text = lb.loanid::text
     JOIN loanproduct lp ON l.loanproductid::text = lp.id::text
     JOIN creditlimit cl ON l.userid::text = cl.userid::text;


-- dashboard.user_info_view source

CREATE OR REPLACE VIEW dashboard.user_info_view
AS SELECT row_number() OVER () AS "Sr. No.",
    u.username AS "User Name",
    r.name AS "Role Name",
    u.firstname AS "First Name",
    u.middlename AS "Middle Name",
    u.lastname AS "Last Name",
    u.mobilenumber AS "mobile No.",
    to_char(u.createdon, 'yyyy-mm-dd HH24:MI:SS'::text) AS "Registration Date",
    u.email AS "Email",
    to_char(u.dob, 'yyyy-mm-dd HH24:MI:SS'::text) AS "Date of Birth",
    u.gender AS "Gender",
    u.address AS "Address",
    u.country AS "Country",
    u.countrycode AS "Country Code",
    to_char(u.passwordexpirydate, 'yyyy-mm-dd HH24:MI:SS'::text) AS "Password Exipry Date",
    u.state AS "State",
    u.city AS "City",
    u.pincode AS "City Pincode",
    u.userstatus AS "Status",
    u.roletype AS "Role Type",
    u.idtype AS "ID Type",
    u.idnumber AS "ID Number"
   FROM users u
     LEFT JOIN role r ON u.roleid::text = r.id::text;


-- dashboard.ussddbchart source

CREATE OR REPLACE VIEW dashboard.ussddbchart
AS SELECT 'ACCOUNTBLOCKED'::text AS errormsg,
    count(u.userstatus) AS count
   FROM users u
     JOIN channel c ON u.registrationchannelid::text = c.id::text
  WHERE u.userstatus::text = 'BLOCKED'::text AND c.key::text = 'USSD'::text AND date(u.createdon) = date(now())
  GROUP BY 'ACCOUNTBLOCKED'::text
UNION ALL
 SELECT 'INSUFFICIENTFUNDS'::text AS errormsg,
    count(u.id) AS count
   FROM ussdrequestlog u
  WHERE u.status::text = 'FAILURE'::text AND (u.errortype::text = 'P2P'::text OR u.errortype::text = 'PAY_BILL_BILLER'::text OR u.errortype::text = 'BUY_AIRTIME'::text OR u.errortype::text = 'BUY_MPESA_GOODS'::text OR u.errortype::text = 'CREATE_GOAL_MPESA'::text OR u.errortype::text = 'CREATE_GOAL_WALLET'::text OR u.errortype::text = 'CRT_ATM_VCH'::text OR u.errortype::text = 'DEP_GOAL_MPESA'::text OR u.errortype::text = 'DEP_GOAL_WALLET'::text OR u.errortype::text = 'LOAN_REPAY_MPESA'::text OR u.errortype::text = 'LOAN_REPAY_WALLET'::text OR u.errortype::text = 'MPESA_TO_WALLT'::text OR u.errortype::text = 'PAY_MPESA_BILL'::text OR u.errortype::text = 'WALLET_TO_MPESA'::text OR u.errortype::text = 'SUBS_PAY_INC_MPESA'::text OR u.errortype::text = 'SUBS_PAY_INC_WALLET'::text) AND date(u.createdon) = date(now())
  GROUP BY 'INSUFFICIENTFUNDS'::text
UNION ALL
 SELECT 'INVALIDACCOUNT'::text AS errormsg,
    count(u.id) AS count
   FROM ussdrequestlog u
  WHERE u.status::text = 'FAILURE'::text AND u.errortype::text = 'INVALID_ACC'::text AND date(u.createdon) = date(now())
  GROUP BY 'INVALIDACCOUNT'::text
UNION ALL
 SELECT 'FAILEDKYC'::text AS errormsg,
    count(u.id) AS count
   FROM users u
     JOIN channel c ON u.registrationchannelid::text = c.id::text
  WHERE u.kycstatus::text = 'KYC_FAILED'::text AND c.key::text = 'USSD'::text AND date(u.createdon) = date(now())
  GROUP BY 'FAILEDKYC'::text
UNION ALL
 SELECT 'NOSECURITYQUESTION'::text AS errormsg,
    count(u.id) AS count
   FROM users u
     JOIN channel c ON u.registrationchannelid::text = c.id::text
  WHERE u.securityquestionjson IS NULL AND c.key::text = 'USSD'::text AND date(u.createdon) = date(now())
  GROUP BY 'NOSECURITYQUESTION'::text
UNION ALL
 SELECT 'PENDINGKYC'::text AS errormsg,
    count(u.id) AS count
   FROM users u
     JOIN channel c ON u.registrationchannelid::text = c.id::text
  WHERE u.kycstatus::text = 'NON_KYC'::text AND c.key::text = 'USSD'::text AND date(u.createdon) = date(now())
  GROUP BY 'PENDINGKYC'::text
UNION ALL
 SELECT 'CHANGEPIN'::text AS errormsg,
    count(u.id) AS count
   FROM ussdrequestlog u
  WHERE u.status::text = 'FAILURE'::text AND u.errortype::text = 'CHANGE_PIN'::text AND date(u.createdon) = date(now())
  GROUP BY 'CHANGEPIN'::text;

