-- DROP PROCEDURE "dataReports".proc_rpt_activeusrs(varchar);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_activeusrs(requestid character varying)
 LANGUAGE plpgsql
AS $procedure$
BEGIN
truncate "dataReports".rpt_activeusrs;
insert into "dataReports".rpt_activeusrs
SELECT   requestid, usr.id,
    wb.walletno AS bankaccountid,
    usr.createdon::timestamp(0) without time zone AS registrationdate,
    usr.firstname,
    usr.middlename AS othername,
    usr.lastname,
    usr.mobilenumber,
    max(wt.txtime::timestamp(0) without time zone) AS transactiondateandtime,
    count(wt.id) AS totaltransactions
       FROM public.users usr
     JOIN public.wallettransactions wt ON usr.id = wt.fromortouserid
     JOIN public.walletbalance wb ON usr.id = wb.ownerid
  WHERE wb.producttype = 'WALLET'
  GROUP BY usr.id, wb.walletno;
 end;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_atmdetailsreport(varchar);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_atmdetailsreport(requestid character varying)
 LANGUAGE plpgsql
AS $procedure$
BEGIN
truncate "dataReports".rpt_atmdetailsreport;
insert into "dataReports".rpt_atmdetailsreport
 SELECT  requestid,uvc.plainvouchercode AS "Voucher Code",
    concat('254', usr.username) AS "Mobile Number",
    concat(w.businesstrxid, ' / ', w.executionid) AS "Transaction ID/Batch ID",
    ( SELECT w2.walletno
           FROM walletbalance w2
          WHERE w2.ownerid::text = uvc.fromuserid::text AND w2.producttype::text = 'WALLET'::text AND w2.instancetype::text = 'CUSTOMER'::text
         LIMIT 1) AS "AccountID",
    uvc.createdon::timestamp(0) without time zone AS voucherpurchasedate,
    round(uvc.orignaltrxamount, 2) AS "Voucher Amount",
        CASE
            WHEN uvc.benificiarymobile IS NULL THEN ' '::text
            ELSE concat('254', uvc.benificiarymobile)
        END AS "Beneficiary Mobile Number",
    uvc.validtill::timestamp(0) without time zone AS voucherexpirydate,
    uvc.vouchercodestatus AS "Voucher Status",
        CASE
            WHEN uvc.vouchercodestatus::text = 'CLAIMED'::text THEN uvc.modifiedon::timestamp(0) without time zone::text
            ELSE ' '::text
        END AS "Voucher Redeemed Date"
   FROM uservouchercodes uvc
     JOIN wallettransactions w ON uvc.txid::text = w.businesstrxid::text
     LEFT JOIN users usr ON uvc.fromuserid::text ~~ usr.id::text
  WHERE w.debitamount > 0::numeric;
      end;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_atmreportexpired(varchar);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_atmreportexpired(requestid character varying)
 LANGUAGE plpgsql
AS $procedure$
BEGIN
truncate "dataReports".rpt_atmreportexpired;
insert into "dataReports".rpt_atmreportexpired
 SELECT  requestid,uvc.plainvouchercode AS "Voucher Code",
    concat('254', usr.username) AS "Mobile Number",
    ( SELECT w2.walletno
           FROM walletbalance w2
          WHERE w2.ownerid::text = uvc.fromuserid::text AND w2.producttype::text = 'WALLET'::text AND w2.instancetype::text = 'CUSTOMER'::text
         LIMIT 1) AS "AccountID",
    uvc.createdon::timestamp(0) without time zone AS voucherpurchasedate,
    concat(w.businesstrxid, ' / ', w.executionid) AS "Transaction ID/Batch ID",
    round(uvc.orignaltrxamount, 2) AS "Voucher Amount",
        CASE
            WHEN uvc.benificiarymobile IS NULL THEN ' '::text
            ELSE concat('254', uvc.benificiarymobile)
        END AS "Beneficiary Mobile Number",
    uvc.validtill::timestamp(0) without time zone AS voucherexpirydate
    FROM uservouchercodes uvc
     JOIN wallettransactions w ON uvc.txid::text = w.businesstrxid::text
     LEFT JOIN users usr ON uvc.fromuserid::text ~~ usr.id::text
  WHERE uvc.vouchercodestatus::text = 'EXPIRED'::text AND w.debitamount > 0::numeric;
      end;
$procedure$
;

