-- DROP PROCEDURE "dataReports".proc_rpt_c2bexceptionreport(varchar, timestamp, timestamp);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_c2bexceptionreport(requesterid character varying, start_date timestamp without time zone DEFAULT '2021-09-15 00:00:00'::timestamp without time zone, end_date timestamp without time zone DEFAULT '2021-09-15 23:59:59'::timestamp without time zone)
 LANGUAGE plpgsql
AS $procedure$
BEGIN
truncate "dataReports".rpt_c2bexceptionreport;
insert into "dataReports".rpt_c2bexceptionreport
SELECT requesterid, 
date(mb.requesttime) AS "date",
mb.requesttime::timestamp(0) without time zone::time without time zone AS "time",
mb.merchantrequestid AS "MerchantRequestID",
mb.mpesaReceiptNumber AS "MpesaRef",
'N/A'::text AS "trxbatchid",
round(mb.amount,2) AS "trxamount",
mb.sourceType AS "trxtype",
'N/A'::text AS "trxnarration",
'N/A'::text AS "glid",
mb.username AS "mobile",
mb.errordescription AS "description",
mb.requestId AS "c2bRequestId" from mpesac2bpayment mb
where paymentStatus='ERROR';	
end;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_c2breconreport(varchar);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_c2breconreport(requesterid character varying)
 LANGUAGE plpgsql
AS $procedure$
Begin
truncate "dataReports".rpt_c2breconreport;
insert into "dataReports".rpt_c2breconreport
select * from (select  requesterid,date(w.txtime) AS date,
    w.txtime::timestamp(0) without time zone::time without time zone AS "time",
    c2b.mpesareceiptnumber AS mpesaref,
    concat(w.businesstrxid, ' / ', w.executionid) AS trxbatchid,
    round(w.creditamount + w.debitamount, 2) AS trxamount,
        CASE
            WHEN w.creditamount > 0::numeric THEN 'Credit'::text
            ELSE 'Debit'::text
        END AS transactiontype,
        CASE
            WHEN w.description IS NULL OR w.description::text = ''::text THEN bp.name
            ELSE w.description
        END AS transactionnarration,
    wt.glaccountnumber AS glid,
    array_to_json(ARRAY[to_json(c2b.paymentrequest::json -> 'phoneNumber'::text)]) ->> 0 AS mobile
FROM mpesac2bpayment c2b
     JOIN wallettransactions w ON c2b.externalrefid::text = w.externalrefid::text
     LEFT JOIN wallettype wt ON w.wallettypeid::text = wt.id::text
     LEFT JOIN businessproduct bp ON w.businessproductid::text = bp.id::text
  WHERE (c2b.sourceType <> 'LOAN' AND (c2b.callbackresultcode::text = '0.0'::text or c2b.callbackresultcode::text = '0'::text or c2b.confirmed = true or c2b.queryStatusResultCode::text = '0'::text or c2b.queryStatusResultCode::text = '0.0'::text)) OR (c2b.sourceType = 'LOAN' AND c2b.paymentStatus='PROCESSED')
  UNION ALL
  select  requesterid,date(w.txtime) AS date,
    w.txtime::timestamp(0) without time zone::time without time zone AS "time",
    fsic.transid AS mpesaref,
    concat(w.businesstrxid, ' / ', w.executionid) AS trxbatchid,
    round(w.creditamount + w.debitamount, 2) AS trxamount,
        CASE
            WHEN w.creditamount > 0::numeric THEN 'Credit'::text
            ELSE 'Debit'::text
        END AS transactiontype,
        CASE
            WHEN w.description IS NULL OR w.description::text = ''::text THEN bp.name
            ELSE w.description
        END AS transactionnarration,
    wt.glaccountnumber AS glid,
    fsic.billrefnumber AS mobile
FROM fsipaymentconfirmation fsic
     JOIN wallettransactions w ON fsic.transid::text = w.externalrefid::text
     LEFT JOIN wallettype wt ON w.wallettypeid::text = wt.id::text
     LEFT JOIN businessproduct bp ON w.businessproductid::text = bp.id::text
  WHERE fsic.responsecode='200' and fsic.paymenttype='C2B'
UNION ALL
select  requesterid,date(w.createdon) AS date,
    w.txtime::timestamp(0) without time zone::time without time zone AS "time",
    'N/A'::text AS mpesaref,
    concat(w.businesstrxid, ' / ', w.executionid) AS trxbatchid,
    round(w.creditamount + w.debitamount, 2) AS trxamount,
        CASE
            WHEN w.creditamount > 0::numeric THEN 'Credit'::text
            ELSE 'Debit'::text
        END AS transactiontype,
        CASE
            WHEN w.description IS NULL OR w.description::text = ''::text THEN bp.name
            ELSE w.description
        END AS transactionnarration,
    wt.glaccountnumber AS glid,
CASE
            WHEN w.instanceType ='BUSINESS' THEN ou.username
ELSE u.username
    END AS mobile
FROM wallettransactions w
JOIN businessproduct bp ON w.businessproductid::text = bp.id::text and bp.bpcode in('BLDMCB')
     LEFT JOIN wallettype wt ON w.wallettypeid::text = wt.id::text
LEFT JOIN walletbalance wb ON w.walletinstanceid =  wb.id
LEFT JOIN walletbalance owb ON w.otherwalletinstanceid =  owb.id
LEFT JOIN users u ON wb.ownerid=u.id
LEFT JOIN users ou ON owb.ownerid = ou.id) as mpesac2breport order by mpesac2breport.date desc, mpesac2breport.time DESC;  
  End;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_collectionstkpushreport(varchar, date);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_collectionstkpushreport(requestid character varying, run_date date DEFAULT (now() - '1 day'::interval))
 LANGUAGE plpgsql
AS $procedure$
Begin
insert into "dataReports".rpt_collectionstkpushreport
	SELECT  requestid,
	date(m.requesttime) AS dateofinitation,
	    m.requesttime::timestamp(0) without time zone::time without time zone AS "time",
	    m.referenceNumber AS loanaccountnumber,
	    m.username AS mobilenumber,
	    usr.username as agentId,
	    m.mpesareceiptnumber AS mpesareferenceid,
	    m.amount AS amount,
	    CASE
		    WHEN m.paymentstatus::text = 'NEW'::text THEN 'Pending'::text
		    WHEN m.paymentstatus::text = 'PENDING'::text THEN 'Pending'::text
		    WHEN m.paymentstatus::text = 'PROCESSED'::text THEN 'Completed'::text
		    WHEN m.paymentstatus::text = 'IN_PROGRESS'::text THEN 'Pending'::text
		    WHEN m.paymentstatus::text = 'FAILED'::text THEN 'Failed'::text
		    WHEN m.paymentstatus::text = 'ERROR'::text THEN 'Failed'::text
		    ELSE NULL::text
		END AS paymentstatus
	FROM MpesaC2BPayment m 
	join agentstkrequest a on m.externalrefid =a.mpesarefid
	LEFT JOIN users usr ON a.createdby::text = usr.id::text
	and Date(m.requesttime)=date(run_date)
	ORDER BY m.requesttime desc;
	End;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_crbreport(varchar, date);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_crbreport(requestid character varying, run_date date DEFAULT (now() - '1 day'::interval))
 LANGUAGE plpgsql
AS $procedure$
begin
	truncate "dataReports".rpt_crbreport;
	insert into "dataReports".rpt_crbreport
	SELECT 
		requestid,to_char(run_date::date::timestamp with time zone, 'yyyymmdd'::text) as "Business date",usr.lastname AS surname,
    	usr.firstname AS forename1,
    	usr.middlename AS forename2,
    	''::text AS forename3,
    	''::text AS tradingas,
    	to_char(usr.dob::date::timestamp with time zone, 'yyyymmdd'::text) AS date_of_birth,
    	usr.username AS client_number,
    	l.accountnumber,
        CASE
            WHEN usr.gender::text = 'MALE'::text THEN 'M'::character varying
            WHEN usr.gender::text = 'FEMALE'::text THEN 'F'::character varying
            ELSE usr.gender
        END AS gender,
    	'KE'::text AS nationality,
        CASE
            WHEN usr.idtype::text = 'NATIONAL_ID'::text THEN '001'::character varying
            WHEN usr.idtype::text = 'PASSPORT'::text THEN '002'::character varying
            WHEN usr.idtype::text = 'ALIEN_REGISTRATION'::text THEN '003'::character varying
            WHEN usr.idtype::text = 'SERVICE_ID'::text THEN '004'::character varying
            ELSE usr.idtype
        END AS primaryid_type,
		usr.idnumber AS primaryid_num,
		concat('254', usr.username) AS mobilenumber,
		'I'::text AS accountproducttype,
		to_char(l.expectedfirstrepaymentdate::date::timestamp with time zone, 'yyyymmdd'::text) AS installment_due_date,
		round(l.principaldisbursed, 2) * 100::numeric AS originalamount,
		'KES'::text AS currencyoffacility,
    	CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN round(l.totalamountoutstanding, 2)*100
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN round(l.totalamountwrittenoff, 2) * 100
            ELSE round(l.totalamountoutstanding, 2)*100
        end as current_balance_inkes,
     	CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN round(l.totalamountoutstanding, 2)*100
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN round(l.totalamountwrittenoff, 2) * 100
            ELSE round(l.totalamountoutstanding, 2)*100
        END AS current_balance,
		CASE
			WHEN l.loanstatus::text = 'CLOSED'::text THEN round(l.totalamountoutstanding, 2)*100
			WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN round(l.totalamountwrittenoff, 2) * 100
			WHEN date(l.calucatedclosedate) >= date(run_date) THEN 0::numeric
			WHEN l.totalamountoutstanding IS NULL THEN 0::numeric
			ELSE round(l.totalamountoutstanding, 2) * 100
		END AS overdue_balance,
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN ' '::text
            WHEN l.calucatedclosedate < date(run_date) THEN to_char((l.calucatedclosedate::date + 1)::timestamp with time zone, 'yyyymmdd'::text)
            ELSE ' '::text
        END AS overdue_date,
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::double precision
            WHEN  date(l.calucatedclosedate) >= date(run_date) THEN 0::numeric
            ELSE date_part('days'::text, l.expectedfirstrepaymentdate::timestamp with time zone - run_date) * '-1'::integer::double precision
        END AS days_in_arrears,
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::double precision
            WHEN  date(l.calucatedclosedate) >= date(run_date) THEN 0::numeric
            ELSE 1::double precision
        END AS noofinstallmentinarrears,
		CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 'A'::text
            WHEN date_part('days'::text, run_date - l.expectedfirstrepaymentdate::timestamp with time zone) < 31::double precision THEN 'A'::text
            WHEN date_part('days'::text, run_date - l.expectedfirstrepaymentdate::timestamp with time zone) >= '31'::double precision AND date_part('days'::text, run_date - l.expectedfirstrepaymentdate::timestamp with time zone) <= '90'::double precision THEN 'B'::text
            WHEN date_part('days'::text, run_date - l.expectedfirstrepaymentdate::timestamp with time zone) >= '91'::double precision AND date_part('days'::text, run_date - l.expectedfirstrepaymentdate::timestamp with time zone) <= '180'::double precision THEN 'C'::text
            WHEN date_part('days'::text, run_date - l.expectedfirstrepaymentdate::timestamp with time zone) >= '181'::double precision AND date_part('days'::text, run_date - l.expectedfirstrepaymentdate::timestamp with time zone) <= '360'::double precision THEN 'D'::text
            WHEN date_part('days'::text, run_date - l.expectedfirstrepaymentdate::timestamp with time zone) > 360::double precision THEN 'E'::text
            ELSE ''::text
        END AS "Prudential Risk Classification",
        CASE
            WHEN l.loanstatus::text = 'ACTIVE'::text THEN 'F'::text
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 'A'::text
            ELSE 'C'::text
        END AS accountstatus,
        CASE
            WHEN l.loanstatus::text = 'ACTIVE'::text THEN to_char(l.createdon::date::timestamp with time zone, 'yyyymmdd'::text)
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN to_char(l.writtenoffdate::date::timestamp with time zone, 'yyyymmdd'::text)
            ELSE to_char(l.actualclosedate::date::timestamp with time zone, 'yyyymmdd'::text)
        END AS accountstatusdate,
    	1 AS repaymentperiod,
    	to_char(l.actualdisbursementdate::date::timestamp with time zone, 'yyyymmdd'::text) AS disbursement_date,
    	round(l.totalexpectedcostofloan, 2) * 100::numeric AS installment_amount,
        CASE
            WHEN l.lastpaidon IS NULL THEN ' '::text
            ELSE to_char(l.lastpaidon::date::timestamp with time zone, 'yyyymmdd'::text)
        END AS latest_pymt_date,
        CASE
            WHEN l.lastinstallmentamount IS NULL THEN 0::numeric
            ELSE round(l.lastinstallmentamount, 2) * 100::numeric
        END AS latest_pymt_amt
	FROM users usr
		JOIN loan l ON usr.id::text = l.userid::text 
			and (l.loanstatus in ('ACTIVE','WRITTEN_OFF') 
				or (l.loanstatus='CLOSED' and Date(l.actualclosedate)=date(run_date)))  and l.loanproductid='e0cff44e-bf30-43cf-91ab-82b3f2446980'
		LEFT JOIN userkycdetails ukyc ON usr.id::text = ukyc.userid::text
		LEFT JOIN loanbucket lb ON l.id::text = lb.loanid::text
		LEFT JOIN loanproduct lp ON l.loanproductid::text = lp.id::text
		JOIN walletbalance wt ON usr.id::text = wt.ownerid::text
	WHERE wt.producttype::text = 'WALLET'::text
union
SELECT 
		requestid,to_char(run_date::date::timestamp with time zone, 'yyyymmdd'::text) as "Business date",usr.lastname AS surname,
    	usr.firstname AS forename1,
    	usr.middlename AS forename2,
    	''::text AS forename3,
    	''::text AS tradingas,
    	to_char(usr.dob::date::timestamp with time zone, 'yyyymmdd'::text) AS date_of_birth,
    	usr.username AS client_number,
    	l.accountnumber,
        CASE
            WHEN usr.gender::text = 'MALE'::text THEN 'M'::character varying
            WHEN usr.gender::text = 'FEMALE'::text THEN 'F'::character varying
            ELSE usr.gender
        END AS gender,
    	'KE'::text AS nationality,
        CASE
            WHEN usr.idtype::text = 'NATIONAL_ID'::text THEN '001'::character varying
            WHEN usr.idtype::text = 'PASSPORT'::text THEN '002'::character varying
            WHEN usr.idtype::text = 'ALIEN_REGISTRATION'::text THEN '003'::character varying
            WHEN usr.idtype::text = 'SERVICE_ID'::text THEN '004'::character varying
            ELSE usr.idtype
        END AS primaryid_type,
		usr.idnumber AS primaryid_num,
		concat('254', usr.username) AS mobilenumber,
		'I'::text AS accountproducttype,
		CASE
			WHEN l.loanstatus::text = 'CLOSED'::text THEN to_char((select l2.duedate	FROM loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.repaymentduestatus not in ('EARLY_PAID') 
					order by paidon desc limit 1)::timestamp with time zone, 'yyyymmdd'::text)
			ELSE to_char((select l2.duedate	FROM loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') 
					order by installmentno limit 1)::timestamp with time zone, 'yyyymmdd'::text)
			END	AS installment_due_date,--CHANGE THIS BASED ON OLDEST DUE DATE
		round(l.principaldisbursed, 2) * 100::numeric AS originalamount,
		'KES'::text AS currencyoffacility,
    	CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN round(l.totalamountoutstanding, 2)*100
            WHEN l.loanstatus::text = 'CHARGE_OFF'::text THEN round(lcd.principalchargedoffpending+lcd.interestchargedoffpending+lcd.penaltychargedoffpending+lcd.chargeoffinterestpending, 2)*100 
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN round(l.totalamountwrittenoff, 2) * 100
            ELSE (select round(sum(l2.interestpending+l2.principalpending+l2.penaltypending), 2) FROM loanschedule l2 
            WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID'))*100
        end as current_balance_inkes,
     	CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN round(l.totalamountoutstanding, 2)*100
            WHEN l.loanstatus::text = 'CHARGE_OFF'::text THEN round(lcd.principalchargedoffpending+lcd.interestchargedoffpending+lcd.penaltychargedoffpending+lcd.chargeoffinterestpending, 2)*100
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN round(l.totalamountwrittenoff, 2) * 100
            ELSE (select round(sum(l2.interestpending+l2.principalpending+l2.penaltypending), 2) FROM loanschedule l2 
            WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID'))*100
        END AS current_balance,
    	CASE
			WHEN l.loanstatus::text = 'CLOSED'::text THEN round(l.totalamountoutstanding, 2)*100
			WHEN l.loanstatus::text = 'CHARGE_OFF'::text THEN round(lcd.principalchargedoffpending+lcd.interestchargedoffpending+lcd.penaltychargedoffpending+lcd.chargeoffinterestpending, 2)*100
			WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN round(l.totalamountwrittenoff, 2) * 100
			WHEN l.totalamountoutstanding IS NULL THEN 0::numeric
			ELSE  COALESCE((select round(sum(l2.interestpending+l2.principalpending+l2.penaltypending), 2) FROM loanschedule l2 
            WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') and l2.duedate < run_date)*100,0)
		END AS overdue_balance, -- Should be ZERO not blank
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN ' '::text
            WHEN l.calucatedclosedate < run_date - '1 day'::interval THEN to_char(((select l2.duedate	FROM loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') order by installmentno limit 1 ) :: DATE + 1 ),'yyyymmdd')
			WHEN l.calucatedclosedate > run_date - '1 day'::interval and ((select l2.duedate	FROM loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') order by installmentno limit 1 ) :: DATE + 1 ) < run_date -  '1 day'::interval then to_char(((select l2.duedate	FROM loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') order by installmentno limit 1 ) :: DATE + 1 ),'yyyymmdd')       
            ELSE ' '::text
        END AS overdue_date, -- CHANGE BASED ON DUE,DATE, If Overdue, Oldest Due Date, If updcoming due: should be empty
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::double precision
            WHEN date_part('days'::text, 
			(select l2.duedate	FROM loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') 
				order by installmentno limit 1)::timestamp with time zone - run_date - '1 day'::interval) >= 0::double precision THEN 0::double precision
            ELSE date_part('days'::text, 
            (select l2.duedate	FROM loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') 
				order by installmentno limit 1)::timestamp with time zone - run_date - '1 day'::interval) * '-1'::integer::double precision
        END AS days_in_arrears,
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::double precision
			WHEN l.loanstatus::text = 'CHARGE_OFF'::text THEN (select count(*) from loanschedule l2 where installmentstatus not in ('FULLY_PAID') and l2.loanid=l.id)
			WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN (select count(*) from loanschedule l2 where installmentstatus not in ('FULLY_PAID') and l2.loanid=l.id)
            ELSE (select count(*) from loanschedule l2 where installmentstatus not in ('FULLY_PAID') and l2.loanid=l.id and duedate < run_date)
        END AS noofinstallmentinarrears,
		CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 'A'::text
            WHEN date_part('days'::text, run_date - (select l2.duedate	FROM loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') 
				order by installmentno limit 1)::timestamp with time zone) < 31::double precision THEN 'A'::text
            WHEN date_part('days'::text, run_date - (select l2.duedate	FROM loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') 
				order by installmentno limit 1)::timestamp with time zone) >= '31'::double precision AND date_part('days'::text, run_date - (select l2.duedate	FROM loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') 
				order by installmentno limit 1)::timestamp with time zone) <= '90'::double precision THEN 'B'::text
            WHEN date_part('days'::text, run_date - (select l2.duedate	FROM loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') 
				order by installmentno limit 1)::timestamp with time zone) >= '91'::double precision AND date_part('days'::text, run_date - (select l2.duedate	FROM loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') 
				order by installmentno limit 1)::timestamp with time zone) <= '180'::double precision THEN 'C'::text
            WHEN date_part('days'::text, run_date - (select l2.duedate	FROM loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') 
				order by installmentno limit 1)::timestamp with time zone) >= '181'::double precision AND date_part('days'::text, run_date - (select l2.duedate	FROM loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') 
				order by installmentno limit 1)::timestamp with time zone) <= '360'::double precision THEN 'D'::text
            WHEN date_part('days'::text, run_date - (select l2.duedate	FROM loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') 
				order by installmentno limit 1)::timestamp with time zone) > 360::double precision THEN 'E'::text
            ELSE ''::text
        END AS "Prudential Risk Classification",
        CASE
            WHEN l.loanstatus::text = 'ACTIVE'::text THEN 'F'::text
            WHEN l.loanstatus::text = 'CHARGE_OFF'::text THEN 'F'::text
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 'A'::text
            ELSE 'C'::text
        END AS accountstatus,
        CASE
            WHEN l.loanstatus::text = 'ACTIVE'::text THEN to_char(l.createdon::date::timestamp with time zone, 'yyyymmdd'::text)
            WHEN l.loanstatus::text = 'CHARGE_OFF'::text THEN to_char(l.chargeoffdate::date::timestamp with time zone, 'yyyymmdd'::text)
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN to_char(l.writtenoffdate::date::timestamp with time zone, 'yyyymmdd'::text)
            ELSE to_char(l.actualclosedate::date::timestamp with time zone, 'yyyymmdd'::text)
        END AS accountstatusdate,
    	l.loanperiod AS repaymentperiod,
    	to_char(l.actualdisbursementdate::date::timestamp with time zone, 'yyyymmdd'::text) AS disbursement_date,
    	round(l.installmentamount, 2) * 100::numeric AS installment_amount,
        CASE
            WHEN l.lastpaidon IS NULL THEN ' '::text
            ELSE to_char(l.lastpaidon::date::timestamp with time zone, 'yyyymmdd'::text)
        END AS latest_pymt_date,
        CASE
            WHEN l.lastinstallmentamount IS NULL THEN 0::numeric
            ELSE round(l.lastinstallmentamount, 2) * 100::numeric
        END AS latest_pymt_amt
	FROM users usr
		JOIN loan l ON usr.id= l.userid	and 
		(l.loanstatus in ('ACTIVE','WRITTEN_OFF','CHARGE_OFF') 
				or (l.loanstatus='CLOSED' and Date(l.actualclosedate)=date(run_date))) and l.loanproductid='68e8db46-c420-4e90-8ef0-2a48c50f9e65'
		LEFT JOIN userkycdetails ukyc ON usr.id::text = ukyc.userid::text
		LEFT JOIN loanbucket lb ON l.id::text = lb.loanid::text
		LEFT JOIN loanproduct lp ON l.loanproductid::text = lp.id::text
		left join loanchargeoffdata lcd on lcd.loanid = l.id
		JOIN walletbalance wt ON usr.id::text = wt.ownerid::text
	WHERE wt.producttype::text = 'WALLET'::text;
	end;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_customerdetailsreport(varchar);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_customerdetailsreport(reportrequestid character varying)
 LANGUAGE plpgsql
AS $procedure$
begin
truncate "dataReports".rpt_customerdetailsreport;
insert into "dataReports".rpt_customerdetailsreport
select reportrequestid,usr.id AS customernumber,
usr.createdon::timestamp(0) without time zone AS dateopened,
        CASE
            WHEN kyc.title IS NULL THEN ' '::character varying
            ELSE kyc.title
        END AS salutation,
    usr.lastname AS surname,
    usr.firstname,
    usr.middlename AS othername,
    concat(usr.firstname, ' ', usr.middlename, ' ', usr.lastname) AS fullname,
    usr.idnumber AS nationalidorpassportno,
    date(usr.dob) AS dateofbirth,
    usr.gender,
    'KE'::text AS nationality,
    concat('254', usr.username) AS mobilenumber,
    usr.email AS emailaddress,
    usr.address AS address1,
    ' '::text AS address2,
    ' '::text AS address3,
    usr.pincode AS postalcode,
    usr.city AS citytown,
        CASE
            WHEN kyc.createdon IS NULL THEN ' '::text
            ELSE kyc.createdon::timestamp(0) without time zone::text
        END AS createdon,
    ' '::text AS maritalstatus,
        CASE
            WHEN kyc.employmenttype::text ~~ 'Unemployed'::text THEN 'Unemployed'::character varying
            WHEN kyc.employername IS NULL THEN ' '::character varying
            ELSE kyc.employername
        END AS employer,
    usr.idtype AS documenttype,
        CASE
            WHEN cl.creditlimit IS NULL THEN ' '::text
            ELSE round(cl.creditlimit, 2)::text
        END AS creditlimit,
        CASE
            WHEN cl.riskcategory IS NULL THEN ' '::character varying
            ELSE cl.riskcategory
        END AS riskcategory,
    usr.kycstatus
 FROM users usr
     LEFT JOIN userkycdetails kyc ON usr.id::text = kyc.userid::text
     LEFT JOIN creditlimit cl ON usr.id::text = cl.userid::text
     JOIN role rl ON usr.roleid::text = rl.id::text AND rl.roletype::text = 'CUSTOMER'::text;
     End;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_fintrxreport(varchar, date);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_fintrxreport(reportrequestid character varying, run_date date DEFAULT ((now())::date - 1))
 LANGUAGE plpgsql
AS $procedure$
begin
	truncate "dataReports".rpt_fintrxreport;
	insert into "dataReports".rpt_fintrxreport

(With selectedtransactions as
(select * from wallettransactions where date(createdon) = run_date and parentid IS NULL),
selectedchildtransactions as
(select executionid,walletinstanceid, CASE
                    WHEN round(sum(debitamount), 2) IS NULL THEN 0::numeric
                    ELSE round(sum(debitamount), 2)
                END as fee from wallettransactions where date(createdon) = run_date and parentid is not null group by executionid,walletinstanceid)
	SELECT  reportrequestid, wtrans.createdon::timestamp(0) without time zone AS date,
    bp.name AS transactiontype,
    usr.username AS bankid,
        CASE
            WHEN wtrans.description IS NULL OR wtrans.description::text = ''::text THEN bp.name
            ELSE wtrans.description
        END AS paymentdetails,
    wtrans.businesstrxid AS trxreference,
    round(wtrans.creditamount, 2) AS amount,
    COALESCE(scwt.fee,0) AS transactionfee,
        CASE
            WHEN wtrans.transactionstatus::text = 'PROCESSED'::text THEN 'Success'::text
            ELSE 'Failure'::text
        END AS status,
    'CREDIT'::text AS trxtype,
    usr.username AS customerid,
    ''::character varying AS merchantid,
        CASE
            WHEN wtrans.channelid::text = 'SYSTEM'::text THEN 'SYSTEM'::character varying
            ELSE ch.name
        END AS trxsource,
    usr.firstname,
    usr.lastname,
    concat('254', usr.username) AS mobilenumber,
    wtrans.businesstrxid AS uniqueid,
    ( SELECT wallettype.glaccountnumber
           FROM wallettype
          WHERE wallettype.id::text = ((( SELECT walletbalance.wallettypeid
                   FROM walletbalance
                  WHERE walletbalance.id::text = wtrans.otherwalletinstanceid::text))::text)) AS sourceaccount,
    wb.walletno AS destinationaccount
    FROM selectedtransactions wtrans
     LEFT JOIN businessproduct bp ON wtrans.businessproductid::text = bp.id::text
     LEFT JOIN selectedchildtransactions scwt ON scwt.executionid::text = wtrans.executionid::text AND scwt.walletinstanceid::text = wtrans.walletinstanceid::text
     LEFT JOIN users usr ON wtrans.fromortouserid::text = usr.id::text
     LEFT JOIN walletbalance wb ON usr.id::text = wb.ownerid::text
     LEFT JOIN channel ch ON wtrans.channelid::text = ch.id::text
  WHERE wtrans.parentid IS NULL AND bp.bpcode::text = 'DMPESA'::text AND wtrans.creditamount > 0::numeric 
  AND wb.producttype::text = 'WALLET'::text
UNION ALL
 SELECT reportrequestid, wtrans.createdon::timestamp(0) without time zone AS date,
        CASE
            WHEN fsi.receiverpartypublicname IS NULL THEN bp.name::text
            WHEN fsi.requesttype::text = 'B2C'::text THEN bp.name::text
            ELSE concat(bp.name)
        END AS transactiontype,
    usr.username AS bankid,
        CASE
            WHEN wtrans.description IS NULL OR wtrans.description::text = ''::text THEN bp.name
            ELSE wtrans.description
        END AS paymentdetails,
    wtrans.businesstrxid AS trxreference,
    round(wtrans.debitamount, 2) AS amount,
   COALESCE(scwt.fee,0) AS transactionfee,
        CASE
            WHEN wtrans.transactionstatus::text = 'PROCESSED'::text THEN 'Success'::text
            ELSE 'Failure'::text
        END AS status,
    'DEBIT'::text AS trxtype,
    usr.username AS customerid,
        CASE
            WHEN fsi.requesttype::text = 'B2C'::text THEN ''::character varying
            WHEN fsi.receiverpartypublicname IS NULL THEN ''::character varying
            ELSE fsi.receiverpartypublicname
        END AS merchantid,
        CASE
            WHEN wtrans.channelid::text = 'SYSTEM'::text THEN 'SYSTEM'::character varying
            ELSE ch.name
        END AS trxsource,
    usr.firstname,
    usr.lastname,
    concat('254', usr.username) AS mobilenumber,
    wtrans.businesstrxid AS uniqueid,
        CASE
            WHEN wtrans.instancetype::text = 'BUSINESS'::text THEN ( SELECT wt.glaccountnumber
               FROM wallettype wt
              WHERE wt.id::text = wtrans.wallettypeid::text)
            ELSE wtrans.walletno
        END AS sourceaccount,
    ( SELECT wallettype.glaccountnumber
           FROM wallettype
          WHERE wallettype.id::text = ((( SELECT walletbalance.wallettypeid
                   FROM walletbalance
                  WHERE walletbalance.id::text = wtrans.otherwalletinstanceid::text))::text)) AS destinationaccount
    FROM selectedtransactions wtrans
     LEFT JOIN businessproduct bp ON wtrans.businessproductid::text = bp.id::text
     LEFT JOIN selectedchildtransactions scwt ON scwt.executionid::text = wtrans.executionid::text AND scwt.walletinstanceid::text = wtrans.walletinstanceid::text
     LEFT JOIN users usr ON wtrans.fromortouserid::text = usr.id::text
     LEFT JOIN mpesafsi fsi ON wtrans.externalrefid::text = fsi.originatorconversationid::text
     JOIN walletbalance wb ON usr.id::text = wb.ownerid::text
     LEFT JOIN channel ch ON wtrans.channelid::text = ch.id::text
  WHERE wtrans.parentid IS NULL 
  AND (bp.bpcode::text <> ALL (ARRAY['DMPESA'::character varying::text, 'SNDMNY'::character varying::text])) 
  AND wtrans.debitamount > 0::numeric AND wb.producttype::text = 'WALLET'::text
UNION ALL
 select reportrequestid, wtrans.createdon::timestamp(0) without time zone AS date,
        CASE
            WHEN fsi.receiverpartypublicname IS NULL THEN bp.name::text
            WHEN fsi.requesttype::text = 'B2C'::text THEN bp.name::text
            ELSE concat(bp.name, '-', fsi.receiverpartypublicname)
        END AS transactiontype,
    usr.username AS bankid,
        CASE
            WHEN wtrans.description IS NULL OR wtrans.description::text = ''::text THEN bp.name
            ELSE wtrans.description
        END AS paymentdetails,
    wtrans.businesstrxid AS trxreference,
    round(wtrans.debitamount + wtrans.creditamount, 2) AS amount,
    COALESCE(scwt.fee,0) AS transactionfee,
        CASE
            WHEN wtrans.transactionstatus::text = 'PROCESSED'::text THEN 'Success'::text
            ELSE 'Failure'::text
        END AS status,
        CASE
            WHEN wtrans.debitamount > 0::numeric THEN 'DEBIT'::text
            ELSE 'CREDIT'::text
        END AS trxtype,
    usr.username AS customerid,
    ''::character varying AS merchantid,
        CASE
            WHEN wtrans.debitamount > 0::numeric THEN ch.name::text
            ELSE 'SYSTEM'::text
        END AS trxsource,
    usr.firstname,
    usr.lastname,
    concat('254', usr.username) AS mobilenumber,
    wtrans.businesstrxid AS uniqueid,
        CASE
            WHEN wtrans.instancetype::text = 'BUSINESS'::text THEN ( SELECT wt.glaccountnumber
               FROM wallettype wt
              WHERE wt.id::text = wtrans.wallettypeid::text)
            ELSE wtrans.walletno
        END AS sourceaccount,
    ( SELECT walletbalance.walletno
           FROM walletbalance
          WHERE walletbalance.id::text = wtrans.otherwalletinstanceid::text) AS destinationaccount
   FROM selectedtransactions wtrans
     LEFT JOIN businessproduct bp ON wtrans.businessproductid::text = bp.id::text
     LEFT JOIN selectedchildtransactions scwt ON scwt.executionid::text = wtrans.executionid::text AND scwt.walletinstanceid::text = wtrans.walletinstanceid::text
     LEFT JOIN users usr ON wtrans.fromortouserid::text = usr.id::text
     LEFT JOIN mpesafsi fsi ON wtrans.externalrefid::text = fsi.originatorconversationid::text
     JOIN walletbalance wb ON usr.id::text = wb.ownerid::text
     LEFT JOIN channel ch ON wtrans.channelid::text = ch.id::text
  WHERE wtrans.parentid IS NULL AND bp.bpcode::text = 'SNDMNY'::text 
  AND wb.producttype::text = 'WALLET'::text AND (wtrans.creditamount > 0::numeric OR wtrans.debitamount > 0::numeric)
UNION ALL
select reportrequestid, wtrans.createdon::timestamp(0) without time zone AS date,
    lp.name AS transactiontype,
    usr.username AS bankid,
        CASE
            WHEN wtrans.description IS NULL THEN lp.name
            ELSE wtrans.description
        END AS paymentdetails,
    wtrans.businesstrxid AS trxreference,
	CASE
            WHEN wtrans.debitamount > 0 THEN round(wtrans.debitamount, 2)
	    ELSE round(wtrans.creditamount, 2)
        END AS amount,
    COALESCE(scwt.fee,0) AS transactionfee,
        CASE
            WHEN wtrans.transactionstatus::text = 'PROCESSED'::text THEN 'Success'::text
            ELSE 'Failure'::text
        END AS status,
CASE
            WHEN wtrans.debitamount > 0 THEN 'DEBIT'::text
	    ELSE 'CREDIT'::text
        END AS trxtype,
    usr.username AS customerid,
    ''::character varying AS merchantid,
        CASE
            WHEN wtrans.channelid::text = 'SYSTEM'::text THEN 'SYSTEM'::character varying
            ELSE ch.name
        END AS trxsource,
    usr.firstname,
    usr.lastname,
    concat('254', usr.username) AS mobilenumber,
    wtrans.businesstrxid AS uniqueid,
CASE 
WHEN wtrans.debitamount > 0 THEN
        CASE
            WHEN wtrans.instancetype::text = 'BUSINESS'::text THEN ( SELECT wt.glaccountnumber
               FROM wallettype wt
              WHERE wt.id::text = wtrans.wallettypeid::text)
            ELSE wtrans.walletno
	END
ELSE
CASE
            WHEN wtrans.otherwalletinstanceid IS NULL THEN ( SELECT w2.glaccountnumber
               FROM wallettype w2
                 JOIN selectedtransactions w3 ON w2.id::text = w3.wallettypeid::text
              WHERE w3.executionid::text = wtrans.executionid::text AND w3.debitamount > 0::numeric AND (w3.instancetype::text = 'CUSTOMER'::text OR w3.instancetype::text = 'BUSINESS'::text AND w3.externalrefid IS NOT NULL))
            ELSE ( SELECT wallettype.glaccountnumber
               FROM wallettype
              WHERE wallettype.id::text = ((( SELECT walletbalance.wallettypeid
                       FROM walletbalance
                      WHERE walletbalance.id::text = wtrans.otherwalletinstanceid::text))::text))
        END
END AS sourceaccount,
CASE
            WHEN wtrans.debitamount > 0 THEN l.accountnumber
 ELSE wb.walletno
 END AS destinationaccount
   FROM selectedtransactions wtrans
     JOIN loan l ON wtrans.sourceid::text = l.id::text
     LEFT JOIN loanproduct lp ON l.loanproductid::text = lp.id::text
	 LEFT JOIN selectedchildtransactions scwt ON scwt.executionid::text = wtrans.executionid::text AND scwt.walletinstanceid::text = wtrans.walletinstanceid::text
     LEFT JOIN users usr ON wtrans.fromortouserid::text = usr.id::text
     LEFT JOIN walletbalance wb ON usr.id::text = wb.ownerid::text
     LEFT JOIN channel ch ON wtrans.channelid::text = ch.id::text
  WHERE wtrans.chargebackofid IS NULL 
  AND wb.producttype::text = 'WALLET'::text 
  AND (wtrans.instancetype::text = 'CUSTOMER'::text OR wtrans.instancetype::text = 'BUSINESS'::text AND wtrans.externalrefid IS NOT NULL)
UNION ALL
 select reportrequestid, wtrans.createdon::timestamp(0) without time zone AS date,
    wtrans.description AS transactiontype,
    usr.username AS bankid,
        CASE
            WHEN wtrans.description IS NULL OR wtrans.description::text = ''::text THEN rdp.rdaccountno
            ELSE wtrans.description
        END AS paymentdetails,
    wtrans.businesstrxid AS trxreference,
    round(wtrans.debitamount, 2) AS amount,
   COALESCE(scwt.fee,0) AS transactionfee,
        CASE
            WHEN wtrans.transactionstatus::text = 'PROCESSED'::text THEN 'Success'::text
            ELSE 'Failure'::text
        END AS status,
    'DEBIT'::text AS trxtype,
    usr.username AS customerid,
    ''::character varying AS merchantid,
        CASE
            WHEN wtrans.channelid::text = 'SYSTEM'::text THEN 'SYSTEM'::character varying
            ELSE ch.name
        END AS trxsource,
    usr.firstname,
    usr.lastname,
    concat('254', usr.username) AS mobilenumber,
    wtrans.businesstrxid AS uniqueid,
        CASE
            WHEN wtrans.instancetype::text = 'BUSINESS'::text THEN ( SELECT wt.glaccountnumber
               FROM wallettype wt
              WHERE wt.id::text = wtrans.wallettypeid::text)
            ELSE wtrans.walletno
        END AS sourceaccount,
        CASE
            WHEN wtrans.description::text ~~ '%RD_PRECLOSURE DISBURSAL%'::text THEN ( SELECT walletbal.walletno
               FROM walletbalance walletbal
              WHERE walletbal.wallettypeid::text = rdp.matureamountdeposittoaccountid::text AND walletbal.producttype::text = 'WALLET'::text AND walletbal.ownerid::text = rdp.userid::text)
            WHEN wtrans.description::text ~~ '%TAX_%'::text THEN ( SELECT wt.glaccountnumber
               FROM wallettype wt
                 JOIN walletbalance wb1 ON wt.id::text = wb1.wallettypeid::text AND wb1.id::text = wtrans.otherwalletinstanceid::text)
            ELSE ( SELECT walletbalance.walletno
               FROM walletbalance
              WHERE walletbalance.id::text = rdp.walletbalanceid::text)
        END AS destinationaccount
     FROM selectedtransactions wtrans
     JOIN rdproductassociation rdp ON wtrans.sourceid::text = rdp.id::text
     JOIN users usr ON wtrans.fromortouserid::text = usr.id::text
     JOIN walletbalance wb ON usr.id::text = wb.ownerid::text
     LEFT JOIN selectedchildtransactions scwt ON scwt.executionid::text = wtrans.executionid::text AND scwt.walletinstanceid::text = wtrans.walletinstanceid::text
     LEFT JOIN channel ch ON wtrans.channelid::text = ch.id::text
  WHERE wtrans.parentid IS NULL AND wtrans.debitamount > 0::numeric 
  AND wtrans.chargebackofid IS NULL AND wb.producttype::text = 'WALLET'::text 
  AND (wtrans.instancetype::text = 'CUSTOMER'::text OR wtrans.instancetype::text = 'BUSINESS'::text AND wtrans.externalrefid IS NOT NULL) 
  AND wtrans.description::text !~~ 'RD_PRECLOSURE DISBURSAL%'::text 
  AND wtrans.description::text !~~ 'PRECLOSURE_RD DISBURSAL%'::text AND rdp.walletbalanceid IS NOT null
UNION ALL
 select reportrequestid, wtrans.createdon::timestamp(0) without time zone AS date,
    wtrans.description AS transactiontype,
    usr.username AS bankid,
        CASE
            WHEN wtrans.description IS NULL OR wtrans.description::text = ''::text THEN rdp.rdaccountno
            ELSE wtrans.description
        END AS paymentdetails,
    wtrans.businesstrxid AS trxreference,
    round(wtrans.creditamount, 2) AS amount,
   COALESCE(scwt.fee,0) AS transactionfee,
        CASE
            WHEN wtrans.transactionstatus::text = 'PROCESSED'::text THEN 'Success'::text
            ELSE 'Failure'::text
        END AS status,
    'CREDIT'::text AS trxtype,
    usr.username AS customerid,
    ''::character varying AS merchantid,
        CASE
            WHEN wtrans.channelid::text = 'SYSTEM'::text THEN 'SYSTEM'::character varying
            ELSE ch.name
        END AS trxsource,
    usr.firstname,
    usr.lastname,
    concat('254', usr.username) AS mobilenumber,
    wtrans.businesstrxid AS uniqueid,
    ( SELECT w.walletno
           FROM rdproductassociation r
             JOIN walletbalance w ON w.id::text = r.walletbalanceid::text
          WHERE r.id::text = wtrans.sourceid::text) AS sourceaccount,
    wb.walletno AS destinationaccount
    FROM selectedtransactions wtrans
     JOIN rdproductassociation rdp ON wtrans.sourceid::text = rdp.id::text
     JOIN users usr ON wtrans.fromortouserid::text = usr.id::text
     JOIN walletbalance wb ON usr.id::text = wb.ownerid::text
     LEFT JOIN selectedchildtransactions scwt ON scwt.executionid::text = wtrans.executionid::text AND scwt.walletinstanceid::text = wtrans.walletinstanceid::text
     LEFT JOIN channel ch ON wtrans.channelid::text = ch.id::text
  WHERE wtrans.parentid IS NULL AND wtrans.creditamount > 0::numeric AND wtrans.chargebackofid IS NULL 
  AND wb.producttype::text = 'WALLET'::text AND wtrans.walletno::text = wb.walletno::text 
  AND wtrans.instancetype::text = 'CUSTOMER'::text
UNION ALL
 select reportrequestid, wtrans.createdon::timestamp(0) without time zone AS date,
    wtrans.description AS transactiontype,
    usr.username AS bankid,
    wtrans.description AS paymentdetails,
    wtrans.businesstrxid AS trxreference,
    round(wtrans.debitamount, 2) AS amount,
    COALESCE(scwt.fee,0) AS transactionfee,
        CASE
            WHEN wtrans.transactionstatus::text = 'PROCESSED'::text THEN 'Success'::text
            ELSE 'Failure'::text
        END AS status,
    'DEBIT'::text AS trxtype,
    usr.username AS customerid,
    ''::character varying AS merchantid,
        CASE
            WHEN wtrans.channelid::text = 'SYSTEM'::text THEN 'SYSTEM'::character varying
            ELSE ch.name
        END AS trxsource,
    usr.firstname,
    usr.lastname,
    concat('254', usr.username) AS mobilenumber,
    wtrans.businesstrxid AS uniqueid,
        CASE
            WHEN wtrans.instancetype::text = 'BUSINESS'::text THEN ( SELECT wt.glaccountnumber
               FROM wallettype wt
              WHERE wt.id::text = wtrans.wallettypeid::text)
            ELSE wtrans.walletno
        END AS sourceaccount,
    ( SELECT wallettype.glaccountnumber
           FROM wallettype
          WHERE wallettype.id::text = ((( SELECT walletbalance.wallettypeid
                   FROM walletbalance
                  WHERE walletbalance.id::text = wtrans.otherwalletinstanceid::text))::text)) AS destinationaccount
     FROM selectedtransactions wtrans
     JOIN insurancesubscription ins ON wtrans.sourceid::text = ins.id::text
     JOIN users usr ON wtrans.fromortouserid::text = usr.id::text
     JOIN walletbalance wb ON usr.id::text = wb.ownerid::text
     LEFT JOIN selectedchildtransactions scwt ON scwt.executionid::text = wtrans.executionid::text AND scwt.walletinstanceid::text = wtrans.walletinstanceid::text
     LEFT JOIN channel ch ON wtrans.channelid::text = ch.id::text
  WHERE wtrans.parentid IS NULL AND wtrans.creditamount = 0::numeric AND wtrans.debitamount > 0::numeric 
  AND wtrans.chargebackofid IS NULL AND wb.producttype::text = 'WALLET'::text 
  AND (wtrans.instancetype::text = 'CUSTOMER'::text OR wtrans.instancetype::text = 'BUSINESS'::text AND wtrans.externalrefid IS NOT NULL)
UNION ALL
 select reportrequestid, wtrans.createdon::timestamp(0) without time zone AS date,
    wtrans.description AS transactiontype,
    usr.username AS bankid,
    wtrans.description AS paymentdetails,
    wtrans.businesstrxid AS trxreference,
    round(wtrans.debitamount, 2) AS amount,
    COALESCE(scwt.fee,0) AS transactionfee,
        CASE
            WHEN wtrans.transactionstatus::text = 'PROCESSED'::text THEN 'Success'::text
            ELSE 'Failure'::text
        END AS status,
    'DEBIT'::text AS trxtype,
    usr.username AS customerid,
    ''::character varying AS merchantid,
        CASE
            WHEN wtrans.channelid::text = 'SYSTEM'::text THEN 'SYSTEM'::character varying
            ELSE ch.name
        END AS trxsource,
    usr.firstname,
    usr.lastname,
    concat('254', usr.username) AS mobilenumber,
    wtrans.businesstrxid AS uniqueid,
        CASE
            WHEN wtrans.instancetype::text = 'BUSINESS'::text THEN ( SELECT wt.glaccountnumber
               FROM wallettype wt
              WHERE wt.id::text = wtrans.wallettypeid::text)
            ELSE wtrans.walletno
        END AS sourceaccount,
    ( SELECT wallettype.glaccountnumber
           FROM wallettype
          WHERE wallettype.id::text = ((( SELECT walletbalance.wallettypeid
                   FROM walletbalance
                  WHERE walletbalance.id::text = wtrans.otherwalletinstanceid::text))::text)) AS destinationaccount
    FROM selectedtransactions wtrans
     JOIN users usr ON wtrans.fromortouserid::text = usr.id::text
     LEFT JOIN walletbalance wb ON usr.id::text = wb.ownerid::text
     LEFT JOIN selectedchildtransactions scwt ON scwt.executionid::text = wtrans.executionid::text AND scwt.walletinstanceid::text = wtrans.walletinstanceid::text
     LEFT JOIN channel ch ON wtrans.channelid::text = ch.id::text
  WHERE wtrans.parentid IS NULL AND wtrans.debitamount > 0::numeric AND wtrans.sourceid IS NULL 
  AND wtrans.businessproductid IS NULL AND wtrans.chargebackofid IS NULL 
  AND wb.producttype::text = 'WALLET'::text 
  AND (wtrans.instancetype::text = 'CUSTOMER'::text OR wtrans.instancetype::text = 'BUSINESS'::text AND wtrans.externalrefid IS NOT NULL)
UNION ALL
 select reportrequestid, wtrans.createdon::timestamp(0) without time zone AS date,
    wtrans.description AS transactiontype,
    usr.username AS bankid,
    wtrans.description AS paymentdetails,
    wtrans.businesstrxid AS trxreference,
    round(wtrans.creditamount, 2) AS amount,
    COALESCE(scwt.fee,0) AS transactionfee,
        CASE
            WHEN wtrans.transactionstatus::text = 'PROCESSED'::text THEN 'Success'::text
            ELSE 'Failure'::text
        END AS status,
    'CREDIT'::text AS trxtype,
    usr.username AS customerid,
    ''::character varying AS merchantid,
        CASE
            WHEN wtrans.channelid::text = 'SYSTEM'::text THEN 'SYSTEM'::character varying
            ELSE ch.name
        END AS trxsource,
    usr.firstname,
    usr.lastname,
    concat('254', usr.username) AS mobilenumber,
    wtrans.businesstrxid AS uniqueid,
        CASE
            WHEN wtrans.instancetype::text = 'BUSINESS'::text THEN ( SELECT wt.glaccountnumber
               FROM wallettype wt
              WHERE wt.id::text = wtrans.wallettypeid::text)
            ELSE wtrans.walletno
        END AS sourceaccount,
    ( SELECT wallettype.glaccountnumber
           FROM wallettype
          WHERE wallettype.id::text = ((( SELECT walletbalance.wallettypeid
                   FROM walletbalance
                  WHERE walletbalance.id::text = wtrans.otherwalletinstanceid::text))::text)) AS destinationaccount
      FROM selectedtransactions wtrans
     JOIN users usr ON wtrans.fromortouserid::text = usr.id::text
     LEFT JOIN walletbalance wb ON usr.id::text = wb.ownerid::text
     LEFT JOIN selectedchildtransactions scwt ON scwt.executionid::text = wtrans.executionid::text AND scwt.walletinstanceid::text = wtrans.walletinstanceid::text
     LEFT JOIN channel ch ON wtrans.channelid::text = ch.id::text
  WHERE wtrans.parentid IS NULL AND wtrans.debitamount = 0::numeric AND wtrans.creditamount > 0::numeric AND wtrans.sourceid IS NULL 
 AND wtrans.businessproductid IS NULL AND wtrans.chargebackofid IS NULL 
AND wb.producttype::text = 'WALLET'::text 
AND (wtrans.instancetype::text = 'CUSTOMER'::text OR wtrans.instancetype::text = 'BUSINESS'::text AND wtrans.externalrefid IS NOT NULL));
	end;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_gldetailsreport(varchar);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_gldetailsreport(requestid character varying)
 LANGUAGE plpgsql
AS $procedure$
Begin
truncate "dataReports".rpt_gldetailsreport;
insert into "dataReports".rpt_gldetailsreport
select requestid, w2.glaccountnumber AS accountid,
    w2.name AS description,
    ( SELECT
                CASE
                    WHEN w.otherwalletinstanceid IS NULL THEN 'Business'::character varying
                    ELSE ( SELECT walletbalance.walletno
                       FROM walletbalance
                      WHERE walletbalance.id::text = w.otherwalletinstanceid::text)
                END AS walletno) AS customerid,
    ( SELECT
                CASE
                    WHEN w.fromortouserid IS NULL OR w.fromortouserid::text = 'NEW_THREAD'::text THEN 'Business'::character varying
                    ELSE ( SELECT users.username
                       FROM users
                      WHERE users.id::text = w.fromortouserid::text)
                END AS username) AS mobilenumber,
        CASE
            WHEN w.creditamount > 0::numeric THEN 'Credit'::text
            ELSE 'Debit'::text
        END AS trxtype,
        CASE
            WHEN w.description IS NULL OR w.description::text = ''::text THEN ( SELECT b.name
               FROM businessproduct b
              WHERE b.id::text = w.businessproductid::text)
            ELSE w.description
        END AS trxdescription,
    w.businesstrxid AS serialid,
    w.createdon::timestamp(0) without time zone AS trxdate,
        CASE
            WHEN w.creditamount > 0::numeric THEN round(w.totalbalance - w.creditamount, 2)
            ELSE round(w.totalbalance + w.debitamount, 2)
        END AS openingbalance,
    round(w.creditamount, 2) AS creditamount,
    round(w.debitamount, 2) AS debitamount,
    round(w.totalbalance, 2) AS closingbalance
     FROM wallettransactions w
     JOIN wallettype w2 ON w.wallettypeid::text = w2.id::text AND (w.transactionstatus::text = 'PROCESSED'::text OR w.transactionstatus::text = 'FAILED'::text)
              and w.createdon >= (concat(now()::date - 1,' ', '00:00:00')::timestamp without time zone) and  w.createdon <= (concat(now()::date - 1,' ', '23:59:59')::timestamp without time zone)
  ORDER BY w.createdon DESC;
  End;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_income_accrual_report(varchar, date, date);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_income_accrual_report(requestid character varying, start_date date DEFAULT ((now())::date - (date_part('days'::text, (date_trunc('month'::text, (((now())::date - 28))::timestamp with time zone) + '1 mon -1 days'::interval)))::integer), end_date date DEFAULT ((now())::date - 1))
 LANGUAGE plpgsql
AS $procedure$
begin
truncate "dataReports".rpt_income_accrual_report;
insert into "dataReports".rpt_income_accrual_report
select requestid,interestacc.date,interestacc.amount, penalty.amount , facility.amount
from (select date(w.createdon),sum(creditamount) as amount
from wallettransactions w 
where w.wallettypeid ='2776e4a9-49bd-4e22-9ce8-c011183996cb' and w.creditamount > 0 and date(w.createdon) >= start_date and date(w.createdon) <= end_date
group by date(w.createdon)) interestacc 
join (select date(w.createdon),sum(creditamount) as amount
from wallettransactions w 
where w.wallettypeid ='f95e33bd-475c-42ca-ad42-d30628efddc1' and w.creditamount > 0 and date(w.createdon) >= start_date and date(w.createdon) <= end_date
group by date(w.createdon)) penalty on penalty.date = interestacc.date
join (select date(w.createdon),sum(creditamount) as amount
from wallettransactions w 
where w.wallettypeid ='204039fb-8c0d-439a-970d-e31896b8e8d6' and w.creditamount > 0 and date(w.createdon) >= start_date and date(w.createdon) <= end_date
group by date(w.createdon)) facility on facility.date = penalty.date;
end;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_interestaccrual(varchar);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_interestaccrual(requestid character varying)
 LANGUAGE plpgsql
AS $procedure$
BEGIN
truncate "dataReports".rpt_interestaccrual;
insert into "dataReports".rpt_interestaccrual
 SELECT  requestid,rd.rdaccountno AS accountid,
    concat('254', usr.username) AS mobilenumber,
    rd.accountstatus,
    concat(usr.firstname, ' ', usr.lastname) AS name,
    date(da.acuraldonetill) AS accrualdate,
    round(da.dailyaccuralamount, 2) AS value,
    round(da.totalinterestaccured, 2) AS totalaccrued,
    round(rd.totalamountdeposited, 2) AS balance,
    round(da.dailyaccuralamount, 2) AS baseaccrued,
    round(rd.bonusamountdisbursed, 2) AS bonusaccrued
    FROM depositaccural da
     JOIN users usr ON da.userid::text=usr.id::text
     LEFT JOIN rdproductassociation rd ON da.depositproductassociationid::text=rd.id::text;
      end;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_loanclosed_report(varchar, timestamp, timestamp);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_loanclosed_report(requestid character varying, start_date timestamp without time zone DEFAULT (concat(((now())::date - 1), ' ', '00:00:00'))::timestamp without time zone, end_date timestamp without time zone DEFAULT (concat(((now())::date - 1), ' ', '23:59:59'))::timestamp without time zone)
 LANGUAGE plpgsql
AS $procedure$
begin
-- stored procedure body
INSERT INTO "dataReports".rpt_closed_loan_report
select requestid, l.accountnumber as accountid,
case 
	when l.loanproductid = 'e0cff44e-bf30-43cf-91ab-82b3f2446980' then '30 Day loan'
	else 'Term Loan'
end as productname,
CONCAT(u.firstname, ' ', u.lastname) as name,
u.username as mobile,
round(l.principalDisbursed,2) as loanamount,
l.actualdisbursementdate as disbursementdate,
l.actualCloseDate as closeddate,
date_part('days',(l.actualCloseDate - l.actualdisbursementdate)) as loanclosedafterdisbursement,
round(l.lastinstallmentamount,2) as closeddateamount,
CASE
WHEN l.loanstatus = 'CLOSED' THEN 'Fully Paid'::text
ELSE
l.loanstatus
END as loanstatus
from Loan l left join users u on l.userid=u.id where l.loanstatus = 'CLOSED' and l.actualclosedate between start_date and end_date;

end;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_loanlimitsreport(varchar);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_loanlimitsreport(reportrequestid character varying)
 LANGUAGE plpgsql
AS $procedure$
begin
 truncate "dataReports".rpt_loanlimitsreport;
 insert  into "dataReports".rpt_loanlimitsreport
 SELECT reportrequestid,concat(usr.firstname, ' ', usr.middlename, ' ', usr.lastname) AS customername,
    concat('254', usr.username) AS mobilenumber,
    round(cl.creditlimit, 2) AS creditlimit,
        CASE
            WHEN cl.limitlastupdatedon IS NULL THEN cl.createdon::timestamp(0) without time zone
            ELSE cl.limitlastupdatedon::timestamp(0) without time zone
        END AS limitlastupdatedon,
    cl.limitexpirydate::timestamp(0) without time zone AS limitexpirydate,
        CASE
            WHEN date(cl.limitexpirydate) > date(now()) THEN 'Valid'::text
            ELSE 'Expired'::text
        END AS limitstatus,
    cl.loanterm as loanterm
     FROM users usr
     JOIN creditlimit cl ON usr.id::text = cl.userid::text
     JOIN role rl ON usr.roleid::text = rl.id::text
  WHERE rl.roletype::text <> 'OPERATIONAL'::text AND cl.creditlimit > 0::numeric
  ORDER BY (
        CASE
            WHEN cl.limitlastupdatedon IS NULL THEN cl.createdon::timestamp(0) without time zone
            ELSE cl.limitlastupdatedon::timestamp(0) without time zone
        END) DESC;
        end;
$procedure$
;

