$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_merchantdetailsreport(varchar);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_merchantdetailsreport(requestid character varying)
 LANGUAGE plpgsql
AS $procedure$
Begin
insert into "dataReports".rpt_merchantdetailsreport
select  requestid, usr.username  AS merchantid,
    usr.createdon::timestamp(0) without time zone AS dateopened,
        CASE
            WHEN kyc.title IS NULL THEN ' '::character varying
            ELSE kyc.title
        END AS salutation,
    usr.lastname AS surname,
    usr.firstname,
    usr.middlename AS othername,
    concat(usr.firstname, ' ', usr.middlename, ' ', usr.lastname) AS fullname,
    usr.idnumber AS idnumber,
    usr.businessname  AS businessname,
    usr.krapinnumber  AS krapinnumber,
    usr.natureofbusiness  AS natureofbusiness,
    usr.sourceoffunds  AS sourceoffunds,
    date(usr.dob) AS dateofbirth,
    usr.gender,
    'KE'::text AS nationality,
    concat('254', usr.mobilenumber) AS mobilenumber,
    usr.email AS emailaddress,
    usr.address AS address,
    usr.state as state,
    usr.country as country,
    usr.pincode AS zipcode,
    usr.city AS citytown,
        CASE
            WHEN kyc.createdon IS NULL THEN ' '::text
            ELSE kyc.createdon::timestamp(0) without time zone::text
        END AS createdon,
    usr.idtype AS documenttype,
        CASE
            WHEN usr.riskrating  IS NULL THEN ' '::character varying
            ELSE usr.riskrating
        END AS riskrating,
    usr.kycstatus
 FROM users usr
     LEFT JOIN userkycdetails kyc ON usr.id::text = kyc.userid::text  
     JOIN role rl ON usr.roleid::text = rl.id::text AND rl.roletype::text = 'BUSINESS_ASSOCIATE'::text
    AND rl.subtype::text = 'MERCHANT'::text;
   End;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_merchantregistrationauditlogreport(varchar, timestamp, timestamp);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_merchantregistrationauditlogreport(requesterid character varying, start_date timestamp without time zone DEFAULT (concat(((now())::date - 1), ' ', '00:00:00'))::timestamp without time zone, end_date timestamp without time zone DEFAULT (concat(((now())::date - 1), ' ', '23:59:59'))::timestamp without time zone)
 LANGUAGE plpgsql
AS $procedure$
BEGIN
truncate "dataReports".rpt_merchantregistrationauditlogreport;
insert into "dataReports".rpt_merchantregistrationauditlogreport
SELECT requesterid, 
date(rl.createdon) AS creationdate,
rl.createdon::timestamp(0) without time zone::time without time zone AS creationtime,
rl.mobileNumber,
rl.idNumber,
rl.idType,
rl.email,
rl.referralCode,
rl.agreementAccepted,
rl.errorCode,
rl.errorMsg,
rl.firstname,
rl.middlename,
rl.lastname,
rl.requestid as merchantrequestid,
c.name as registrationChannel from MerchantRegistrationAuditLog rl 
left join channel c on rl.registrationChannelId=c.id
where  rl.createdon  >= start_date
  AND rl.createdon <= end_date;
end;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_mpesaairtimereport(varchar, date);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_mpesaairtimereport(requesterid character varying, run_date date DEFAULT ((now())::date - 1))
 LANGUAGE plpgsql
AS $procedure$
begin
truncate "dataReports".rpt_mpesaairtimereport;
insert into "dataReports".rpt_mpesaairtimereport
select * from (SELECT 
	requesterid,
    concat(w.businesstrxid, ' / ', w.executionid) AS trxbatchid,
    concat(date(w.txtime),' ',w.txtime::timestamp(0) without time zone::time without time zone) AS requestTime,
    CASE
            WHEN w.instanceType ='BUSINESS' THEN ou.username
    ELSE u.username
    END AS mobile,
    m.transid,
        CASE
            WHEN w.debitamount > 0::numeric THEN round(w.debitamount + w.creditamount, 2) * '-1'::integer::numeric
            ELSE round(w.debitamount + w.creditamount, 2)
        END AS trxamount,
        CASE
            WHEN w.creditamount > 0::numeric THEN 'Credit'::text
            WHEN w.debitamount > 0::numeric THEN 'Debit'::text
            ELSE NULL::text
        END AS trxtype,
        CASE
            WHEN w.description IS NULL OR w.description::text = ''::text THEN bp.name
            ELSE w.description
        END AS trxnarration,
    wt.glaccountnumber AS glid,
    m.receivermsisdn,
        CASE
            WHEN w.chargebackbyid IS NOT NULL AND w.transactionstatus::text = 'PROCESSED'::text THEN 'Chargeback'::text
            WHEN w.transactionstatus::text = 'PROCESSED'::text THEN 'Success'::text
            ELSE concat('Failed - ', w.description)
        END AS status
      FROM wallettransactions w inner JOIN mpesaairtimepaymentdata m ON w.externalrefid = m.externalrefid
      JOIN businessproduct bp ON w.businessproductid::text = bp.id::text --and bp.bpcode in('BLWMBC')
     LEFT JOIN wallettype wt ON w.wallettypeid::text = wt.id::text
LEFT JOIN walletbalance wb ON w.walletinstanceid =  wb.id
LEFT JOIN walletbalance owb ON w.otherwalletinstanceid =  owb.id
LEFT JOIN users u ON wb.ownerid=u.id
LEFT JOIN users ou ON owb.ownerid = ou.id where date(w.txtime) = run_date) as mpesaairtimereport  order by requestTime DESC;
end;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_mpesab2breport(varchar, date);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_mpesab2breport(requesterid character varying, run_date date DEFAULT ((now())::date - 1))
 LANGUAGE plpgsql
AS $procedure$
Begin
truncate "dataReports".rpt_mpesab2breport;
insert into "dataReports".rpt_mpesab2breport
select * from (SELECT  requesterid, date(w.txtime) AS date,
    w.txtime::timestamp(0) without time zone::time without time zone AS "time",
    fsi.transactionid AS mpesaref,
    concat(w.businesstrxid, ' / ', w.executionid) AS trxbatchid,
        CASE
            WHEN w.debitamount > 0::numeric THEN round(w.creditamount + w.debitamount, 2) * '-1'::integer::numeric
            ELSE round(w.creditamount + w.debitamount, 2)
        END AS trxamount,
        CASE
            WHEN w.debitamount > 0::numeric THEN 'Debit'::text
            WHEN w.creditamount > 0::numeric THEN 'Credit'::text
            ELSE NULL::text
        END AS trxtype,
        CASE
            WHEN w.description IS NULL OR w.description::text = ''::text THEN bp.name
            ELSE w.description
        END AS trxnarration,
    wt.glaccountnumber AS glid,
    fsi.mobilenumber AS mobile,
        CASE
            WHEN w.chargebackbyid IS NOT NULL AND w.transactionstatus::text = 'PROCESSED'::text THEN 'Chargeback'::text
            WHEN w.transactionstatus::text = 'PROCESSED'::text THEN 'Success'::text
            ELSE concat('Failed - ', fsi.resultdesc)
        END AS status
     FROM mpesafsi fsi
     JOIN wallettransactions w ON fsi.originatorconversationid::text = w.externalrefid::text
     LEFT JOIN wallettype wt ON w.wallettypeid::text = wt.id::text
     LEFT JOIN businessproduct bp ON w.businessproductid::text = bp.id::text
  WHERE fsi.requesttype::text <> 'B2C'::text and date(fsi.requesttime) = run_date
UNION ALL
SELECT  requesterid, date(w.txtime) AS date,
    w.txtime::timestamp(0) without time zone::time without time zone AS "time",
    'N/A'::text AS mpesaref,
    concat(w.businesstrxid, ' / ', w.executionid) AS trxbatchid,
        CASE
            WHEN w.debitamount > 0::numeric THEN round(w.creditamount + w.debitamount, 2) * '-1'::integer::numeric
            ELSE round(w.creditamount + w.debitamount, 2)
        END AS trxamount,
        CASE
            WHEN w.debitamount > 0::numeric THEN 'Debit'::text
            WHEN w.creditamount > 0::numeric THEN 'Credit'::text
            ELSE NULL::text
        END AS trxtype,
        CASE
            WHEN w.description IS NULL OR w.description::text = ''::text THEN bp.name
            ELSE w.description
        END AS trxnarration,
    wt.glaccountnumber AS glid,
    'N/A'::text AS mobile,
        CASE
            WHEN w.chargebackbyid IS NOT NULL AND w.transactionstatus::text = 'PROCESSED'::text THEN 'Chargeback'::text
            WHEN w.transactionstatus::text = 'PROCESSED'::text THEN 'Success'::text
            ELSE concat('Failed - ', w.description)
        END AS status
     FROM wallettransactions w 
     JOIN businessproduct bp ON w.businessproductid::text = bp.id::text and bp.bpcode in('BLMBBB','BLTLBB','BLEXBB')
     LEFT JOIN wallettype wt ON w.wallettypeid::text = wt.id::text) as mpesab2breport order by mpesab2breport.date desc, mpesab2breport.time DESC;
     End;
$procedure$
;

