-- DROP PROCEDURE "dataReports".proc_rpt_pinstatusreport(varchar);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_pinstatusreport(requestid character varying)
 LANGUAGE plpgsql
AS $procedure$
Begin
truncate "dataReports".rpt_pinstatusreport;
insert into "dataReports".rpt_pinstatusreport
SELECT  requestid, usr.username as username,usr.mobilenumber as mobilenumber,
    usr.passwordexpirydate,
        CASE
            WHEN usr.passwordexpirydate >= now() THEN 'Active'::text
            ELSE 'Expired'::text
        END AS pinstatus,
    usr.userstatus AS customerstatus
     FROM users usr
     JOIN role rl ON usr.roleid::text = rl.id::text and ( rl.roletype::text ='CUSTOMER'::text or (rl.roletype::text ='BUSINESS_ASSOCIATE'::text and usr.rolesubtype::text ='MERCHANT'::text));
    End;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_registrationauditlogreport(varchar, timestamp, timestamp);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_registrationauditlogreport(requesterid character varying, start_date timestamp without time zone DEFAULT (concat(((now())::date - 1), ' ', '00:00:00'))::timestamp without time zone, end_date timestamp without time zone DEFAULT (concat(((now())::date - 1), ' ', '23:59:59'))::timestamp without time zone)
 LANGUAGE plpgsql
AS $procedure$
BEGIN
truncate "dataReports".rpt_registrationauditlogreport;
insert into "dataReports".rpt_registrationauditlogreport
SELECT requesterid, 
date(rl.createdon) AS creationdate,
rl.createdon::timestamp(0) without time zone::time without time zone AS creationtime,
rl.mobileNumber,
rl.idNumber,
rl.idType,
rl.email,
rl.referralCode,
rl.agreementAccepted,
rl.errorCode,
rl.errorMsg,
c.name as registrationChannel,
rl.firstname,
rl.middlename,
rl.lastname
from RegistrationAuditLog rl 
left join channel c on rl.registrationChannelId=c.id
where  rl.createdon  >= start_date
  AND rl.createdon <= end_date;	
end;
$procedure$
;

