-- DROP PROCEDURE "dataReports".proc_rpt_savingsaccountreport(varchar);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_savingsaccountreport(requestid character varying)
 LANGUAGE plpgsql
AS $procedure$
BEGIN
truncate "dataReports".rpt_savingsaccountreport;
insert into "dataReports".rpt_savingsaccountreport
 SELECT  requestid,usr.username AS clientid,
    rdpa.rdaccountno AS accountid,
    concat('254', usr.username) AS mobilenumber,
    concat(usr.firstname, ' ', usr.lastname) AS accountname,
    rdp.productnumber AS productid,
    round(rdpa.totalamountdeposited, 2) AS accountbalance,
    rdpa.createdon::timestamp(0) without time zone AS createdon,
    usr.userstatus AS accountstatus,
    '1'::text AS noofgoals,
    rdpa.accountstatus AS "Goal Status",
    rdpa.targetamount AS "Target Amount",
    rdpa.savingperiod AS "Savings Term (In Months)"
    FROM rdproductassociation rdpa
     LEFT JOIN users usr ON rdpa.userid::text = usr.id::text
     LEFT JOIN rdproduct rdp ON rdpa.productid::text = rdp.id::text;
      end;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_staticlimituploadreport(varchar);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_staticlimituploadreport(reportrequestid character varying)
 LANGUAGE plpgsql
AS $procedure$
begin
truncate "dataReports".rpt_staticlimituploadreport;
insert into "dataReports".rpt_staticlimituploadreport
SELECT reportrequestid,  concat(u.firstname, ' ', u.lastname) AS customername,
       CASE
            WHEN substring(blr.mobilenumber::text,1,3) = '254'::text THEN blr.mobilenumber::text else  concat('254', blr.mobilenumber::text)
        END AS mobilenumber,
--concat('254', blr.mobilenumber) AS mobilenumber,blr.mobilenumber AS mobilenumberOUT,u.username,
    round(blr.newlimit, 2) AS newlimit,
    date(blr.limitexpirydate) AS limitexpirydate,
    c.riskcategory AS assessment,
        CASE
            WHEN blr.executionstatus::text = 'EXECUTED_SUCCESS'::text THEN 'Success'::text
            ELSE 'Failure'::text
        END AS updatestatus,
    blb.id AS uploadbatchid,
    blr.createdon::timestamp(0) without time zone AS createdon,
    ( SELECT u_1.username
           FROM users u_1
          WHERE u_1.id::text = blr.createdby::text) AS createdby,
    blr.modifiedon::timestamp(0) without time zone AS supervisedon,
    ( SELECT u_1.username
           FROM users u_1
          WHERE u_1.id::text = blr.modifiedby::text) AS supervisedby
     FROM users u,
    creditlimit c,
    bulklendinglimitrecord blr,
    bulklendinglimitjob blb
  WHERE u.id::text = c.userid::text AND (u.username::text = blr.mobilenumber::text or u.username::text  = substring(blr.mobilenumber::text,4))
AND blr.bulklendinglimitjobid::text = blb.id::text AND (blr.executionstatus::text = 'EXECUTED_SUCCESS'::text OR blr.executionstatus::text = 'EXECUTED_ERROR'::text); end;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_temporarylimittable(varchar);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_temporarylimittable(reportrequestid character varying)
 LANGUAGE plpgsql
AS $procedure$
begin
truncate "dataReports".rpt_temporarylimittable;
insert into "dataReports".rpt_temporarylimittable
SELECT   reportrequestid ,concat(usr.firstname, ' ', usr.lastname) AS "Customer Name",
    concat('254', usr.username) AS "Mobile Number",
    round(clp.creditlimit, 2) AS "Limit Amount (New)",
    clp.createdon::timestamp(0) without time zone AS limitdate,
    clp.riskcategory AS "Assessment",
    round(cl.creditlimit, 2) AS "Old Limit Amount",
    cl.riskcategory AS "Old Assessment",
    clp.status AS "Status"
   FROM users usr
     JOIN creditlimit cl ON usr.id= cl.userid
     JOIN creditlimitpending clp ON usr.id= clp.userid;
 end;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_tl_income_accrual_report(varchar, date, date);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_tl_income_accrual_report(requestid character varying, start_date date DEFAULT ((now())::date - (date_part('days'::text, (date_trunc('month'::text, (((now())::date - 28))::timestamp with time zone) + '1 mon -1 days'::interval)))::integer), end_date date DEFAULT ((now())::date - 1))
 LANGUAGE plpgsql
AS $procedure$
begin
truncate "dataReports".rpt_tl_income_accrual_report;
insert into "dataReports".rpt_tl_income_accrual_report
select requestid, interestincome.date,interestincome.amount, penaltyinterest.amount, interestincome2.amount, penaltyfees.amount 
from (select date(w.createdon),sum(creditamount) as amount
from wallettransactions w
where w.wallettypeid = '69c8e6b6-dc97-4e37-beab-028da54ba845' and w.creditamount > 0 and date(w.createdon) >= start_date and date(w.createdon) <= end_date
group by date(w.createdon)) interestincome
left join (select date(w.createdon),sum(creditamount) as amount
from wallettransactions w
where w.wallettypeid = 'e10a8786-67f4-46d7-a365-4a39eecb30cf' and w.creditamount > 0 and date(w.createdon) >= start_date and date(w.createdon) <= end_date
group by date(w.createdon)) penaltyinterest on penaltyinterest.date = interestincome.date
left join (select date(w.createdon),sum(creditamount) as amount
from wallettransactions w
where w.wallettypeid = 'dc34bf4d-acf5-413a-bebc-8cfc411611e0' and w.creditamount > 0 and date(w.createdon) >= start_date and date(w.createdon) <= end_date
group by date(w.createdon)) interestincome2 on interestincome2.date = interestincome.date
left join (select date(w.createdon),sum(creditamount) as amount
from wallettransactions w
where w.wallettypeid = '70e19df9-a69d-47d2-8f73-490e38e5c6dd' and w.creditamount > 0 and date(w.createdon) >= start_date and date(w.createdon) <= end_date
group by date(w.createdon)) penaltyfees on penaltyfees.date = interestincome.date;
end;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_u756loanreportactive(varchar, date);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_u756loanreportactive(requestid character varying, run_date date DEFAULT (now() - '1 day'::interval))
 LANGUAGE plpgsql
AS $procedure$
begin
	truncate "dataReports".rpt_u756loanreportactive;
 	insert into "dataReports".rpt_u756loanreportactive
	select
		requestid,
		usr.lastname AS "Surname",
	    usr.firstname AS "Forename1",
	    usr.middlename AS "Forename2",
        CASE
            WHEN ukyc.title IS NULL THEN ''::character varying
            ELSE ukyc.title
        END AS "Salutation",
    	to_char(run_date,'dd/mm/yyyy') AS "BusinessDate",
		to_char(dob::DATE,'dd/mm/yyyy') AS "Date_of_Birth",
	    usr.id AS "Client_Number",
	    l.accountnumber AS "Mobile_Loan_Account_Number",
	    usr.gender,
    	'KE'::text AS "Nationality",
	    usr.idtype AS "PrimaryID_type",
	    usr.idnumber AS "PrimaryID_Num",
	    concat('254', usr.username) AS "Mobile_Number",
	    'KE'::text AS "Postal_Country",
	    0 AS salary_band,
	    'Virtual Banking'::text AS "Lender_Branch_Name",
	    160 AS "Lender_Branch_Code",
	    'IN001'::text AS "Account_prod_type",
	    to_char(l.expecteddisbursementdate::DATE,'dd/mm/yyyy') AS "Date_Acct_Opened",
	    to_char(l.expectedfirstrepaymentdate::DATE,'dd/mm/yyyy') AS "Instalment_due_date",
	    round(l.principaldisbursed, 2) AS "Original_Amount",
	    round(l.principaldisbursed, 2) AS local_orig_amount,
		CASE
			WHEN l.loanstatus::text = 'CLOSED'::text THEN round(l.totalamountoutstanding, 2)
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN round(l.totalamountwrittenoff, 2)
            ELSE round(l.totalamountoutstanding, 2)
        END AS "Current_balance",
    	(SELECT
               CASE
                    WHEN loan.loanstatus::text = 'CLOSED'::text THEN round(l.totalamountoutstanding, 2)
                    WHEN loan.loanstatus::text = 'WRITTEN_OFF'::text THEN round(l.totalamountwrittenoff, 2)
                    WHEN date(loan.calucatedclosedate) >= run_date THEN 0::numeric
                    WHEN loan.totalamountoutstanding IS NULL THEN 0::numeric
                    ELSE round(loan.totalamountoutstanding, 2)
                END AS round
		FROM loan
		WHERE loan.accountnumber::text = l.accountnumber::text) AS "Overdue_balance",
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN ' '::text
            WHEN l.calucatedclosedate < run_date THEN to_char((l.calucatedclosedate::DATE + 1),'dd/mm/yyyy')
            ELSE ' '::text
        END AS "Overdue_date",
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::double precision
			WHEN date_part('days'::text, l.calucatedclosedate::timestamp with time zone - run_date) >= 0::double precision THEN 0::double precision
            ELSE date_part('days'::text, l.calucatedclosedate::timestamp with time zone - run_date) * '-1'::integer::double precision
        END AS "Days_in_arrears",
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 'Bucket 0'::text
            ELSE concat('Bucket ', round(lb.currentbucketnumber, 0))
        END AS "Bucket",
		(SELECT
			CASE
				WHEN loan.loanstatus::text = 'CLOSED'::text THEN 0::numeric
				WHEN loan.loanstatus::text = 'WRITTEN_OFF'::text THEN round(l.totalamountwrittenoff, 2)
				WHEN date(loan.calucatedclosedate) > run_date THEN 0::numeric
			    WHEN loan.totalamountoutstanding IS NULL THEN 0::numeric
				ELSE round(loan.totalamountoutstanding, 2)
			END AS round
		FROM loan
		WHERE loan.accountnumber::text = l.accountnumber::text) AS "Instalment_arrears",
    	l.loanstatus AS "Account_Status",
        CASE
            WHEN l.loanstatus::text = 'ACTIVE'::text THEN to_char(l.createdon::DATE,'dd/mm/yyyy')
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN to_char(l.writtenoffdate::DATE,'dd/mm/yyyy')
            else to_char(l.actualclosedate::DATE,'dd/mm/yyyy')
        END AS "Account_status_Date",
		' '::text AS "Reason_For_Closure",
    	1 AS "Repayment_period",
    	''::text AS "Deferred_pymt_Date",
    	''::text AS "Deferred_pymt_amt",
		l.replayfrequency AS "Payment_freq",
		to_char(l.actualdisbursementdate::DATE,'dd/mm/yyyy') AS "Disbursement_Date",
	    round(l.totalexpectedcostofloan, 2) AS "Instalment_amount",
        CASE
            WHEN l.lastpaidon IS NULL THEN ' '::text
            ELSE to_char(l.lastpaidon::DATE,'dd/mm/yyyy')::text
        END AS "Latest_pymt_date",
    	COALESCE(round(l.lastinstallmentamount, 2), 0::numeric) AS "Latest_pymt_Amt",
        CASE
            WHEN l.loanstatus::text = ANY (ARRAY['ACTIVE'::character varying::text, 'WRITTEN_OFF'::character varying::text]) THEN 'ACTIVE'::text
            ELSE 'CLOSED'::text
        END AS "Account_status_desc",
    	lp.name AS product_name,
    	to_char(l.createdon,'dd/mm/yyyy HH:MM:SS') AS createdon,
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::numeric
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN 0::numeric
            ELSE round(l.principaloutstanding, 2)
        END AS "PrincipalOutstanding",
    	(SELECT
			CASE
		    	WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::numeric
				WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN 0::numeric
				ELSE round(l.calcuatedintrest - l.interestrepaidsofar, 2)
			END AS round
        	FROM loanschedule ls
	  		WHERE ls.loanid::text = l.id::text LIMIT 1) AS "Interestoutstanding", round(l.creditlimit, 2) AS "Creditlimit",
		l.riskassessment AS "RiskCategory",
        (SELECT
				sum(round(l2.penaltypending, 2)) AS sum
				FROM loanschedule l2
				WHERE l2.loanid::text = l.id::text) AS "Penaltyfeeoutstanding",
		(SELECT
		 	sum(round(l2.penaltycomponent, 2)) AS sum
           	FROM loanschedule l2
          	WHERE l2.loanid::text = l.id::text) AS "RolloverFees",
	0::numeric AS "ChargeOffInterestPending"
	FROM users usr
 	JOIN loan l ON usr.id::text = l.userid::text and l.loanstatus::text in ('ACTIVE','WRITTEN_OFF') and l.loanproductid = 'e0cff44e-bf30-43cf-91ab-82b3f2446980'
 	LEFT JOIN userkycdetails ukyc ON usr.id::text = ukyc.userid::text
	LEFT JOIN loanbucket lb ON l.id::text = lb.loanid::text
	LEFT JOIN loanproduct lp ON l.loanproductid::text = lp.id::text
union
select
		requestid,
		usr.lastname AS "Surname",
	    usr.firstname AS "Forename1",
	    usr.middlename AS "Forename2",
        CASE
            WHEN ukyc.title IS NULL THEN ''::character varying
            ELSE ukyc.title
        END AS "Salutation",
    	to_char(run_date,'dd/mm/yyyy') AS "BusinessDate",
		to_char(dob::DATE,'dd/mm/yyyy') AS "Date_of_Birth",
	    usr.id AS "Client_Number",
	    l.accountnumber AS "Mobile_Loan_Account_Number",
	    usr.gender,
    	'KE'::text AS "Nationality",
	    usr.idtype AS "PrimaryID_type",
	    usr.idnumber AS "PrimaryID_Num",
	    concat('254', usr.username) AS "Mobile_Number",
	    'KE'::text AS "Postal_Country",
	    0 AS salary_band,
	    'Virtual Banking'::text AS "Lender_Branch_Name",
	    160 AS "Lender_Branch_Code",
	    'IN001'::text AS "Account_prod_type",
	    to_char(l.expecteddisbursementdate::DATE,'dd/mm/yyyy') AS "Date_Acct_Opened",
	    CASE
			WHEN l.loanstatus::text = 'CLOSED'::text THEN to_char((select l2.duedate	FROM loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID')
					order by installmentno desc limit 1)::timestamp with time zone, 'dd/mm/yyyy')
			ELSE to_char((select l2.duedate	FROM loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID')
					order by installmentno limit 1)::timestamp with time zone, 'dd/mm/yyyy')
			END	AS "Instalment_due_date",
	    round(l.principaldisbursed, 2) AS "Original_Amount",
	    round(l.principaldisbursed, 2) AS local_orig_amount,
		CASE
			WHEN l.loanstatus::text = 'CLOSED'::text THEN round(l.totalamountoutstanding, 2)
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN round(l.totalamountwrittenoff, 2)
            WHEN l.loanstatus::text = 'CHARGE_OFF'::text THEN round(lcd.principalchargedoffpending+lcd.interestchargedoffpending+lcd.penaltychargedoffpending+lcd.chargeoffinterestpending, 2)
            else (select round(sum(l2.interestpending+l2.principalpending+l2.penaltypending), 2) FROM loanschedule l2
            WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID'))
        END AS "Current_balance",
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN round(l.totalamountoutstanding, 2)
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN round(l.totalamountwrittenoff, 2)
            WHEN l.loanstatus::text = 'CHARGE_OFF'::text THEN round(lcd.principalchargedoffpending+lcd.interestchargedoffpending+lcd.penaltychargedoffpending+lcd.chargeoffinterestpending, 2)
            WHEN l.totalamountoutstanding IS NULL THEN 0::numeric
            ELSE COALESCE((select round(sum(l2.interestpending+l2.principalpending+l2.penaltypending), 2)  FROM loanschedule l2
            WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') and l2.duedate < run_date),0)
            END AS "Overdue_balance",
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN ' '::text
            WHEN l.calucatedclosedate < run_date - '1 day'::interval THEN to_char(((select l2.duedate	FROM loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') order by installmentno limit 1 ) :: DATE + 1 ),'dd/mm/yyyy')
			WHEN l.calucatedclosedate > run_date - '1 day'::interval and ((select l2.duedate	FROM loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') order by installmentno limit 1 ) :: DATE + 1 ) < run_date -  '1 day'::interval then to_char(((select l2.duedate	FROM loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') order by installmentno limit 1 ) :: DATE + 1 ),'dd/mm/yyyy')
            ELSE ' '::text
        END AS "Overdue_date",
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::double precision
			WHEN date_part('days'::text,
			(select l2.duedate	FROM loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID')
				order by installmentno limit 1)::timestamp with time zone - run_date - '1 day'::interval) >= 0::double precision THEN 0::double precision
            ELSE date_part('days'::text,
            (select l2.duedate	FROM loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID')
				order by installmentno limit 1)::timestamp with time zone - run_date - '1 day'::interval) * '-1'::integer::double precision
        END AS "Days_in_arrears",
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 'Bucket 0'::text
            ELSE concat('Bucket ', round(lb.currentbucketnumber, 0))
        END AS "Bucket",
        CASE
				WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::numeric
				WHEN l.loanstatus::text = 'CHARGE_OFF'::text THEN round(lcd.principalchargedoffpending+lcd.interestchargedoffpending+lcd.penaltychargedoffpending+lcd.chargeoffinterestpending, 2)
                WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN round(l.totalamountwrittenoff, 2)
			    WHEN l.totalamountoutstanding IS NULL THEN 0::numeric
				ELSE (select round(sum(l2.interestpending+l2.principalpending+l2.penaltypending), 2) FROM loanschedule l2
				WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') and l2.duedate < run_date)
			END as "Instalment_arrears",
    	l.loanstatus AS "Account_Status",
        CASE
            WHEN l.loanstatus::text = 'ACTIVE'::text THEN to_char(l.createdon::DATE,'dd/mm/yyyy')
            WHEN l.loanstatus::text = 'CHARGE_OFF'::text THEN to_char(l.chargeoffdate::DATE,'dd/mm/yyyy')
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN to_char(l.writtenoffdate::DATE,'dd/mm/yyyy')
            else to_char(l.actualclosedate::DATE,'dd/mm/yyyy')
        END AS "Account_status_Date",
		' '::text AS "Reason_For_Closure",
		l.loanperiod AS "Repayment_period",
    	''::text AS "Deferred_pymt_Date",
    	''::text AS "Deferred_pymt_amt",
		l.replayfrequency AS "Payment_freq",
		to_char(l.actualdisbursementdate::DATE,'dd/mm/yyyy') AS "Disbursement_Date",
	    round(l.installmentamount, 2) AS "Instalment_amount",
        CASE
            WHEN l.lastpaidon IS NULL THEN ' '::text
            ELSE to_char(l.lastpaidon::DATE,'dd/mm/yyyy')::text
        END AS "Latest_pymt_date",
    	COALESCE(round(l.lastinstallmentamount, 2), 0::numeric) AS "Latest_pymt_Amt",
        CASE
            WHEN l.loanstatus::text = ANY (ARRAY['ACTIVE'::character varying::text,'CHARGE_OFF'::character varying::text ,'WRITTEN_OFF'::character varying::text]) THEN 'ACTIVE'::text
            ELSE 'CLOSED'::text
        END AS "Account_status_desc",
    	lp.name AS product_name,
    	to_char(l.createdon,'dd/mm/yyyy HH:MM:SS') AS createdon,
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::numeric
            WHEN l.loanstatus::text = 'CHARGE_OFF'::text THEN round(lcd.principalchargedoffpending, 2)
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN 0::numeric
            ELSE round(l.principaloutstanding, 2)
        END AS "PrincipalOutstanding",
    	CASE
		   	WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::numeric
		   	WHEN l.loanstatus::text = 'CHARGE_OFF'::text then round(lcd.interestchargedoffpending+lcd.chargeoffinterestpending, 2)
			WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN 0::numeric
			ELSE (select round(sum(l2.interestpending), 2) FROM loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID'))
			END AS "Interestoutstanding",
	  	round(l.creditlimit, 2) AS "Creditlimit",
		l.riskassessment AS "RiskCategory",
		case
			WHEN l.loanstatus::text = 'CHARGE_OFF'::text THEN round(lcd.penaltychargedoffpending, 2)
			WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN 0::numeric
        	else (SELECT
				sum(round(l2.penaltypending, 2)) AS sum
				FROM loanschedule l2
				WHERE l2.loanid::text = l.id::text)
			end AS "Penaltyfeeoutstanding",
		round(l.chargescharged, 2) AS "RolloverFees",
    CASE
      WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::numeric
      WHEN l.loanstatus::text = 'CHARGE_OFF'::text then round(lcd.chargeoffinterestpending, 2)
      ELSE 0::numeric
    END AS "ChargeOffInterestPending"
	FROM users usr
 	JOIN loan l ON usr.id::text = l.userid::text and l.loanstatus::text in ('ACTIVE','WRITTEN_OFF','CHARGE_OFF') and l.loanproductid='68e8db46-c420-4e90-8ef0-2a48c50f9e65'
 	LEFT JOIN userkycdetails ukyc ON usr.id::text = ukyc.userid::text
	LEFT JOIN loanbucket lb ON l.id::text = lb.loanid::text
	LEFT JOIN loanproduct lp ON l.loanproductid::text = lp.id::text
	LEFT JOIN loanchargeoffdata lcd ON l.id=lcd.loanid;
end;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_u756loanreportclosed(varchar, date);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_u756loanreportclosed(requestid character varying, run_date date DEFAULT (concat(((now())::date - 1), ' ', '23:59:59'))::timestamp without time zone)
 LANGUAGE plpgsql
AS $procedure$
begin
 	truncate "dataReports".rpt_u756loanreportclosed;
	insert into "dataReports".rpt_u756loanreportclosed
	select
		requestid,
		usr.lastname AS "Surname",
	    usr.firstname AS "Forename1",
	    usr.middlename AS "Forename2",
        CASE
            WHEN ukyc.title IS NULL THEN ''::character varying
            ELSE ukyc.title
        END AS "Salutation",
    	to_char(run_date,'dd/mm/yyyy') AS "BusinessDate",
		to_char(dob::DATE,'dd/mm/yyyy') AS "Date_of_Birth",
	    usr.id AS "Client_Number",
	    l.accountnumber AS "Mobile_Loan_Account_Number",
	    usr.gender,
    	'KE'::text AS "Nationality",
	    usr.idtype AS "PrimaryID_type",
	    usr.idnumber AS "PrimaryID_Num",
	    concat('254', usr.username) AS "Mobile_Number",
	    'KE'::text AS "Postal_Country",
	    0 AS salary_band,
	    'Virtual Banking'::text AS "Lender_Branch_Name",
	    160 AS "Lender_Branch_Code",
	    'IN001'::text AS "Account_prod_type",
	    to_char(l.expecteddisbursementdate::DATE,'dd/mm/yyyy') AS "Date_Acct_Opened",
	    to_char(l.expectedfirstrepaymentdate::DATE,'dd/mm/yyyy') AS "Instalment_due_date",
	    round(l.principaldisbursed, 2) AS "Original_Amount",
	    round(l.principaldisbursed, 2) AS local_orig_amount,
		CASE
			WHEN l.loanstatus::text = 'CLOSED'::text THEN round(l.totalamountoutstanding, 2)
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN round(l.totalamountwrittenoff, 2)
            ELSE round(l.totalamountoutstanding, 2)
        END AS "Current_balance",
		CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN round(l.totalamountoutstanding, 2)
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN round(l.totalamountwrittenoff, 2)
            WHEN date(l.calucatedclosedate) >= run_date THEN 0::numeric
            WHEN l.totalamountoutstanding IS NULL THEN 0::numeric
            ELSE round(l.totalamountoutstanding, 2)
        END AS "Overdue_balance",
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN ' '::text
            WHEN l.calucatedclosedate < run_date THEN to_char((l.calucatedclosedate::DATE + 1),'dd/mm/yyyy')
            ELSE ' '::text
        END AS "Overdue_date",
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::double precision
			WHEN date_part('days'::text, l.calucatedclosedate::timestamp with time zone - run_date) >= 0::double precision THEN 0::double precision
            ELSE date_part('days'::text, l.calucatedclosedate::timestamp with time zone - run_date) * '-1'::integer::double precision
        END AS "Days_in_arrears",
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 'Bucket 0'::text
            ELSE concat('Bucket ', round(lb.currentbucketnumber, 0))
        END AS "Bucket",
		CASE
			WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::numeric
			WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN round(l.totalamountwrittenoff, 2)
			WHEN date(l.calucatedclosedate) > run_date THEN 0::numeric
		    WHEN l.totalamountoutstanding IS NULL THEN 0::numeric
			ELSE round(l.totalamountoutstanding, 2)
		end AS "Instalment_arrears",
    	l.loanstatus AS "Account_Status",
        CASE
            WHEN l.loanstatus::text = 'ACTIVE'::text THEN to_char(l.createdon::DATE,'dd/mm/yyyy')
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN to_char(l.writtenoffdate::DATE,'dd/mm/yyyy')
            else to_char(l.actualclosedate::DATE,'dd/mm/yyyy')
        END AS "Account_status_Date",
		' '::text AS "Reason_For_Closure",
    	l.loanperiod AS "Repayment_period",
    	''::text AS "Deferred_pymt_Date",
    	''::text AS "Deferred_pymt_amt",
		l.replayfrequency AS "Payment_freq",
		to_char(l.actualdisbursementdate::DATE,'dd/mm/yyyy') AS "Disbursement_Date",
	    round(l.totalexpectedcostofloan, 2) AS "Instalment_amount",
        CASE
            WHEN l.lastpaidon IS NULL THEN ' '::text
            ELSE to_char(l.lastpaidon::DATE,'dd/mm/yyyy')::text
        END AS "Latest_pymt_date",
    	COALESCE(round(l.lastinstallmentamount, 2), 0::numeric) AS "Latest_pymt_Amt",
        CASE
            WHEN l.loanstatus::text = ANY (ARRAY['ACTIVE'::character varying::text, 'WRITTEN_OFF'::character varying::text]) THEN 'ACTIVE'::text
            ELSE 'CLOSED'::text
        END AS "Account_status_desc",
    	lp.name AS product_name,
		to_char(l.createdon,'dd/mm/yyyy HH24:MI:SS') AS createdon,
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::numeric
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN 0::numeric
            ELSE round(l.principaloutstanding, 2)
        END AS "PrincipalOutstanding",
    	CASE
	    	WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::numeric
			WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN 0::numeric
			ELSE round(l.calcuatedintrest - l.interestrepaidsofar, 2)
		END as "Interestoutstanding",
  		round(l.creditlimit, 2) AS "Creditlimit",
		l.riskassessment AS "RiskCategory",
        (SELECT
				sum(round(l2.penaltypending, 2)) AS sum
				FROM loanschedule l2
				WHERE l2.loanid::text = l.id::text) AS "Penaltyfeeoutstanding",
		(SELECT
		 	sum(round(l2.penaltycomponent, 2)) AS sum
           	FROM loanschedule l2
          	WHERE l2.loanid::text = l.id::text) AS "RolloverFees",
     0::numeric AS "ChargeOffInterestPending"
  FROM users usr
 	JOIN loan l ON usr.id::text = l.userid::text and l.loanstatus::text = 'CLOSED'
 	LEFT JOIN userkycdetails ukyc ON usr.id::text = ukyc.userid::text
	LEFT JOIN loanbucket lb ON l.id::text = lb.loanid::text
	LEFT JOIN loanproduct lp ON l.loanproductid::text = lp.id::text;
end;
$procedure$
;

