-- DROP PROCEDURE public.glsnapshot(timestamp);

CREATE OR REPLACE PROCEDURE public.glsnapshot(today timestamp without time zone)
 LANGUAGE sql
AS $procedure$
with temp_glsummary_today as
(select wt.id as wallettypeid, wt.name as wallettypename, wt.currencyid as currencyid, wt.wallettype as instancetype, wt.glaccountnumber as glaccountnumber, COALESCE(sum(wtx.debitamount),0) as debitamounttoday, COALESCE(sum(wtx.creditamount),0) as creditamounttoday
from wallettype wt left join wallettransactions wtx on wt.id = wtx.wallettypeid and date(wtx.createdon) = (date(today) -1)
group by wt.id),
temp_glsummary_total as
(SELECT * FROM (
SELECT wallettypeid, currencyid, instancetype, creditamount,debitamount,totalbalance, creditamounttoday,debitamounttoday,summarydate, ROW_NUMBER() OVER (PARTITION BY wallettypeid order by summarydate DESC) AS rn from glsummary where date(summarydate) < (date(today) -1)) sq WHERE sq.rn=1)
insert into public.glsummary
select wt.id, wt.currencyid, wt.wallettype, COALESCE(gtd.creditamounttoday,0)+ COALESCE(gtl.creditamount,0) as creditamount, COALESCE(gtd.debitamounttoday,0)+ COALESCE(gtl.debitamount,0) as debitamount, COALESCE(gtd.creditamounttoday,0) + COALESCE(gtl.creditamount,0) - COALESCE(gtd.debitamounttoday,0) - COALESCE(gtl.debitamount,0) as totalbalance, COALESCE(gtd.creditamounttoday,0) as creditamounttoday, COALESCE(gtd.debitamounttoday,0) as debitamounttoday,
(date(today) -1) as summarydate
from wallettype wt left join temp_glsummary_total as gtl on wt.id=gtl.wallettypeid
left join temp_glsummary_today gtd on gtd.wallettypeid = gtl.wallettypeid;
$procedure$
;

-- DROP FUNCTION public.loanscoringreport();

CREATE OR REPLACE FUNCTION public.loanscoringreport()
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare 
	table_record record;
begin 
	for table_record in select distinct userid from loan loop 
		raise notice 'Userid: %',table_record.userid;
		call loanscore(table_record.userid);
	end loop;
end
$function$
;

-- DROP FUNCTION public.new_uuid();

CREATE OR REPLACE FUNCTION public.new_uuid()
 RETURNS character varying
 LANGUAGE plpgsql
AS $function$

declare
   uuidString varchar;
begin
   SELECT uuid_in(overlay(overlay(md5(random()::text || ':' || clock_timestamp()::text) placing '4' from 13) placing to_hex(floor(random()*(11-8+1) + 8)::int)::text from 17)::cstring)  into  uuidString;
   return uuidString;
end;
$function$
;

