-- DROP PROCEDURE public.proc_loanscore();

CREATE OR REPLACE PROCEDURE public.proc_loanscore()
 LANGUAGE sql
AS $procedure$
TRUNCATE TABLE loansummary;

INSERT INTO loansummary(userid,
NMobileOpenLoan,
NMobileLoanEver,
NMobileLoanClosedL12M,
MSinceMobileLoanClosed,
NMaxDPDMobileLoanL12M,
NMaxDPDMobileLoanL6M,
NmobileLoansPast1M,
days_betn_loans,
createdOn,
modifiedOn,
nmobileloanspast3m,
nmobileloanspast12m,
nmobileloanspenalty12m,
nmobileloanclosed,
nmobileloansoverdue12m,
nmobileloanspast6m,
amobileloanspenalty3m,
amobileloanspenalty12m,
nmobileloansoverdue24m,
nmobileloanspast36m,
nriskcategorymedium24m
)
(WITH ln as (select distinct userid from loan)



SELECT distinct ln.userid, coalesce(q1.nMobileOpenLoan,0) as nmobileopenloan,
coalesce(q2.nmobileloanever,0) as nmobileloanever, coalesce(q3.nmobileloanclosedl12m,0) as nmobileloanclosedl12m, coalesce(q5.msincemobileloanclosed,0) as msincemobileloanclosed, coalesce(q7.nmaxdpdmobileloanl12m, 0) as nmaxdpdmobileloanl12m,
coalesce(q8.nmaxdpdmobileloanl6m,0) as nmaxdpdmobileloanl6m, coalesce(q20.nmobileloanspast1m,0) as nmobileloanspast1m, coalesce(q22.days_betn_loans,0) as days_betn_loans,
now() as createdon, now() as modifiedOn,
coalesce(q23.nmobileloanspast3m,0) as nmobileloanspast3m,coalesce(q24.nmobileloanspast12m,0) as nmobileloanspast12m,coalesce(q25.nmobileloanspenalty12m,0) as nmobileloanspenalty12m,coalesce(q26.nmobileloanclosed,0) as nmobileloanclosed,coalesce(q27.nmobileloansoverdue12m,0) as nmobileloansoverdue12m,coalesce(q28.nmobileloanspast6m,0) as nmobileloanspast6m,coalesce(q29.amobileloanspenalty3m,0) as amobileloanspenalty3m,coalesce(q30.amobileloanspenalty12m,0) as amobileloanspenalty12m,coalesce(q31.nmobileloansoverdue24m,0) as nmobileloansoverdue24m,coalesce(q32.nmobileloanspast36m,0) as nmobileloanspast36m,coalesce(q33.nriskcategorymedium24m,0) as nriskcategorymedium24m



FROM ln
LEFT OUTER JOIN
(Select userid, count(*) as nMobileOpenLoan from loan
WHERE loanstatus = 'ACTIVE' or loanstatus = 'WRITTEN_OFF' or loanstatus = 'CHARGE_OFF' GROUP BY userid) q1 on q1.userid = ln.userid
LEFT OUTER JOIN
(SELECT userid, count(*) as nmobileloanever from loan GROUP BY userid) q2 on q2.userid = ln.userid
LEFT OUTER JOIN
(SELECT userid, count(*) as nmobileloanclosedl12m from loan where loanstatus = 'CLOSED'
and date_part('day',now()-actualclosedate) < 365 GROUP BY userid) q3 on q3.userid = ln.userid
LEFT OUTER JOIN
(select userid, case when loanstatus <> 'CLOSED' then 0 else
ROUND(date_part('day', now()-modifiedon)/30) END as msincemobileloanclosed from loan order by createdon desc limit 1) q5 on q5.userid = ln.userid
LEFT OUTER JOIN
(select sq2.userid, max(sq2.days) as nmaxdpdmobileloanl12m from
(select userid, max(DATE_PART('day', actualclosedate - expectedFirstRepaymentDate)) AS days from loan
where loanstatus='CLOSED' and actualclosedate > expectedFirstRepaymentDate
and DATE_PART('day', NOW()- actualclosedate) <=365 GROUP BY userid
UNION ALL
select userid, max(DATE_PART('day', NOW() - expectedFirstRepaymentDate)) AS days from loan
where loanstatus<>'CLOSED'
and NOW() > expectedFirstRepaymentDate GROUP BY userid) AS sq2 GROUP BY sq2.userid) q7 on q7.userid = ln.userid
LEFT OUTER JOIN
(select userid, max(days) as nmaxdpdmobileloanl6m from
(select userid, max(DATE_PART('day', actualclosedate - expectedFirstRepaymentDate)) AS days from loan
where loanstatus='CLOSED' and actualclosedate > expectedFirstRepaymentDate
and DATE_PART('day', NOW()- actualclosedate) <=180 GROUP BY userid
UNION ALL
select userid, max(DATE_PART('day', NOW() - expectedFirstRepaymentDate)) AS days from loan
where loanstatus<>'CLOSED' and NOW() > expectedFirstRepaymentDate GROUP BY userid) AS sq3 GROUP BY sq3.userid) q8 on q8.userid = ln.userid
LEFT OUTER JOIN
(select userid, count(*) as nmobileloanspast1m from loan
where date_part('day', now()-createdon) < 30 GROUP BY userid) q20 on q20.userid = ln.userid
LEFT OUTER JOIN
(select sq5.userid, date_part('day', sq5.new_date- sq5.prev_date) as days_betn_loans from (
select sq4.userid, sq4.prev_date, sq4.new_date, ROW_NUMBER() OVER ( partition by sq4.userid order by sq4.createdon desc) as rowno from (
select lo.userid, lo.createdon, lag(lo.actualdisbursementdate) over (partition by lo.userid order by lo.createdon)
as prev_date, lo.actualdisbursementdate as new_date from loan lo order by createdon desc) as sq4) as sq5 where rowno=1) q22 on q22.userid = ln.userid
LEFT OUTER JOIN
(select userid, count(*) as nmobileloanspast3m from loan
where date_part('day', now()-createdon) < 90 GROUP BY userid) q23 on q23.userid = ln.userid
LEFT OUTER JOIN
(select userid, count(*) as nmobileloanspast12m from loan
where date_part('day', now()-createdon) < 365 GROUP BY userid) q24 on q24.userid = ln.userid
LEFT OUTER JOIN
(select userid, count(*) as nmobileloanspenalty12m from loan
where date_part('day', now()-createdon) < 365 and (chargesCharged is not null and chargesCharged > 0) GROUP BY userid) q25 on q25.userid = ln.userid
LEFT OUTER JOIN
(SELECT userid, count(*) as nmobileloanclosed from loan where loanstatus = 'CLOSED' GROUP BY userid) q26 on q26.userid = ln.userid
LEFT OUTER JOIN
(select userid,count(*) as nmobileloansoverdue12m from loan
where date_part('day', now()-createdon) < 365 and isOverdue='true' GROUP BY userid) q27 on q27.userid = ln.userid
LEFT OUTER JOIN
(select userid, count(*) as nmobileloanspast6m from loan
where date_part('day', now()-createdon) < 180 GROUP BY userid) q28 on q28.userid = ln.userid
LEFT OUTER JOIN
(select userid, sum(chargesCharged) as amobileloanspenalty3m from loan
where date_part('day', now()-createdon) < 90 GROUP BY userid) q29 on q29.userid = ln.userid
LEFT OUTER JOIN
(select userid, sum(chargesCharged) as amobileloanspenalty12m from loan
where date_part('day', now()-createdon) < 365 GROUP BY userid) q30 on q30.userid = ln.userid
LEFT OUTER JOIN
(select userid,count(*) as nmobileloansoverdue24m from loan
where date_part('day', now()-createdon) < 730 and isOverdue='true' GROUP BY userid) q31 on q31.userid = ln.userid
LEFT OUTER JOIN
(select userid, count(*) as nmobileloanspast36m from loan
where date_part('day', now()-createdon) < 1095 GROUP BY userid) q32 on q32.userid = ln.userid
LEFT OUTER JOIN
(select userid, count(*) as nriskcategorymedium24m from loan
where date_part('day', now()-createdon) < 730 and riskassessment in ('MEDIUM RISK','REPEAT MEDIUM RISK') GROUP BY userid) q33 on q33.userid = ln.userid);
$procedure$
;

